export default [{"path":"/","title":"Paneli","title_en":"Dashboard","section":"Pasqyra","perm":"core.read","keywords":["home","kpi"],"what":{"sq":"Faqja e parë: shifrat kryesore (stoku, shitjet, borxhet, miratimet) dhe lëvizjet e fundit të stokut.","en":"The start page: the key figures (stock, sales, debts, approvals) and the latest stock movements."},"steps":[{"sq":"Kliko një kartelë me shifër për të hapur faqen pas saj, p.sh. borxhet ose stokun.","en":"Click a figure card to open the page behind it, e.g. debts or stock."},{"sq":"Kliko \"Personalizo panelin\" për të zgjedhur cilat kartela dalin dhe me çfarë radhe; zgjedhjen e sheh vetëm ti.","en":"Click \"Choose cards\" to pick which cards show and in what order; only you see this choice."},{"sq":"Kur lart del shiriti \"gjëra për t'u kontrolluar në libra\", klikoje: të hap kontrollin e librave.","en":"When the \"things to check in the books\" strip shows on top, click it: it opens the books check."},{"sq":"\"Po mbarojnë\" tregon artikujt që ranë te pika e riporositjes; \"Shiko të gjitha\" hap listën e plotë.","en":"\"Running low\" shows items that dropped to the reorder point; \"View all\" opens the full list."}],"mistakes":[{"sq":"Vlera e stokut dhe lëvizjet janë me çmim blerjeje pa TVSH, jo me çmimin e shitjes.","en":"Stock value and movements are at purchase price without VAT, not at the selling price."},{"sq":"Në pamjen e thjeshtë këtu ke vetëm butona të mëdhenj: me \"Rregullo\" zgjedh cilët dalin.","en":"In the simple view this page has only big buttons: \"Arrange\" picks which ones show."}],"related":[{"href":"/approvals","label":"Për miratim"},{"href":"/check","label":"Kontrolli i librave"}]},{"path":"/approvals","title":"Për miratim","title_en":"Approvals","section":"Pasqyra","perm":"core.read","keywords":["approve","pending","inbox"],"what":{"sq":"Dokumentet që presin vendimin tënd: porosi, kërkesa blerjeje, rregullime stoku, pagesa. Kërkesat e tua nuk i miraton dot vetë.","en":"Documents waiting for your decision: orders, requisitions, stock adjustments, payments. You cannot approve your own requests."},"steps":[{"sq":"Te \"Në pritje\" sheh çka pret vendimin; kliko numrin për të parë dokumentin.","en":"Under \"Waiting\" see what waits for a decision; click the number to see the document."},{"sq":"Kliko \"Mirato\" ose \"Refuzo\"; te miratimi mund të shtosh një shënim.","en":"Click \"Approve\" or \"Reject\"; when approving you can add a note."},{"sq":"Kur refuzon, shkruaj patjetër arsyen: kërkuesi e sheh se çka duhet ndryshuar.","en":"When you reject, you must write the reason: the requester sees what to change."},{"sq":"Te \"Të vendosura\" sheh vendimet e mëparshme.","en":"Under \"Decided\" see the earlier decisions."}],"mistakes":[{"sq":"Te kërkesa jote del \"Kërkesa juaj\" pa butona: atë e miraton dikush tjetër.","en":"Your own request shows \"Your request\" without buttons: someone else approves it."},{"sq":"Cilat dokumente kërkojnë miratim dhe nga kush caktohet te Rregullat e miratimit.","en":"Which documents need approval, and by whom, is set in Approval workflows."}],"after":{"sq":"Kërkuesi njoftohet për vendimin. Nëse rregulli ka edhe një hap, njoftohet miratuesi i radhës; pas miratimit të fundit dokumenti vazhdon (p.sh. porosia rezervon mallin).","en":"The requester is notified of the decision. If the workflow has another step, the next approver is notified; after the last approval the document goes on (e.g. the order reserves stock)."},"related":[{"href":"/settings/workflows","label":"Rregullat e miratimit"},{"href":"/notifications","label":"Njoftimet"}]},{"path":"/tasks","title":"Detyrat","title_en":"Tasks","section":"Pasqyra","perm":"core.read","keywords":["detyrat","detyrë","punët","to do","todo","lista","kujtesa","projekt","task","kanban"],"what":{"sq":"Detyrat: çfarë duhet bërë, kush e bën dhe deri kur. Disa i shkruan ti, disa i krijon vetë programi (fatura të vonuara, diferenca në arkë, kontrata që mbarojnë).","en":"Tasks: what needs doing, by whom and by when. You write some; the program makes others by itself (late invoices, till differences, contracts ending)."},"steps":[{"sq":"Shkruaj detyrën në rreshtin sipër dhe shtyp Enter. \"nesër\", \"e premte\" ose \"15.11\" vendosin afatin; \"@Ilir\" personin; \"!lartë\" përparësinë.","en":"Type the task in the line at the top and press Enter. \"tomorrow\", \"friday\" or \"15.11\" set the date; \"@Ilir\" the person; \"!high\" the priority."},{"sq":"Kliko detyrën për ta hapur: pikat e kontrollit, nën-detyrat, komentet dhe fotot si provë.","en":"Click a task to open it: checklist, sub-tasks, comments and photos as proof."},{"sq":"Shenjo rrethin majtas kur e kryen. Ai që ta dha e merr vesh menjëherë.","en":"Tick the circle on the left when it is done. Whoever gave it to you hears at once."},{"sq":"Ndërro pamjen: Lista sipas afatit, Tabela sipas gjendjes, Kalendari, ose Ekipi për menaxherët.","en":"Switch the view: List by due date, Board by status, Calendar, or Team for managers."}],"mistakes":[{"sq":"Detyra të tjerëve u jep vetëm menaxheri; punëtori i shkruan detyrat e veta.","en":"Only a manager gives tasks to other people; staff write their own."},{"sq":"Detyra me drynin (private) e sheh vetëm ai që e shkroi.","en":"A task with the lock (private) is seen only by whoever wrote it."}],"after":{"sq":"Në orën 7 të mëngjesit secili njoftohet për detyrat e sotme dhe të nesërme, në program dhe në telefon.","en":"At 7 in the morning everyone hears about the tasks due today and tomorrow, in the app and on the phone."},"related":[{"href":"/tasks/setup","label":"Përsëritjet dhe automatiket"}]},{"path":"/training","title":"Trajnimi","title_en":"Training","section":"Pasqyra","perm":"core.read","keywords":["trajnimi","trajnim","mësime","udhëzime","si punon","ndihmë","help","tutorial","learn"],"what":{"sq":"Mësime të shkurtra sipas rolit tënd. Çdo mësim hap faqen e vërtetë, e shpjegon hap pas hapi dhe të tregon ku të klikosh.","en":"Short lessons for your role. Each one opens the real page, explains it step by step and shows you where to click."},"steps":[{"sq":"Kliko \"Fillo\" te mësimi i parë. Faqja hapet me shpjegimin anash.","en":"Click \"Start\" on the first lesson. The page opens with the explanation beside it."},{"sq":"Lexoje, provoje dhe kliko \"Mësimi u krye\".","en":"Read it, try it and click \"Lesson done\"."},{"sq":"Pronari sheh te Përdoruesit sa mësime ka kryer secili.","en":"The owner sees under Users how many lessons each person finished."}],"mistakes":[],"after":{"sq":"Te çdo faqe, ⓘ pranë titullit e hap të njëjtin shpjegim kur të duhet përsëri.","en":"On every page, the ⓘ next to the title opens the same explanation whenever you need it again."},"related":[]},{"path":"/accountant","title":"Klientët e mi","title_en":"My clients","section":"Pasqyra","perm":"core.read","keywords":["kontabilisti","kontabilist","accountant","klientët e kontabilistit","zyra e kontabilitetit"],"what":{"sq":"Për kontabilistin: çdo kompani që ua mban librat, me atë që pret në secilën.","en":"For the accountant: every company you keep the books of, with what waits in each one."},"steps":[{"sq":"Kërko kompaninë te \"Gjej një klient\"; ato me më shumë punë dalin të parat.","en":"Find the company with \"Find a client\"; those with the most work come first."},{"sq":"Kliko një etiketë (rreshta banke për t'u lidhur, kupona për t'u regjistruar, fatura në skicë…): hapet ajo kompani në faqen e duhur.","en":"Click a tag (bank lines to match, receipts to book, draft invoices…): that company opens at the right page."},{"sq":"Etiketa e TVSH-së ose e deklaratës së pagave tregon afatin; me të kuqe do të thotë që ka kaluar.","en":"The VAT or payroll declaration tag shows the deadline; red means it has passed."},{"sq":"Kliko \"Hap\" për të hyrë te financat e kompanisë.","en":"Click \"Open\" to go into the company's finance."}],"mistakes":[{"sq":"Kur hap një klient, programi kalon në atë kompani: shiko emrin lart para se të regjistrosh diçka.","en":"Opening a client switches the program to that company: check the name on top before you record anything."}],"related":[{"href":"/finance/bank","label":"Banka dhe arka"},{"href":"/tax","label":"Afatet e tatimeve"}]},{"path":"/notifications","title":"Njoftimet","title_en":"Notifications","section":"Pasqyra","perm":"core.read","keywords":["alerts","inbox","reminders","njoftime"],"what":{"sq":"Njoftimet: miratimet që të presin, afatet dhe gjërat që duan vëmendje në këtë kompani.","en":"Notifications: approvals waiting for you, deadlines and things that need attention in this company."},"steps":[{"sq":"Te \"Kutia hyrëse\" kliko një njoftim: hapet faqja ku duhet të veprosh dhe njoftimi shënohet si i lexuar.","en":"Under \"Inbox\" click a notification: the page where you need to act opens and it is marked as read."},{"sq":"Zgjidh një kategori majtas, ose ndiz \"Vetëm të palexuarat\".","en":"Choose a category on the left, or switch on \"Unread only\"."},{"sq":"\"Shëno të gjitha si të lexuara\" i pastron të gjitha njëherësh.","en":"\"Mark all as read\" clears them all at once."},{"sq":"Te \"Çfarë merrni\" fik kategoritë që s'të duhen: në aplikacion, në telefon ose me email.","en":"Under \"What you receive\" switch off the categories you do not need: in the app, on the phone or by email."}],"mistakes":[{"sq":"Njoftimet e miratimeve në aplikacion nuk fiken: ato duhen gjithmonë.","en":"Approval notifications in the app cannot be switched off: they are always needed."},{"sq":"Kopjet me email nisin të vijnë vetëm pasi administratori lidh shërbimin e postës.","en":"Email copies start arriving only once the administrator connects a mail service."}],"related":[{"href":"/approvals","label":"Për miratim"}]},{"path":"/sales/invoices","title":"Faturat","title_en":"Customer invoices","section":"Shitja","perm":"invoicing.read","keywords":["invoice","fatura","credit note","billing"],"what":{"sq":"Faturat e shitjes dhe notat e kreditit.","en":"Sales invoices and credit notes."},"steps":[{"sq":"Kliko \"Faturë e re\", zgjidh klientin dhe shto artikujt.","en":"Click \"New invoice\", choose the customer and add the items."},{"sq":"Filtro sipas statusit: \"Papaguar\" janë ato që duhen arkëtuar.","en":"Filter by status: \"Unpaid\" are the ones still to collect."},{"sq":"Për gabim në një faturë të kontabilizuar bëj \"Notë krediti\", jo fshirje.","en":"For a mistake on a posted invoice make a \"Credit note\", not a deletion."}],"mistakes":[],"related":[{"href":"/finance/receivables","label":"Borxhet"},{"href":"/sales/recurring","label":"Faturat mujore"}]},{"path":"/sales/quotes","title":"Ofertat","title_en":"Quotes","section":"Shitja","perm":"sales.read","keywords":["offer","proposal","estimate","oferta"],"what":{"sq":"Ofertat për klientët: çmime që i premton para porosisë.","en":"Quotes for customers: prices you promise before the order."},"steps":[{"sq":"Bëj ofertën dhe dërgoja klientit.","en":"Make the quote and send it to the customer."},{"sq":"Kur pranon, kliko \"Krijo porosinë\": nuk e shkruan dy herë.","en":"When they accept, click \"Create the order\": you do not type it twice."}],"mistakes":[],"related":[]},{"path":"/sales/orders","title":"Porositë","title_en":"Sales orders","section":"Shitja","perm":"sales.read","keywords":["so","orders","porosi"],"what":{"sq":"Porositë e klientëve: malli rezervohet, dërgohet dhe faturohet.","en":"Customer orders: the goods are reserved, delivered and invoiced."},"steps":[{"sq":"Konfirmo porosinë: kontrollohet kredia e klientit dhe rezervohet malli.","en":"Confirm the order: the customer's credit is checked and the goods are reserved."},{"sq":"Krijo dërgesën kur malli niset.","en":"Create the delivery when the goods leave."},{"sq":"Krijo faturën nga porosia.","en":"Create the invoice from the order."}],"mistakes":[],"related":[]},{"path":"/sales/deliveries","title":"Dërgesat","title_en":"Deliveries","section":"Shitja","perm":"sales.read","keywords":["shipping","dispatch","flete"],"what":{"sq":"Dërgesat: malli që del nga njësia për klientët. Kur përfundon dërgesa, malli zbret nga stoku.","en":"Deliveries: goods leaving the unit for customers. Completing a delivery takes the goods out of stock."},"steps":[{"sq":"Dërgesa krijohet nga porosia e konfirmuar me \"Krijo dërgesën\", ose nga \"Porositë në pritje\".","en":"A delivery is created from a confirmed order with \"Create delivery\", or from the \"Order desk\"."},{"sq":"Hape dërgesën dhe kontrollo sasitë dhe raftin te \"Merret nga\"; shto \"Numri i gjurmimit\" ose \"Shënime për shoferin\" kur duhen.","en":"Open the delivery and check the quantities and the shelf under \"Pick from\"; add a \"Tracking number\" or \"Notes for the driver\" when needed."},{"sq":"Kliko \"Gati për dërgim\" kur malli është përgatitur.","en":"Click \"Ready to ship\" when the goods are prepared."},{"sq":"Kur malli niset, kliko \"Përfundo dërgesën\".","en":"When the goods leave, click \"Complete delivery\"."}],"mistakes":[{"sq":"Për të dërguar më pak se porosia, ul sasinë: pjesa tjetër mbetet e rezervuar në porosi për një dërgesë tjetër.","en":"To send less than ordered, lower the quantity: the rest stays reserved on the order for a later delivery."}],"after":{"sq":"Stoku zbret, rezervimet e porosisë përdoren dhe kostoja e mallit regjistrohet në kontabilitet me koston mesatare. Fatura bëhet nga porosia.","en":"Stock goes down, the order's reservations are used up and the cost of the goods is booked at average cost. The invoice is made from the order."},"related":[{"href":"/sales/orders","label":"Porositë"},{"href":"/oms/fulfillment","label":"Porositë në pritje"}]},{"path":"/sales/recurring","title":"Faturat mujore","title_en":"Recurring invoices","section":"Shitja","perm":"invoicing.read","keywords":["rent","subscription","qira","abonim","monthly"],"what":{"sq":"Faturat mujore: qiraja, abonimet, mirëmbajtja. Bëhen vetë çdo mëngjes në ditën e tyre.","en":"Recurring invoices: rent, subscriptions, maintenance. They are made by themselves every morning on their day."},"steps":[{"sq":"Për të filluar, hap një faturë që përsëritet çdo muaj dhe kliko \"Përsërit\".","en":"To start one, open an invoice that comes back every month and click \"Repeat\"."},{"sq":"Zgjidh \"Sa shpesh\" (çdo muaj, çdo 2, 3, 6 muaj ose çdo vit) dhe \"Në ditën\" (1–28).","en":"Choose \"How often\" (every month, every 2, 3, 6 months or every year) and \"On day\" (1–28)."},{"sq":"Ndiz \"Postoji menjëherë\" që të kontabilizohen vetë; përndryshe çdo faturë pret si skicë që ta kontrollosh.","en":"Switch on \"Post them straight away\" to have them posted by themselves; otherwise each one waits as a draft for you to check."},{"sq":"Këtu, me \"Ndrysho\" ndërron datën e radhës ose fundin; me butonin e pauzës e ndal përkohësisht.","en":"Here, \"Edit\" changes the next date or the end; the pause button stops it for a while."}],"mistakes":[{"sq":"Rreshtat vijnë nga fatura e parë: për t'i ndryshuar, bëj faturë të re, përsërite atë dhe hiq planin e vjetër.","en":"The lines come from the first invoice: to change them, make a new invoice, repeat it and remove the old plan."},{"sq":"Shkruaj {period} në tekstin e rreshtit, p.sh. \"Qiraja {period}\", që në çdo faturë të dalë muaji.","en":"Write {period} in the line text, e.g. \"Rent {period}\", so each invoice shows its month."}],"after":{"sq":"Çdo faturë e bërë del te Faturat; kur kontabilizohet, shkon te Borxhet dhe në librin e shitjeve. Nëse një faturë nuk bëhet dot, arsyeja del te kolona \"Tjetra\".","en":"Each invoice made shows under Invoices; once posted it goes to Debts and the sales book. If one cannot be made, the reason shows in the \"Next\" column."},"related":[{"href":"/sales/invoices","label":"Faturat"}]},{"path":"/oms/fulfillment","title":"Porositë në pritje","title_en":"Order desk","section":"Shitja","perm":"sales.read","keywords":["oms","backorders","fulfilment","allocation","open orders","short"],"what":{"sq":"Çdo rresht i porosive të hapura: sa është rezervuar, sa ka të lirë dhe sa po vjen. Këtu rezervon, dërgon dhe porosit atë që mungon.","en":"Every open order line: what is reserved, free and on the way. Reserve, ship and order what is missing from here."},"steps":[{"sq":"Zgjidh njësinë lart, ose lëre \"Të gjitha njësitë\".","en":"Choose the unit on top, or leave \"All warehouses\"."},{"sq":"Kliko një kartelë lart (p.sh. \"Mund të rezervohet\" ose \"Mungesë\") për të parë vetëm ato rreshta.","en":"Click a card on top (e.g. \"Can reserve\" or \"Short\") to see only those lines."},{"sq":"Te porosia kliko \"Rezervo\" për të zënë mallin e lirë; kur gjithçka është gati, \"Krijo dërgesën\" (ose \"Dërgo të rezervuarat\" për pjesën që ka).","en":"On the order click \"Reserve\" to take the free stock; when everything is ready, \"Create delivery\" (or \"Deliver reserved\" for the part there is)."},{"sq":"Për rreshtat me \"Mungesë\" kliko \"Planifiko rifurnizimin\" dhe porosite te furnitori.","en":"For \"Short\" lines click \"Plan replenishment\" and order from the vendor."}],"mistakes":[{"sq":"\"Stoku i lirë\" me të kuqe do të thotë që është rezervuar më shumë se sa ka fizikisht: kontrollo stokun.","en":"\"Free stock\" in red means more is reserved than is on hand: check the stock."}],"after":{"sq":"Rezervimi e mban mallin vetëm për këtë porosi; \"Krijo dërgesën\" hap një dërgesë skicë, dhe stoku zbret kur ajo përfundon.","en":"Reserving keeps the goods for this order only; \"Create delivery\" opens a draft delivery, and stock goes down when it is completed."},"related":[{"href":"/sales/deliveries","label":"Dërgesat"},{"href":"/procurement/replenishment","label":"Çka duhet porositur"}]},{"path":"/partners?role=customer","title":"Klientët","title_en":"Customers","section":"Shitja","perm":"partners.read","keywords":["clients","partners","vendors","klient"],"what":{"sq":"Klientët dhe furnitorët: të dhënat, kushtet e pagesës, kartela dhe kujtesat.","en":"Customers and vendors: details, payment terms, card and reminders."},"steps":[{"sq":"Shto partnerin me NUI-në: të dhënat nga ARBK plotësohen kur gjenden.","en":"Add the partner with their NUI: the registry details fill in when found."},{"sq":"Cakto kushtet e pagesës dhe kufirin e kredisë.","en":"Set the payment terms and the credit limit."},{"sq":"Te \"Kartela\" sheh çdo faturë dhe pagesë; te \"Kujtesat\" sheh kujtesat e dërguara.","en":"Under \"Card\" see every invoice and payment; under \"Reminders\" the reminders sent."}],"mistakes":[],"related":[]},{"path":"/sales/price-lists","title":"Listat e çmimeve","title_en":"Price lists","section":"Shitja","perm":"sales.read","keywords":["pricing","wholesale","retail","discount"],"what":{"sq":"Listat e çmimeve: çmime shumicë, pakicë ose për një kanal, edhe sipas sasisë. Klienti me listë i merr vetë çmimet e duhura.","en":"Price lists: wholesale, retail or channel prices, also by quantity. A customer with a list gets the right prices automatically."},"steps":[{"sq":"Kliko \"Listë e re çmimesh\", jepi emër (p.sh. Shumicë) dhe zgjidh monedhën.","en":"Click \"New price list\", give it a name (e.g. Wholesale) and choose the currency."},{"sq":"Kliko \"Shto çmim\", zgjidh artikullin dhe shkruaj çmimin; \"Zbritja %\" është me dëshirë.","en":"Click \"Add price\", choose the item and type the price; \"Discount %\" is optional."},{"sq":"Për çmim më të lirë në sasi të madhe, shto të njëjtin artikull edhe një herë me \"Nga sasia\" më të madhe.","en":"For a lower price on bigger quantities, add the same item again with a higher \"From qty\"."},{"sq":"Lidhe listën me klientin te kartela e tij; \"Lista e parazgjedhur\" vlen për klientët pa listë.","en":"Give the list to the customer on their card; the \"Default list\" is for customers without one."}],"mistakes":[{"sq":"Shiko kolonën \"Marzhi\": nën 10% del me të kuqe, që të mos shesësh nën kosto pa e ditur.","en":"Watch the \"Margin\" column: under 10% shows red, so you do not sell below cost without knowing."},{"sq":"Ndiz \"Çmimet përfshijnë TVSH\" vetëm për listat e pakicës, ku çmimi në raft është përfundimtar.","en":"Switch on \"Prices include VAT\" only for retail lists, where the shelf price is final."}],"after":{"sq":"Dokumentet e reja të shitjes e marrin çmimin nga lista; ato të bëra më parë i mbajnë çmimet e tyre.","en":"New sales documents take their prices from the list; ones made earlier keep their prices."},"related":[{"href":"/partners?role=customer","label":"Klientët"},{"href":"/sales/promotions","label":"Promocionet"}]},{"path":"/sales/promotions","title":"Promocionet","title_en":"Promotions","section":"Shitja","perm":"sales.read","keywords":["promocion","promocione","aksion","zbritje","3 me 2","offer","sale","happy hour"],"what":{"sq":"Promocionet: zbritje për një kohë, me përqindje, me çmim të veçantë ose \"3 me 2\". Arka i zbaton vetë.","en":"Promotions: discounts for a time, as a percentage, a special price or \"3 for 2\". The till applies them by itself."},"steps":[{"sq":"Kliko \"Promocion i ri\" dhe zgjidh llojin: \"% zbritje\", \"Çmim i veçantë\" ose \"Bli disa, merr disa falas\".","en":"Click \"New promotion\" and choose the kind: \"% off\", \"A special price\" or \"Buy some, get some free\"."},{"sq":"Te \"Artikuj\" shto artikujt ose kategoritë; nëse s'zgjedh asnjë, vlen për çdo artikull.","en":"Under \"Items\" add the items or categories; if you choose none, it applies to every item."},{"sq":"Cakto datat, orët dhe ditët e javës (p.sh. vetëm të shtunën, nga ora 17 deri 19).","en":"Set the dates, the hours and the days of the week (e.g. only Saturday, from 5 to 7 pm)."},{"sq":"Te \"Ku\" zgjidh \"Në arkë\" dhe/ose \"Në dokumentet e shitjes\", pastaj kliko \"Ruaj\".","en":"Under \"Where\" tick \"On the till\" and/or \"On sales documents\", then click \"Save\"."},{"sq":"Te \"Rezultatet\" sheh sa zbritje u dha dhe sa u shit me secilin promocion.","en":"Under \"Results\" see how much discount was given and how much was sold with each promotion."}],"mistakes":[{"sq":"Për ta ndalur para kohe, hape promocionin dhe fik \"Aktiv\".","en":"To stop it early, open the promotion and switch off \"Active\"."}],"after":{"sq":"Arka e llogarit zbritjen vetë në kupon; dokumentet e shitjes e marrin si zbritje në rresht. Rezultatet llogariten nga kuponat e arkës.","en":"The till works out the discount on the receipt by itself; sales documents take it as the line discount. Results are counted from the till receipts."},"related":[{"href":"/pos/loyalty","label":"Kartat e zbritjes"},{"href":"/sales/price-lists","label":"Listat e çmimeve"}]},{"path":"/crm/leads","title":"Kontaktet","title_en":"Leads","section":"Shitja","perm":"crm.read","keywords":["prospects","enquiries","crm"],"what":{"sq":"Kontaktet: njerëz dhe firma që treguan interes. I kontrollon, pastaj i kthen në klient dhe në mundësi shitjeje.","en":"Leads: people and companies who showed interest. Check them, then turn them into a customer and a deal."},"steps":[{"sq":"Kliko \"Kontakt i ri\" dhe shkruaj për çfarë janë të interesuar, personin, telefonin dhe burimin.","en":"Click \"New lead\" and type what they are interested in, the contact person, the phone and the source."},{"sq":"Pasi të flasësh me ta, kliko \"Kontaktuar\"; kur sheh që janë blerës të vërtetë, \"I kualifikuar\".","en":"Once you have spoken to them, click \"Contacted\"; when you see they are real buyers, \"Qualified\"."},{"sq":"Kliko \"Konverto\" dhe zgjidh \"Krijo klient të ri\" ose \"Lidhe me një klient ekzistues\".","en":"Click \"Convert\" and choose \"Create a new customer\" or \"Link to an existing customer\"."},{"sq":"Nëse s'kanë interes, kliko \"Nuk është i interesuar\"; me \"Rihap\" e kthen prapë.","en":"If they are not interested, click \"Not interested\"; \"Reopen\" brings it back."}],"mistakes":[],"after":{"sq":"Konvertimi krijon një mundësi shitjeje në fazën e parë te Marrëveshjet, të lidhur me klientin.","en":"Converting creates a deal in the first stage of the Pipeline, linked to the customer."},"related":[{"href":"/crm/pipeline","label":"Marrëveshjet"}]},{"path":"/crm/pipeline","title":"Marrëveshjet","title_en":"Pipeline","section":"Shitja","perm":"crm.read","keywords":["opportunities","deals","crm","kanban"],"what":{"sq":"Marrëveshjet: mundësitë e shitjes që janë në punë, të ndara sipas fazave.","en":"Pipeline: the deals in progress, by stage."},"steps":[{"sq":"Kliko \"Mundësi e re shitjeje\", ose konverto një kontakt.","en":"Click \"New deal\", or convert a lead."},{"sq":"Tërhiqe kartelën nga një fazë te tjetra sa ecën bisedimi.","en":"Drag the card from one stage to the next as the talks move on."},{"sq":"Hape mundësinë dhe kliko \"Ofertë e re\" për t'i dërguar klientit ofertë.","en":"Open the deal and click \"New quote\" to send the customer an offer."},{"sq":"Në fund kliko \"Fituar\" ose \"Humbur\"; për të humburën zgjidh arsyen.","en":"At the end click \"Won\" or \"Lost\"; for a lost one, choose the reason."},{"sq":"\"Mundësitë e mia\" tregon vetëm tuat; \"Lista\" i shfaq si tabelë.","en":"\"My deals\" shows only yours; \"List\" shows them as a table."}],"mistakes":[],"after":{"sq":"Kur oferta e mundësisë kthehet në porosi, mundësia shënohet vetë si e fituar. Arsyet e humbjes dalin te raportet.","en":"When the deal's quote becomes an order, the deal is marked as won by itself. Lost reasons show in the reports."},"related":[{"href":"/crm/leads","label":"Kontaktet"},{"href":"/sales/quotes","label":"Ofertat"}]},{"path":"/agent","title":"Agjenti","title_en":"Agent app","section":"Shitja","perm":"sales.write","keywords":["agjent","terren","field","route","rruga","arkëtim","van","shitës","porosi"],"what":{"sq":"Aplikacioni i agjentit në telefon: rruga e ditës, porositë dhe arkëtimet te klienti, edhe pa internet.","en":"The agent's phone app: the day's route, orders and collections at the customer, also without internet."},"steps":[{"sq":"Shiko rrugën e sotme dhe kliko klientin që po viziton (ose përdor \"Kërko klientin\").","en":"Look at today's route and click the customer you are visiting (or use \"Search a customer\")."},{"sq":"Kliko \"Porosi e re\", shto artikujt, pastaj \"Shiko dhe dërgo\" dhe \"Dërgo porosinë\".","en":"Click \"New order\", add the items, then \"Review and send\" and \"Send the order\"."},{"sq":"Kur klienti paguan, kliko \"Arkëto\", shkruaj shumën dhe ruaje; pastaj \"Dërgo mandatin në WhatsApp\".","en":"When the customer pays, click \"Collect\", type the amount and save it; then \"Send the receipt on WhatsApp\"."},{"sq":"Nëse s'ka porosi, ruaje si \"Vizitë pa porosi\" me një shënim.","en":"If there is no order, save a \"Visit without an order\" with a note."}],"mistakes":[{"sq":"Pa internet vazhdo punën: çdo gjë ruhet në telefon dhe dërgohet vetë kur kthehet interneti.","en":"Without internet keep working: everything is kept on the phone and sent by itself when the internet is back."},{"sq":"Nëse s'je caktuar si agjent ose s'ke çantë parash, menaxheri të cakton te Agjentët.","en":"If you are not set up as an agent or have no cash bag, the manager sets you up under Field agents."}],"after":{"sq":"Porosia bëhet porosi shitjeje dhe konfirmohet vetë; zbritja e madhe ose klienti mbi kufirin e kredisë presin menaxherin. Paratë hyjnë në çantën tënde dhe mbyllin faturat më të vjetra të klientit.","en":"The order becomes a sales order and is confirmed by itself; a big discount or a customer over the credit limit waits for the manager. The cash goes into your bag and settles the customer's oldest invoices."},"related":[]},{"path":"/sales/agents","title":"Agjentët","title_en":"Field agents","section":"Shitja","perm":"sales.approve","keywords":["agjentët","terren","field sales","routes","visits","vizita","gps"],"what":{"sq":"Agjentët në terren: dita e tyre (vizitat, porositë, paratë) dhe rrugët që bëjnë.","en":"Field agents: their day (visits, orders, cash) and the routes they follow."},"steps":[{"sq":"Te \"Agjentët dhe rrugët\" kliko \"Cakto agjent\": zgjidh anëtarin, njësinë nga shet dhe çantën e parave.","en":"Under \"Agents and routes\" click \"Set up an agent\": choose the member, the unit they sell from and the cash bag."},{"sq":"Kliko \"Rruga\" te agjenti, shto me radhë klientët për çdo ditë të javës dhe kliko \"Ruaj rrugën\".","en":"Click \"Route\" on the agent, add the customers in order for each weekday and click \"Save the route\"."},{"sq":"Te \"Dita\" zgjidh datën: sheh çdo vizitë, porosi dhe arkëtim, me vendin në hartë.","en":"Under \"The day\" choose the date: see every visit, order and collection, with the place on the map."},{"sq":"Porositë me \"Pret ju\" presin vendimin tënd: hapi dhe konfirmoji.","en":"Orders marked \"Waits for you\" wait for your decision: open and confirm them."}],"mistakes":[{"sq":"Paratë e arkëtuara mbeten në çantën e agjentit derisa t'i dorëzojë: merri në sefin e dyqanit te faqja Sefi.","en":"Collected cash stays in the agent's bag until they hand it in: take it into the shop safe on the Safe page."},{"sq":"Vizita e regjistruar larg dyqanit të klientit del me ngjyrë portokalli: kontrolloje.","en":"A visit recorded far from the customer's shop shows in orange: check it."}],"related":[{"href":"/agent","label":"Agjenti"},{"href":"/safe","label":"Sefi"}]},{"path":"/ecommerce","title":"Dyqani online","title_en":"Web shop","section":"Shitja","perm":"ecommerce.read","keywords":["e-commerce","shopify","woocommerce","online orders","channels"],"what":{"sq":"Dyqani online: dyqanet në internet dhe tregjet online. Porositë e tyre vijnë këtu si porosi shitjeje dhe stoku u kthehet atyre.","en":"Web shop: online stores and marketplaces. Their orders arrive here as sales orders and stock levels go back to them."},"steps":[{"sq":"Kliko \"Shto kanal\", zgjidh platformën (Shopify, WooCommerce…), adresën e dyqanit dhe njësinë nga niset malli.","en":"Click \"Add channel\", choose the platform (Shopify, WooCommerce…), the store address and the unit it ships from."},{"sq":"Hape kanalin dhe kliko \"Lidh të gjitha sipas kodit\", që artikujt të përputhen me ato të dyqanit.","en":"Open the channel and click \"Link all by SKU\" so the items line up with the shop's."},{"sq":"Te \"Cilësimet\" zgjidh listën e çmimeve, klientin për porositë pa email dhe çka sinkronizohet; kliko \"Ruaj cilësimet\".","en":"Under \"Settings\" choose the price list, the customer for orders without an email and what is synced; click \"Save settings\"."},{"sq":"Me \"Dërgo një porosi prove\" e provon importin para se të nisë dyqani i vërtetë.","en":"With \"Send a test order\" try the import before the real shop starts."}],"mistakes":[{"sq":"Porosia që dështon e mban arsyen (p.sh. artikull i palidhur): rregulloje dhe kliko \"Provo përsëri\".","en":"A failed order keeps its reason (e.g. an unlinked item): fix it and click \"Retry\"."}],"after":{"sq":"Çdo porosi importohet vetëm një herë, si porosi shitjeje; gjendja e lirë e artikujve të lidhur i dërgohet dyqanit (\"Sinkronizo stokun tani\" e bën menjëherë).","en":"Each order is imported only once, as a sales order; the available stock of linked items is sent to the shop (\"Sync stock now\" does it at once)."},"related":[{"href":"/sales/orders","label":"Porositë"}]},{"path":"/pos","title":"Arka","title_en":"Point of sale","section":"Dyqani","perm":"pos.read","keywords":["pos","till","cashier","arka","z-report","register"],"what":{"sq":"Këtu janë arkat e dyqanit: hap një arkë për të shitur, shiko turnet dhe raportet Z të ditës.","en":"The shop's tills: open one to sell, and see the shifts and the day's Z reports."},"steps":[{"sq":"Kliko \"Shko te arka\" te arka ku punon.","en":"Click \"Go to the till\" on the till you work at."},{"sq":"Në fillim të ditës shkruaj sa para ka në sirtar dhe kliko \"Hap arkën\".","en":"At the start of the day, type the cash in the drawer and click \"Open the till\"."},{"sq":"Në fund të ditës mbyll turnin: numëro paratë dhe printo raportin Z.","en":"At the end of the day close the shift: count the cash and print the Z report."}],"mistakes":[{"sq":"Mos e lër arkën të hapur natën: shitjet e ditës tjetër përzihen me të sotmet.","en":"Do not leave the till open overnight: tomorrow's sales get mixed with today's."}],"after":{"sq":"Çdo turn i mbyllur bëhet raport Z dhe regjistrim në kontabilitet; diferenca e parave del te sefi.","en":"Each closed shift becomes a Z report and a book entry; any cash difference shows at the safe."},"related":[{"href":"/safe","label":"Sefi"},{"href":"/pos/loyalty","label":"Kartat e zbritjes"}]},{"path":"/safe","title":"Sefi","title_en":"Safe","section":"Dyqani","perm":"pos.approve|finance.read","keywords":["sefi","sef","kasaforta","cash","deposit","derdhje","para","count"],"what":{"sq":"Sefi: paratë që nxirren nga arkat, dorëzohen në bankë ose merren nga pronari.","en":"The safe: money taken from the tills, taken to the bank or by the owner."},"steps":[{"sq":"Kur mbyllet një turn, paratë e arkës kalojnë në sef.","en":"When a shift closes, the till's cash moves to the safe."},{"sq":"Për dorëzim në bankë ose marrje nga pronari regjistro lëvizjen me shumën dhe arsyen.","en":"For a bank deposit or the owner taking money, record the movement with the amount and the reason."},{"sq":"Numëro sefin rregullisht: diferenca regjistrohet dhe e sheh pronari.","en":"Count the safe regularly: a difference is recorded and the owner sees it."}],"mistakes":[],"after":{"sq":"Çdo lëvizje bëhet regjistrim në kontabilitet; paratë në rrugë për në bankë dalin te Banka dhe arka.","en":"Each movement is a book entry; money on its way to the bank shows under Bank and cash."},"related":[]},{"path":"/pos/checks","title":"Kontrollet ditore","title_en":"Daily checks","section":"Dyqani","perm":"pos.read|wms.read","keywords":["kontroll","kontrolli","checklist","listë kontrolli","higjiena","temperatura","frigorifer","hapja","mbyllja","hygiene","fridge"]},{"path":"/pos/atk","title":"Arkat në ATK","title_en":"Tills at ATK","section":"Dyqani","perm":"pos.approve|tax.read","keywords":["atk","fiskalizim","fiskal","kupon fiskal","certifikatë","certificate","qr","edi","kosova","softuer elektronik fiskal"]},{"path":"/pos/loyalty","title":"Kartat e zbritjes","title_en":"Loyalty cards","section":"Dyqani","perm":"pos.read","keywords":["kartela","zbritje","loyalty","points","pikë","besnikëri","discount card"],"what":{"sq":"Kartat e zbritjes: zbritje ose pikë për klientët, në çdo dyqan të kompanisë. Arka i zbaton vetë.","en":"Loyalty cards: a discount or points for customers, in every store of the company. The till applies them by itself."},"steps":[{"sq":"Te \"Llojet e kartelave\" kliko \"Lloj i ri kartele\" dhe zgjidh çfarë jep: zbritje, pikë ose zbritje për punëtorë.","en":"Under \"Types of card\" click \"New type of card\" and choose what it gives: a discount, points or a staff discount."},{"sq":"Te \"Kartelat\" kliko \"Kartelë e re\", zgjidh llojin, shkruaj emrin dhe telefonin e klientit dhe kliko \"Krijo kartelën\".","en":"Under \"Cards\" click \"New card\", choose the type, type the customer's name and phone and click \"Make the card\"."},{"sq":"Lëre bosh \"Numri i kartelës\" që ta bëjë programi, ose skano kartelën plastike që ke.","en":"Leave \"Card number\" empty for the program to make one, or scan a plastic card you have."},{"sq":"Kliko \"Printo kartelën\" për barkodin; te \"Raporti\" sheh zbritjet e dhëna dhe klientët më të mirë.","en":"Click \"Print card\" for the barcode; under \"Report\" see the discounts given and the best customers."}],"mistakes":[{"sq":"Kartelën e humbur hape dhe kliko \"Blloko\", që të mos e përdorë dikush tjetër.","en":"For a lost card, open it and click \"Block\" so nobody else uses it."},{"sq":"Te \"Jo për këto kategori\" hiq p.sh. cigaret ose mallin që është tashmë në ofertë.","en":"Under \"Not for these categories\" leave out e.g. cigarettes or goods already on offer."}],"after":{"sq":"Kur skanohet kartela në arkë, zbritja ose pikët llogariten vetë; arkëtari nuk jep dot zbritje kartele me dorë.","en":"When the card is scanned at the till, the discount or points are worked out by themselves; the cashier cannot give a card discount by hand."},"related":[{"href":"/pos","label":"Arka"},{"href":"/sales/promotions","label":"Promocionet"}]},{"path":"/pos/waiters","title":"Kamarierët","title_en":"Waiters","section":"Dyqani","perm":"pos.read","keywords":["kamarier","kamarierët","waiter","restaurant","tavolina","report"],"what":{"sq":"Kamarierët: llogaritë, tavolinat, mysafirët dhe xhiroja e secilit, me zbritjet dhe artikujt e anuluar pasi shkuan në kuzhinë.","en":"Waiters: bills, tables, guests and takings for each one, with the discounts and the items cancelled after they reached the kitchen."},"steps":[{"sq":"Zgjidh periudhën (\"Sot\", \"Dje\", \"Këtë javë\", \"Këtë muaj\") ose shkruaj datat te \"Nga\" dhe \"Deri\".","en":"Choose the period (\"Today\", \"Yesterday\", \"This week\", \"This month\") or type the dates under \"From\" and \"To\"."},{"sq":"Zgjidh dyqanin, ose lëre \"Të gjitha njësitë\".","en":"Choose the store, or leave \"All stores\"."},{"sq":"Krahaso kamarierët: xhiron për mysafir, zbritjet dhe kohën mesatare në tavolinë.","en":"Compare the waiters: takings per guest, discounts and the average table time."}],"mistakes":[{"sq":"Dalin vetëm llogaritë e paguara në tavolina nga ekrani i sallës, jo shitjet e zakonshme në arkë.","en":"Only bills paid at tables on the floor screen show up, not ordinary till sales."},{"sq":"Shiko kolonën \"Anuluar pas dërgimit\": anulimet e shpeshta pasi porosia shkoi në kuzhinë duan sqarim.","en":"Watch the \"Cancelled after sending\" column: frequent cancellations after the order reached the kitchen need explaining."}],"related":[]},{"path":"/manufacturing/boms","title":"Recetat","title_en":"Recipes","section":"Dyqani","perm":"manufacturing.read","keywords":["receta","recipe","kit","ingredients","përbërës","kafe","restorant"],"what":{"sq":"Recetat: nga çka përbëhet çdo produkt dhe si bëhet.","en":"Recipes: what each product is made of and how."},"steps":[{"sq":"Kliko \"Recetë e re\", zgjidh produktin që prodhon dhe sasinë e serisë.","en":"Click \"New recipe\", choose the product it makes and the batch quantity."},{"sq":"Shto përbërësit me sasinë për një seri; \"Firo %\" shton humbjen e pritur.","en":"Add the components with the quantity for one batch; \"Waste %\" adds the expected loss."},{"sq":"Shto hapat me qendrën e punës dhe minutat: nga to llogaritet kostoja e punës.","en":"Add the steps with the work center and minutes: the labour cost is worked out from them."},{"sq":"Zgjidh llojin: \"Prodhimi\" për urdhra pune, ose \"Set ose recetë: përbërësit dalin nga stoku kur shitet\".","en":"Choose the type: \"Production\" for work orders, or \"Kit or recipe: its parts leave stock when it is sold\"."}],"mistakes":[{"sq":"Fillo nga lëndët e para: së pari gjysmëproduktet, pastaj produktet që bëhen prej tyre.","en":"Start from the raw materials: semi-finished products first, then the products made from them."},{"sq":"Një produkt mund të ketë disa receta; përdoret ajo me \"Receta kryesore për këtë produkt\".","en":"A product can have several recipes; the one marked \"Main recipe for this product\" is used."}],"related":[{"href":"/manufacturing/work-centers","label":"Makinat dhe linjat"},{"href":"/manufacturing/orders","label":"Urdhrat e punës"}]},{"path":"/procurement/bills","title":"Faturat e blerjes","title_en":"Vendor bills","section":"Blerja","perm":"invoicing.read","keywords":["bill","ap","payable","three-way match","faturë blerje"],"what":{"sq":"Faturat e furnitorëve: me mall, pa mall (shërbime, shpenzime) dhe notat e kreditit.","en":"Vendor bills: with goods, without goods (services, expenses) and credit notes."},"steps":[{"sq":"Për faturë me mall përdor \"Fatura e blerjes me mall\".","en":"For a bill with goods use \"Purchase invoice with goods\"."},{"sq":"Për shërbim ose shpenzim (rrymë, qira) bëj faturë pa mall.","en":"For a service or an expense (electricity, rent) make a bill without goods."},{"sq":"Kliko një faturë për ta parë, paguar ose ndarë në këste.","en":"Click a bill to see it, pay it or split it into instalments."}],"mistakes":[],"related":[]},{"path":"/procurement/orders","title":"Porositë e blerjes","title_en":"Purchase orders","section":"Blerja","perm":"procurement.read","keywords":["po","buy","order","porosi blerje"],"what":{"sq":"Porositë e blerjes: çka ke porositur te furnitorët. Porositë e miratuara llogariten si mall në ardhje derisa të pranohen.","en":"Purchase orders: what you have ordered from vendors. Approved orders count as incoming stock until they are received."},"steps":[{"sq":"Kliko \"Porosi e re blerjeje\", ose bëje nga \"Çka duhet porositur\" ose nga një kërkesë blerjeje e miratuar.","en":"Click \"New purchase order\", or make it from Replenishment or from an approved requisition."},{"sq":"Filtro sipas statusit, furnitorit ose faturimit; data e pritshme që ka kaluar del si e vonuar.","en":"Filter by status, vendor or billing; an expected date that has passed shows as late."},{"sq":"Kliko një porosi për ta dërguar, për të pranuar mallin ose për të regjistruar faturën.","en":"Click an order to send it, receive the goods or enter the bill."}],"mistakes":[],"related":[{"href":"/procurement/replenishment","label":"Çka duhet porositur"},{"href":"/procurement/vendor-prices","label":"Çmimet e furnitorëve"}]},{"path":"/inventory/read-invoice","title":"Faturë nga fotoja","title_en":"Invoice from a photo","section":"Blerja","perm":"inventory.read","keywords":["ocr","scan","photo","foto","fatura","ai","pdf"],"what":{"sq":"Fatura nga fotoja: fotografo faturën e furnitorit ose zgjidh PDF-në; programi lexon furnitorin dhe rreshtat dhe gjen artikujt e tu.","en":"Invoice from a photo: photograph the vendor's invoice or choose its PDF; the program reads the vendor and the lines and finds your items."},"steps":[{"sq":"Kliko \"Bëj një foto\" ose \"Zgjidh një skedar\"; leximi zgjat rreth gjysmë minute.","en":"Click \"Take a photo\" or \"Choose a file\"; reading takes about half a minute."},{"sq":"Kontrollo furnitorin, numrin e faturës, datën dhe njësinë ku hyn malli.","en":"Check the vendor, the invoice number, the date and the unit the goods go into."},{"sq":"Në çdo rresht kontrollo artikullin që gjeti programi, sasinë dhe koston pa TVSH; rreshtit që s'e pranon hiqja shenjën.","en":"On each line check the item the program found, the quantity and the cost without VAT; untick a line you do not receive."},{"sq":"Kliko \"Bëj pranimin skicë\", pastaj kontrolloje dhe kontabilizoje pranimin.","en":"Click \"Make the draft receipt\", then check the receipt and post it."}],"mistakes":[{"sq":"Fotografo gjithë faqen, drejt dhe me dritë; PDF-ja nga furnitori lexohet më mirë.","en":"Photograph the whole page, flat and with light; a PDF from the vendor reads best."},{"sq":"Ka një numër faturash në muaj që lexohen; kur mbarojnë, prano mallin me dorë deri më 1 të muajit.","en":"There is a monthly number of invoices that can be read; when they run out, receive goods by hand until the 1st."}],"after":{"sq":"Krijohet një pranim malli skicë; malli hyn në stok vetëm kur ti e kontabilizon pranimin.","en":"A draft goods receipt is made; the goods enter stock only when you post the receipt."},"related":[{"href":"/inventory/receipts","label":"Pranimet"},{"href":"/procurement/invoice/new","label":"Faturë blerje"}]},{"path":"/inventory/landed-costs","title":"Dogana dhe transporti","title_en":"Landed costs","section":"Blerja","perm":"procurement.read","keywords":["customs","freight","import","clearance"],"what":{"sq":"Dogana dhe transporti: kostot e transportit, doganës dhe sigurimit që i shtohen kostos së mallit të pranuar, zakonisht pas zhdoganimit.","en":"Landed costs: transport, customs and insurance added to the cost of received goods, usually after customs clearance."},"steps":[{"sq":"Kliko \"Kosto e re mbërritjeje\", ose \"Shto koston e mbërritjes\" te pranimi i mallit.","en":"Click \"New landed cost\", or \"Add landed cost\" on the goods receipt."},{"sq":"Te \"Kostot\" kliko \"Shto kosto\" për çdo shpenzim (transport, taksë doganore…), pa TVSH.","en":"Under \"Charges\" click \"Add charge\" for each cost (freight, customs duty…), without VAT."},{"sq":"Zgjidh pranimet ku zbatohet kostoja dhe si ndahet te \"Shpërnda sipas\" (vlerës, sasisë, peshës…).","en":"Choose the receipts the cost applies to and how it is split under \"Split by\" (value, quantity, weight…)."},{"sq":"Për import plotëso \"Deklarata doganore\": numrin e DUD-it dhe TVSH-në e paguar në kufi.","en":"For an import fill in \"Customs declaration\": the DUD number and the VAT paid at the border."},{"sq":"Kliko \"Shpërnda dhe regjistro\".","en":"Click \"Spread and record\"."}],"mistakes":[{"sq":"Pranimi i mallit duhet të jetë i kontabilizuar para se t'i shtosh koston.","en":"The goods receipt must be posted before you add its cost."}],"after":{"sq":"Pjesa për mallin që është ende në stok rrit koston mesatare; pjesa për mallin e shitur kalon në shpenzime. TVSH e importit shkon në librin e blerjeve, jo në vlerën e stokut.","en":"The share for goods still in stock raises their average cost; the share for goods already sold is booked as an expense. Import VAT goes to the purchase book, not into the stock value."},"related":[{"href":"/inventory/receipts","label":"Pranimet"}]},{"path":"/partners?role=vendor","title":"Furnitorët","title_en":"Vendors","section":"Blerja","perm":"partners.read","keywords":["suppliers","furnitor"],"what":{"sq":"Klientët dhe furnitorët: të dhënat, kushtet e pagesës, kartela dhe kujtesat.","en":"Customers and vendors: details, payment terms, card and reminders."},"steps":[{"sq":"Shto partnerin me NUI-në: të dhënat nga ARBK plotësohen kur gjenden.","en":"Add the partner with their NUI: the registry details fill in when found."},{"sq":"Cakto kushtet e pagesës dhe kufirin e kredisë.","en":"Set the payment terms and the credit limit."},{"sq":"Te \"Kartela\" sheh çdo faturë dhe pagesë; te \"Kujtesat\" sheh kujtesat e dërguara.","en":"Under \"Card\" see every invoice and payment; under \"Reminders\" the reminders sent."}],"mistakes":[],"related":[]},{"path":"/procurement/vendor-prices","title":"Çmimet e furnitorëve","title_en":"Vendor prices","section":"Blerja","perm":"procurement.read","keywords":["vendor price list","supplier prices","lead time","moq"],"what":{"sq":"Çmimet e furnitorëve: sa kushton artikulli te secili furnitor, porosia minimale dhe koha e dorëzimit.","en":"Vendor prices: what each vendor charges for an item, their minimum order and delivery time."},"steps":[{"sq":"Kliko \"Shto çmim\", zgjidh furnitorin dhe artikullin.","en":"Click \"Add price\", choose the vendor and the item."},{"sq":"Shkruaj çmimin pa TVSH, porosinë minimale dhe kohën e dorëzimit në ditë.","en":"Type the price without VAT, the minimum order and the delivery time in days."},{"sq":"Ndiz \"Furnitori i preferuar\" te furnitori nga i cili blen zakonisht atë artikull.","en":"Switch on \"Preferred vendor\" for the vendor you usually buy that item from."}],"mistakes":[{"sq":"Një furnitor ka vetëm një çmim për artikull: ndrysho atë që ekziston, mos shto tjetër.","en":"A vendor has only one price per item: edit the existing one rather than adding another."}],"after":{"sq":"Porositë e blerjes e marrin çmimin nga këtu; rifurnizimi zgjedh furnitorin e preferuar dhe respekton porosinë minimale.","en":"Purchase orders take their price from here; replenishment picks the preferred vendor and respects the minimum order."},"related":[{"href":"/procurement/replenishment","label":"Çka duhet porositur"}]},{"path":"/procurement/scorecard","title":"Karta e furnitorëve","title_en":"Vendor scorecard","section":"Blerja","perm":"procurement.read","keywords":["scorecard","karta","vlerësimi","furnitor","on time","në kohë","vonesa","supplier rating","performance"]},{"path":"/procurement/replenishment","title":"Çka duhet porositur","title_en":"Replenishment","section":"Blerja","perm":"procurement.read","keywords":["reorder","mrp","suggestions","restock"],"what":{"sq":"Çka duhet porositur: artikujt që ranë te pika e riporositjes ose poshtë saj, me sasinë e propozuar deri te maksimumi.","en":"Replenishment: items at or below their reorder point, with the suggested quantity up to the maximum."},"steps":[{"sq":"Kliko \"Kontrollo stokun tani\" që programi të llogarisë çka duhet porositur.","en":"Click \"Check stock now\" for the program to work out what needs ordering."},{"sq":"Kontrollo sasinë dhe furnitorin në çdo rresht; ndryshoji nëse duhet.","en":"Check the quantity and the vendor on each line; change them if needed."},{"sq":"Zgjidh rreshtat dhe kliko \"Krijo porosi blerjeje\" (ose \"Krijo transferime\" kur malli merret nga një njësi tjetër).","en":"Tick the lines and click \"Create purchase orders\" (or \"Create transfers\" when the goods come from another unit)."},{"sq":"Rreshtat që s'të duhen hiqi me \"Hidh poshtë\".","en":"Remove the lines you do not need with \"Dismiss\"."}],"mistakes":[{"sq":"Pika e riporositjes (min/maks) caktohet për çdo artikull dhe njësi te faqja e produktit: pa të, artikulli nuk del këtu.","en":"The reorder point (min/max) is set per item and unit on the product page: without it the item does not show here."}],"after":{"sq":"Krijohen porosi blerjeje skicë, një për çdo furnitor; ti i kontrollon dhe i dërgon. Me \"Rifurnizim automatik\" kjo bëhet vetë çdo ditë.","en":"Draft purchase orders are made, one per vendor; you review and submit them. With \"Automatic replenishment\" this happens every day by itself."},"related":[{"href":"/procurement/vendor-prices","label":"Çmimet e furnitorëve"},{"href":"/procurement/orders","label":"Porositë e blerjes"}]},{"path":"/procurement/requisitions","title":"Kërkesat për blerje","title_en":"Requisitions","section":"Blerja","perm":"requisitions.read","keywords":["request","purchase request","pr","kërkesë"],"what":{"sq":"Kërkesat për blerje: dikush kërkon diçka, blerjet e miratojnë dhe e porositin te furnitori i duhur.","en":"Requisitions: someone asks for something, purchasing approves it and orders it from the right vendor."},"steps":[{"sq":"Kliko \"Kërkesë e re blerjeje\", zgjidh njësinë, \"Duhet deri më\" dhe shkruaj për çfarë duhet.","en":"Click \"New requisition\", choose the unit, \"Needed by\" and write what it is for."},{"sq":"Kliko \"Shto artikull\": zgjidh produktin nga katalogu ose përshkruaj çfarë duhet.","en":"Click \"Add item\": choose a product from the catalogue or describe what is needed."},{"sq":"Kliko \"Dërgo për miratim\"; blerjet njoftohen.","en":"Click \"Submit for approval\"; purchasing is notified."},{"sq":"Pas miratimit, blerjet klikojnë \"Krijo porosi blerjeje\": del një porosi skicë për çdo furnitor.","en":"Once approved, purchasing clicks \"Create purchase orders\": one draft order per vendor."}],"mistakes":[{"sq":"Kërkesën tënde nuk e miraton dot vetë.","en":"You cannot approve your own requisition."},{"sq":"Nëse refuzohet, lexo arsyen, kliko \"Ndrysho përsëri\" dhe dërgoje prapë.","en":"If it is rejected, read the reason, click \"Edit again\" and submit it again."}],"related":[{"href":"/procurement/orders","label":"Porositë e blerjes"},{"href":"/approvals","label":"Për miratim"}]},{"path":"/procurement/rfqs","title":"Ofertat nga furnitorët","title_en":"Offers from vendors","section":"Blerja","perm":"procurement.read","keywords":["rfq","oferta","ofertë","tender","krahasim","quotation","compare offers","kërkesë për ofertë"]},{"path":"/inventory/products","title":"Artikujt","title_en":"Products","section":"Stoku","perm":"inventory.read","keywords":["items","sku","variants","barcode"],"what":{"sq":"Lista e artikujve: çmimet, kostot dhe sa ka në stok.","en":"The list of items: prices, costs and what is in stock."},"steps":[{"sq":"Kliko \"Produkt i ri\" për një artikull të ri; mjafton barkodi, emri dhe çmimi.","en":"Click \"New product\" for a new item; the barcode, name and price are enough."},{"sq":"Kliko një artikull për ta parë ose ndryshuar: çmimet, barkodet, paketimet, pika e riporositjes.","en":"Click an item to see or change it: prices, barcodes, packs, reorder point."},{"sq":"Me \"Importo\" sjell shumë artikuj njëherësh nga Excel-i.","en":"With \"Import\" bring many items at once from Excel."}],"mistakes":[{"sq":"Mos krijo dy artikuj me të njëjtin barkod: skanimi do të gjejë vetëm njërin.","en":"Do not create two items with the same barcode: a scan finds only one."}],"related":[{"href":"/inventory/stock","label":"Gjendja"},{"href":"/inventory/levelling","label":"Nivelimi i çmimeve"}]},{"path":"/inventory/stock","title":"Gjendja","title_en":"Stock levels","section":"Stoku","perm":"inventory.read","keywords":["on hand","available","reserved","valuation"],"what":{"sq":"Sa ka nga çdo artikull, në cilën njësi, dhe sa vlen.","en":"How much of each item there is, in which unit, and what it is worth."},"steps":[{"sq":"Filtro sipas njësisë ose kategorisë.","en":"Filter by unit or category."},{"sq":"\"E rezervuar\" është malli i premtuar në porosi; \"e lirë\" është ajo që mund të shitet.","en":"\"Reserved\" is promised on orders; \"available\" is what can still be sold."},{"sq":"Kliko artikullin për kartelën: çdo hyrje dhe dalje me datë.","en":"Click an item for its card: every movement in and out by date."}],"mistakes":[],"related":[]},{"path":"/inventory/check","title":"Kontrollo artikullin","title_en":"Check item","section":"Stoku","perm":"inventory.read","keywords":["zebra","scanner","skano","kontrollo","ku ka","where is","stock in stores","njësitë","dyqanet","gjendja","transfer"],"what":{"sq":"Skano një artikull dhe shiko sa ka çdo dyqan dhe magazinë. Kur njësisë sate i mungon, programi të tregon nga cila njësi ta marrësh dhe sa.","en":"Scan an item and see how much every store and warehouse has. When your unit is short, the program tells you which unit to take it from and how much."},"steps":[{"sq":"Lart djathtas zgjidh \"Njësia ime\" (dyqani ku je). Programi e mban mend në këtë pajisje.","en":"Top right, choose \"My unit\" (the store you are in). The device remembers it."},{"sq":"Skano artikullin me Zebra, me kamerën e telefonit, ose shkruaj emrin e tij.","en":"Scan the item with the Zebra, the phone camera, or type its name."},{"sq":"Lexo sugjerimin: \"Merr 36 nga Market Ulpiana\". Ajo njësi jep vetëm atë që ka mbi minimumin e vet, që të mos mbetet vetë pa mall.","en":"Read the suggestion: \"Take 36 from Market Ulpiana\". That unit gives only what it has above its own minimum, so it does not run short itself."},{"sq":"Shtyp \"Kërko nga …\", kontrollo sasinë dhe dërgoje. Njerëzit e asaj njësie njoftohen menjëherë.","en":"Press \"Ask … for it\", check the quantity and send it. The people of that unit are told right away."}],"mistakes":[{"sq":"Pa minimum dhe maksimum (te artikulli → \"Pikat e porosisë\") programi e vlerëson sasinë nga shitjet e 2 javëve. Vendosini për artikujt kryesorë dhe sugjerimet bëhen të sakta.","en":"Without a minimum and maximum (on the item → \"Reorder points\") the program estimates from two weeks of sales. Set them for the main items and the suggestions become exact."},{"sq":"Në Zebra, te DataWedge, ndizni \"Send ENTER\" që çdo skanim të kërkohet vetë.","en":"On the Zebra, in DataWedge, switch on \"Send ENTER\" so every scan is looked up by itself."}],"after":{"sq":"Kërkesa shfaqet te Transferimet. Njësia që e ka e dërgon, dhe njësia jote e numëron kur arrin. Arka gjithashtu tregon kur një artikull mbaron: \"e ka: Market Ulpiana 140\".","en":"The request appears under Transfers. The unit that has it sends it, and your unit counts it when it arrives. The till also tells you when an item runs out: \"has it: Market Ulpiana 140\"."},"related":[{"href":"/inventory/transfers","label":"Transferimet"},{"href":"/procurement/replenishment","label":"Furnizimi"}]},{"path":"/inventory/abc","title":"Klasifikimi ABC","title_en":"ABC-XYZ classification","section":"Stoku","perm":"inventory.read","keywords":["abc","xyz","pareto","klasifikimi","kategorizimi","klasa","analiza abc","dead stock","pa lëvizje","mall i ndenjur"],"what":{"sq":"Klasifikimi ABC: cilët artikuj e mbajnë biznesin. A janë pak artikuj që bëjnë 80 % të vlerës që del nga stoku, B 15 % e radhës, C shumica e artikujve me pak vlerë.","en":"ABC classification: which items carry the business. A are the few items making 80 % of the value that leaves the stock, B the next 15 %, C most items with little value."},"steps":[{"sq":"Kliko një klasë (A, B ose C) për të parë artikujt e saj, më të vlefshmit së pari.","en":"Tap a class (A, B or C) to see its items, the most valuable first."},{"sq":"Zgjidh lart një njësi për ta parë klasifikimin vetëm të atij dyqani.","en":"Pick a unit at the top to see the classification of that store alone."},{"sq":"Te \"Në stok, por pa shitje\" zgjidh periudhën (30, 60, 90, 180 ditë, një vit, ose që nga një datë) dhe shiko çka nuk është shitur dhe sa para rrinë në raft.","en":"Under \"In stock, but not sold\" choose the period (30, 60, 90, 180 days, a year, or since a date) and see what has not sold and how much money stands on the shelf."},{"sq":"Te \"Rregullat\" ndrysho pragjet (80/95 %), sa shpesh numërohet çdo klasë, dhe nëse do, ndiz XYZ (sa rregullisht shiten artikujt).","en":"Under \"Rules\" change the limits (80/95 %), how often each class is counted and, if you want, switch on XYZ (how regularly items sell)."}],"mistakes":[{"sq":"Një artikull i ri ka pak histori: klasa e tij bëhet e saktë pas disa javësh shitje.","en":"A new item has little history: its class becomes accurate after some weeks of sales."}],"after":{"sq":"Klasifikimi bëhet vetë çdo të hënë. Te Numërimet, programi tregon çka është me radhë (A çdo muaj, B çdo 3 muaj, C një herë në vit) dhe e krijon numërimin me një klik.","en":"Items are classified by themselves every Monday. Under Stock counts, the program shows what is due (A monthly, B every 3 months, C yearly) and makes the count in one click."},"related":[{"href":"/wms/counts","label":"Inventarizimi"},{"href":"/inventory/check","label":"Kontrollo artikullin"}]},{"path":"/inventory/item-card","title":"Kartela e artikullit","title_en":"Item card","section":"Stoku","perm":"inventory.read","keywords":["kartela","kartela e artikullit","item ledger","stock card","lëvizjet","movements","ledger","history"],"what":{"sq":"Kartela e artikullit: çdo hyrje dhe dalje, me gjendjen pas secilës.","en":"The item card: every movement in and out, with the stock after each."},"steps":[{"sq":"Zgjidh artikullin dhe periudhën.","en":"Choose the item and the period."},{"sq":"Kliko një rresht për dokumentin që e shkaktoi (faturë, pranim, shitje në arkë).","en":"Click a line to open the document behind it (bill, receipt, till sale)."}],"mistakes":[],"related":[]},{"path":"/inventory/alerts","title":"Po mbarojnë","title_en":"Low stock","section":"Stoku","perm":"inventory.read","keywords":["reorder","alerts","replenish"],"what":{"sq":"Artikujt që kanë rënë te pika e riporositjes ose më poshtë, me sasinë që duhet porositur.","en":"Items at or below their reorder point, with the quantity to order."},"steps":[{"sq":"Filtro sipas njësisë për të parë çka po mbaron në secilin dyqan ose depo.","en":"Filter by unit to see what is running low in each shop or depot."},{"sq":"\"Porosia e sugjeruar\" e mbush njësinë deri te maksimumi, pa atë që është tashmë \"Në ardhje\".","en":"\"Suggested order\" fills the unit up to its maximum, minus what is already \"Incoming\"."},{"sq":"Kliko \"Shëno si të parë\" kur e ke marrë parasysh sinjalizimin.","en":"Click \"Mark as seen\" once you have dealt with the alert."},{"sq":"Për ta porositur hap \"Rifurnizim\" poshtë tabelës; kur vjen malli, kliko \"Prano mallin\".","en":"To order it, open \"Replenishment\" under the table; when the goods arrive, click \"Receive goods\"."}],"mistakes":[{"sq":"Artikulli del këtu vetëm nëse ka pikë riporositjeje: caktoje te artikulli me \"Shto pikë riporositjeje\".","en":"An item shows here only if it has a reorder point: set one on the item with \"Add reorder point\"."}],"after":{"sq":"Kur stoku i lirë ngrihet mbi pikën e riporositjes (p.sh. pas një pranimi), artikulli del nga lista.","en":"When the available stock rises above the reorder point (for example after a receipt), the item leaves the list."},"related":[{"href":"/procurement/replenishment","label":"Çka duhet porositur"},{"href":"/inventory/stock","label":"Gjendja"}]},{"path":"/wms/lots","title":"Afatet e skadimit","title_en":"Lots & expiry","section":"Stoku","perm":"inventory.read","keywords":["batch","serial","traceability","recall","fefo","expiry"],"what":{"sq":"Çdo lot dhe numër serik: kur skadon, sa ka në stok dhe kujt i shkoi.","en":"Every lot and serial number: when it expires, how much is in stock and who received it."},"steps":[{"sq":"Shiko kartat lart: \"Të skaduara, ende në stok\" duhen hequr nga raftet menjëherë.","en":"Look at the cards on top: \"Expired, still in stock\" must come off the shelves now."},{"sq":"Filtro sipas \"Afati i ruajtjes\" ose \"Stoku\"; në fillim dalin vetëm lotet që janë \"Në stok\".","en":"Filter by \"Shelf life\" or \"Stock\"; at first only the lots \"In stock\" are shown."},{"sq":"Kliko një lot për rrugën e tij: nga erdhi, ku lëvizi dhe \"Kush e mori\".","en":"Click a lot for its path: where it came from, where it moved and \"Who received it\"."},{"sq":"Nëse duhet tërhequr malli, te loti kliko \"Lista e tërheqjes\": shkarkon klientët dhe sasitë.","en":"If the goods must be recalled, click \"Recall list\" on the lot: it downloads the customers and quantities."}],"mistakes":[{"sq":"Lotet krijohen vetëm kur pranon artikuj që ndiqen me lot; artikujt pa lot nuk dalin këtu.","en":"Lots are created only when you receive items tracked by lot; items without lots do not show here."}],"after":{"sq":"Mbledhja, vendosja në raft dhe arka marrin së pari lotet që skadojnë më herët; lotet e skaduara nuk rezervohen për porosi.","en":"Picking, putting away and the till take the lots that expire first; expired lots are never reserved for orders."},"related":[{"href":"/inventory/receipts","label":"Pranimet"}]},{"path":"/inventory/receipts","title":"Pranimet","title_en":"Goods receipts","section":"Stoku","perm":"inventory.read","keywords":["grn","receive","import"],"what":{"sq":"Pranimet e mallit: malli që vjen nga furnitorët, nga importi ose si kthim nga klientët.","en":"Goods receipts: goods coming in from vendors, imports or customer returns."},"steps":[{"sq":"Kliko \"Prano mallin\" për një pranim të ri, me ose pa porosi blerjeje.","en":"Click \"Receive goods\" for a new receipt, with or without a purchase order."},{"sq":"Nëse e ke këtë mundësi, \"Fatura nga fotoja\" e lexon faturën dhe e plotëson për ty.","en":"If you have it, \"Invoice from a photo\" reads the invoice and fills it in for you."},{"sq":"Filtro sipas statusit (\"Skicë\" janë të pakryerat) ose te \"Dogana\" për importet që presin zhdoganimin.","en":"Filter by status (\"Draft\" are not done yet) or by \"Customs\" for imports waiting for clearance."},{"sq":"Kliko një pranim për ta hapur, kontrolluar dhe kryer.","en":"Click a receipt to open, check and complete it."}],"mistakes":[],"after":{"sq":"Vetëm pranimi i kryer e shton stokun dhe rillogarit koston mesatare; skicat nuk ndryshojnë asgjë.","en":"Only a completed receipt adds the stock and recalculates the average cost; drafts change nothing."},"related":[{"href":"/procurement/orders","label":"Porositë e blerjes"},{"href":"/inventory/landed-costs","label":"Dogana dhe transporti"}]},{"path":"/inventory/transfers","title":"Transferet","title_en":"Transfers","section":"Stoku","perm":"inventory.read","keywords":["move","warehouse"],"what":{"sq":"Transferet: malli që kalon nga një njësi në tjetrën, ose nga një raft në tjetrin.","en":"Transfers: goods moving from one unit to another, or from one shelf to another."},"steps":[{"sq":"Kliko \"Transferim i ri\" dhe zgjidh nga ku dhe ku shkon malli.","en":"Click \"New transfer\" and choose where the goods come from and where they go."},{"sq":"Te \"Vëmendje\" sheh kërkesat nga dyqanet, mallin \"Në rrugë mbi një ditë\" dhe ato \"Pranuar me diferenca\".","en":"Under \"Attention\" see requests from shops, goods \"On the road over a day\" and those \"Received with differences\"."},{"sq":"Kliko një transfer që është në rrugë për ta numëruar dhe pranuar te njësia pranuese.","en":"Click a transfer on the road to count and receive it at the receiving unit."}],"mistakes":[],"after":{"sq":"Vlera e stokut nuk ndryshon: malli vetëm ndërron vend. Edhe lëvizjet nga skaneri (\"Lëviz mallin\") dalin këtu.","en":"The stock value does not change: the goods only change place. Moves from the scanner (\"Move stock\") show here too."},"related":[{"href":"/wms/move","label":"Lëviz mallin"}]},{"path":"/inventory/adjustments","title":"Rregullimet e stokut","title_en":"Adjustments","section":"Stoku","perm":"inventory.read","keywords":["opening","write-off","damage"],"what":{"sq":"Rregullimet e stokut: gjendja fillestare, korrigjimet, dëmtimet dhe humbjet.","en":"Stock adjustments: opening stock, corrections, damage and losses."},"steps":[{"sq":"Kliko \"Rregullim i ri\" dhe zgjidh arsyen.","en":"Click \"New adjustment\" and choose the reason."},{"sq":"Filtro sipas \"Arsyeja\" ose statusit; \"Pret miratim\" janë ato që i pret menaxheri.","en":"Filter by \"Reason\" or status; \"Pending approval\" are the ones waiting for the manager."},{"sq":"Kliko një rregullim për ta hapur ose kryer.","en":"Click an adjustment to open or complete it."}],"mistakes":[{"sq":"Për numërimin e gjithë raftit përdor \"Inventarizimi\": ai i bën vetë rregullimet nga diferencat.","en":"To count a whole shelf use \"Stock count\": it makes the adjustments from the differences itself."}],"after":{"sq":"Çdo rregullim i kryer ndryshon stokun dhe vlerën e tij në kontabilitet; arsyeja del te Humbjet dhe firot.","en":"Each completed adjustment changes the stock and its value in the books; the reason shows in Shrinkage."},"related":[{"href":"/wms/counts","label":"Inventarizimi"},{"href":"/inventory/shrinkage","label":"Humbjet dhe firot"}]},{"path":"/wms/counts","title":"Inventarizimi","title_en":"Cycle counts","section":"Stoku","perm":"wms.read","keywords":["inventory count","stocktake","inventarizim","inventarizimi","numërimi","regjistrimi i mallit"],"what":{"sq":"Numërimi i stokut (inventarizimi): numëron raftet dhe programi gjen diferencat. Dyqani nuk mbyllet: çdo rresht krahasohet me stokun në minutën kur u numërua, kështu shitjet gjatë numërimit nuk e prishin rezultatin.","en":"Stock counting: count the shelves and the program finds the differences. The shop stays open: each line is compared with the stock at the minute it was counted, so sales during the count do not spoil the result."},"steps":[{"sq":"Kliko \"Numërim i ri\", zgjidh njësinë dhe raftet ose kategorinë.","en":"Click \"New count\", choose the unit and the shelves or a category."},{"sq":"Numëro me skaner, me dorë, ose printo fletën dhe fute nga Excel-i.","en":"Count with a scanner, by hand, or print the sheet and bring it in from Excel."},{"sq":"Kliko \"Përfundo numërimin\", shiko vlerën e diferencave dhe konfirmo.","en":"Click \"Finish counting\", see the value of the differences and confirm."}],"mistakes":[{"sq":"Numërimi \"i verbër\" nuk ia tregon punëtorit sa duhet të jetë: kështu numëron pa u ndikuar.","en":"A \"blind\" count does not show the counter the expected quantity, so they count without bias."},{"sq":"Numëroni një raft të plotë pa ndërprerje dhe mos e numëroni mallin që klienti e ka tashmë në shportë. Arkat le të jenë në internet gjatë numërimit, që shitjet të hyjnë menjëherë.","en":"Count a whole shelf in one go and do not count goods already in a customer's basket. Keep the tills online during the count so sales come in right away."}],"related":[]},{"path":"/inventory/shrinkage","title":"Humbjet dhe firot","title_en":"Shrinkage","section":"Stoku","perm":"inventory.read","keywords":["humbje","firo","vjedhje","dëmtim","skadim","mungesa","shrinkage","loss","theft"],"what":{"sq":"Çka mungoi ose u gjet në stok gjatë një periudhe, me vlerën me kosto.","en":"What went missing or turned up over a period, with its value at cost."},"steps":[{"sq":"Zgjidh periudhën.","en":"Choose the period."},{"sq":"Shiko sipas artikullit, arsyes, njësisë ose kategorisë: ku humbet më shumë.","en":"Look by item, reason, unit or category: where most is lost."}],"mistakes":[],"after":{"sq":"Artikujt që humbin shpesh kanë nevojë për më shumë kontroll (raft më afër arkës, kamerë, numërim më i shpeshtë).","en":"Items that often go missing need more control (shelf near the till, camera, more frequent counts)."},"related":[]},{"path":"/inventory/expiry","title":"Afatet e afërta","title_en":"Short dates","section":"Stoku","perm":"inventory.read","keywords":["afat","afati","skadenca","skadim","zbritje","expiry","short date","markdown","fefo"]},{"path":"/inventory/levelling","title":"Nivelimi i çmimeve","title_en":"Price levelling","section":"Stoku","perm":"inventory.read","keywords":["nivelim","nivelimi","nivelimi i cmimeve","ndryshim cmimi","price change","repricing","çmimet e reja","new selling prices","margin","markup","cost","marzh","cmim"],"what":{"sq":"Nivelimi i çmimeve: ndryshimi i çmimeve të shitjes si dokument, me datë.","en":"Price levelling: changing selling prices as a dated document."},"steps":[{"sq":"Krijo një nivelim dhe shto artikujt me çmimin e ri.","en":"Create a levelling and add the items with their new price."},{"sq":"Kontabilizoje: çmimet e reja vlejnë nga ai moment, edhe në arkë.","en":"Post it: the new prices apply from then on, at the till too."},{"sq":"Printo etiketat e reja për raftet.","en":"Print the new shelf labels."}],"mistakes":[],"related":[]},{"path":"/inventory/labels","title":"Etiketat","title_en":"Labels","section":"Stoku","perm":"inventory.read","keywords":["etiketa","etiketat","barkod","barcode","shelf","raft","çmim","printo"],"what":{"sq":"Etiketat e raftit, të çmimit dhe me barkod, në fletë A4 ose në printer etiketash.","en":"Shelf, price and barcode labels, on A4 sheets or a label printer."},"steps":[{"sq":"Shto artikujt me emër ose barkod, ose merri nga \"Pranim malli\", \"Faturë blerje\", \"Çmimet e ndryshuara\" ose \"Kategoria\".","en":"Add items by name or barcode, or take them from \"Goods receipt\", \"Purchase invoice\", \"Changed prices\" or \"Category\"."},{"sq":"Te kolona \"Etiketat\" shkruaj sa etiketa do për çdo artikull.","en":"In the \"Labels\" column type how many labels you want for each item."},{"sq":"Zgjidh \"Lloji i etiketës\" dhe \"Letra\"; shiko parapamjen djathtas.","en":"Choose the \"Kind of label\" and the \"Paper\"; check the preview on the right."},{"sq":"Kliko \"Printo … etiketa\" ose \"PDF\".","en":"Click \"Print … labels\" or \"PDF\"."}],"mistakes":[{"sq":"Për një fletë A4 të përdorur pjesërisht, cakto \"Fillo nga etiketa\" që të mos humbasësh etiketat bosh.","en":"For a partly used A4 sheet, set \"Start at label\" so the empty labels are not wasted."},{"sq":"Nëse printimi del pak jashtë etiketave, rregulloje te \"Rregullimi i printerit\".","en":"If the print lands a little off the labels, fix it under \"Printer adjustment\"."}],"after":{"sq":"Artikujt pa barkod mund të marrin barkod të dyqanit me \"Jepu barkod … artikujve që s’kanë\".","en":"Items without a barcode can get an in-store barcode with \"Give barcodes to the … items without one\"."},"related":[{"href":"/inventory/levelling","label":"Nivelimi i çmimeve"}]},{"path":"/inventory/warehouses","title":"Njësitë","title_en":"Warehouses","section":"Stoku","perm":"inventory.read","keywords":["locations","bins","magazinat","magazina","dyqanet","depot","njësitë","pikat"],"what":{"sq":"Njësitë (depo, dyqane) dhe raftet e tyre: çdo lëvizje stoku shkon nga një vend te tjetri.","en":"Units (depots, shops) and their shelves: every stock movement goes from one place to another."},"steps":[{"sq":"Kliko \"Njësi e re\", shkruaj kodin, emrin dhe llojin; krijohet vetë edhe një raft stoku.","en":"Click \"New warehouse\", type the code, name and type; a stock shelf is created with it."},{"sq":"Zgjidh njësinë majtas për të parë raftet dhe vlerën e stokut në to.","en":"Choose a unit on the left to see its shelves and the stock value on them."},{"sq":"Me \"Shto vendndodhje\" shto raftet; \"Barkodi i raftit\" të lejon ta skanosh gjatë pranimit dhe transferimit.","en":"Add shelves with \"Add location\"; a \"Bin barcode\" lets you scan it when receiving and transferring."},{"sq":"Me \"Brenda\" i rendit raftet njëri brenda tjetrit; një \"Grup (pa stok)\" vetëm i mbledh.","en":"With \"Inside\" put shelves under one another; a \"Group (no stock)\" only holds them together."}],"mistakes":[{"sq":"Vetëm raftet bosh fshihen. Për një raft rezervë çaktivizo \"Mblidh nga ky raft\".","en":"Only empty shelves can be deleted. For a reserve shelf switch off \"Pick from this bin\"."}],"related":[{"href":"/inventory/stock","label":"Gjendja"},{"href":"/wms","label":"Paneli i skanerit"}]},{"path":"/inventory/setup","title":"Grupet dhe njësitë matëse","title_en":"Inventory setup","section":"Stoku","perm":"inventory.read","keywords":["categories","units","attributes"],"what":{"sq":"Kategoritë e artikujve, njësitë matëse dhe atributet (masa, ngjyra) për variantet.","en":"Item categories, units of measure and attributes (size, colour) for variants."},"steps":[{"sq":"Te \"Kategoritë\" kliko \"Kategori e re\"; një kategori mund të jetë brenda tjetrës.","en":"Under \"Categories\" click \"New category\"; a category can sit inside another."},{"sq":"Te \"Njësitë matëse\" shto p.sh. paketën me 6 copë: \"Madhësia kundrejt njësisë bazë\" është 6.","en":"Under \"Units of measure\" add for example a pack of 6: the \"Size relative to the reference unit\" is 6."},{"sq":"Te \"Atributet e variantit\" krijo p.sh. Masa me S, M, L: artikulli i ri merr një variant për çdo kombinim.","en":"Under \"Variant attributes\" create for example Size with S, M, L: a new item gets one variant per combination."}],"mistakes":[{"sq":"Kur fshin një kategori, artikujt e saj mbeten pa kategori.","en":"When you delete a category, its items are left without one."}],"related":[{"href":"/inventory/products","label":"Artikujt"}]},{"path":"/finance/payments","title":"Pagesat","title_en":"Payments","section":"Financat","perm":"invoicing.read","keywords":["receipts","pay","arkëtim","pagesë"],"what":{"sq":"Pagesat: paratë që hyjnë nga klientët dhe dalin te furnitorët.","en":"Payments: money in from customers and out to vendors."},"steps":[{"sq":"\"Arkëto një pagesë\" kur paguan klienti; \"Paguaj një furnitor\" kur paguan ti.","en":"\"Receive a payment\" when a customer pays; \"Pay a vendor\" when you pay."},{"sq":"Zgjidh partnerin, bankën ose arkën dhe shumën.","en":"Choose the partner, the bank or cash box and the amount."},{"sq":"Lidhe pagesën me faturat që mbyll, pastaj kontabilizoje.","en":"Match the payment to the invoices it settles, then post it."}],"mistakes":[{"sq":"Një pagesë pa e lidhur me faturë mbetet \"e papërputhur\" dhe fatura duket ende e papaguar.","en":"A payment not matched to an invoice stays \"unmatched\" and the invoice still looks unpaid."}],"related":[{"href":"/finance/payment-proposal","label":"Propozimi i pagesave"}]},{"path":"/finance/receivables","title":"Borxhet","title_en":"Debts","section":"Financat","perm":"invoicing.read","keywords":["ar","aging","debtors","overdue","bilanci i subjekteve","saldo","borxhet","kush më ka borxh","ap","creditors","due","kujt i kam borxh","furnitorët","borxhe","detyrime"],"what":{"sq":"Borxhet: kush të ka borxh dhe sa kohë ka kaluar afati.","en":"Debts: who owes you and how long it is overdue."},"steps":[{"sq":"Kolonat 1–30, 31–60… ditë tregojnë sa vonë janë pagesat.","en":"The 1–30, 31–60… day columns show how late the payments are."},{"sq":"Zilja 🔔 i dërgon klientit kujtesë menjëherë.","en":"The bell 🔔 sends the customer a reminder now."},{"sq":"\"Arkëto\" hap pagesën për atë klient.","en":"\"Collect\" opens a payment for that customer."}],"mistakes":[],"after":{"sq":"Te skeda \"Kujt i kam borxh\" sheh anën tjetër: çfarë u detyrohesh furnitorëve.","en":"The \"Payables\" tab shows the other side: what you owe vendors."},"related":[]},{"path":"/finance/payment-proposal","title":"Propozimi i pagesave","title_en":"Payment proposal","section":"Financat","perm":"invoicing.read","keywords":["propozimi i pagesave","çka të paguaj","pagesat e furnitorëve","pay suppliers","payment run","zbritje","afati"],"what":{"sq":"Çfarë duhet paguar këtë javë: faturat e furnitorëve sipas urgjencës, brenda parave që ke.","en":"What to pay this week: vendor bills by urgency, within the money you have."},"steps":[{"sq":"Zgjidh llogarinë nga paguan: programi shënon të vonuarat dhe ato me afat këtë javë, aq sa mjaftojnë paratë.","en":"Choose the account you pay from: the program ticks the overdue and this week's, as far as the money goes."},{"sq":"Ndrysho çka të duash: hiq ose shto fatura, ose paguaj vetëm një pjesë.","en":"Change what you like: untick or tick bills, or pay only part."},{"sq":"\"Lista për bankën\" të jep IBAN-et dhe shumat për e-banking.","en":"\"List for the bank\" gives the IBANs and amounts for e-banking."},{"sq":"Kliko \"Paguaj\": bëhet një pagesë për çdo furnitor.","en":"Click \"Pay\": one payment per vendor is made."}],"mistakes":[],"related":[]},{"path":"/finance/cash-forecast","title":"Parashikimi i parasë","title_en":"Cash forecast","section":"Financat","perm":"finance.read","keywords":["parashikimi","cash flow","rrjedha e parasë","paraja","likuiditeti","liquidity","13 javë","forecast","minus"],"what":{"sq":"Parashikimi i parasë: sa para do të kesh çdo javë në 13 javët e ardhshme.","en":"Cash forecast: how much money you will have each week for the next 13 weeks."},"steps":[{"sq":"Shiko paralajmërimin lart: nëse paraja bie nën zero, del java dhe shuma.","en":"Look at the warning on top: if cash goes below zero, it names the week and the amount."},{"sq":"Kliko një javë për çdo faturë që hyn ose del.","en":"Click a week for every invoice coming in or going out."},{"sq":"Shto \"Zërat e tu\": qira, kredi, tërheqje të pronarit, çka librat nuk e dinë.","en":"Add \"Your own items\": rent, a loan, the owner's draw, what the books do not know."}],"mistakes":[{"sq":"\"Me vlerësime\" shton faturat dhe blerjet që s'janë bërë ende, sipas mesatares; fike për të parë vetëm ato të sigurtat.","en":"\"With estimates\" adds invoices and purchases not made yet, by the average; switch it off to see only the certain ones."}],"related":[]},{"path":"/finance/expenses","title":"Shpenzimet","title_en":"Expenses","section":"Financat","perm":"invoicing.read","keywords":["shpenzime","shpenzim","karburant","naftë","rryma","kupon","faturë","foto","receipt","fuel","expense"],"what":{"sq":"Shpenzimet: fotografo kuponin ose faturën dhe programi e lexon dhe e regjistron.","en":"Expenses: photograph the receipt or bill and the program reads and books it."},"steps":[{"sq":"Bëj foto ose zgjidh skedarin, ose plotëso me dorë.","en":"Take a photo or choose the file, or fill it in by hand."},{"sq":"Kontrollo furnitorin, datën dhe TVSH-në që lexoi programi.","en":"Check the vendor, date and VAT the program read."},{"sq":"Zgjidh nga u pagua (arka ose banka) dhe regjistroje.","en":"Choose what it was paid from (cash box or bank) and book it."}],"mistakes":[],"related":[]},{"path":"/finance/bank","title":"Banka dhe arka","title_en":"Bank and cash","section":"Financat","perm":"finance.read","keywords":["reconciliation","statement","banka"],"what":{"sq":"Banka dhe arka: gjendja e çdo llogarie dhe krahasimi me ekstraktin e bankës.","en":"Bank and cash: each account's balance and the comparison with the bank statement."},"steps":[{"sq":"Importo ekstraktin nga e-banking (Excel, CSV ose XML).","en":"Import the statement from e-banking (Excel, CSV or XML)."},{"sq":"Programi i lidh rreshtat me pagesat; ato që mbeten lidhi me dorë.","en":"The program matches the lines to payments; match the rest by hand."},{"sq":"\"Pse?\" shpjegon diferencën mes librave dhe bankës.","en":"\"Why?\" explains the difference between the books and the bank."}],"mistakes":[{"sq":"Kontrollo që saldo fillestare e ekstraktit të jetë e saktë: përndryshe del diferencë \"e pashpjeguar\".","en":"Check that the statement's opening balance is right, or an \"unexplained\" difference appears."}],"related":[]},{"path":"/finance/cash-book","title":"Libri i arkës","title_en":"Cash book","section":"Financat","perm":"finance.read","keywords":["libri i arkës","arka","cash book","para në dorë"],"what":{"sq":"Libri i arkës: çdo hyrje dhe dalje e parave në dorë, ditë për ditë.","en":"The cash book: every cash movement in and out, day by day."},"steps":[{"sq":"Zgjidh arkën dhe periudhën.","en":"Choose the cash box and the period."},{"sq":"Gjendja në fund të çdo dite duhet të përputhet me paratë e numëruara.","en":"The balance at the end of each day should match the cash counted."},{"sq":"Printoje kur ta kërkojë kontabilisti.","en":"Print it when the accountant asks."}],"mistakes":[],"related":[]},{"path":"/finance/cards","title":"Kartelat e partnerëve","title_en":"Partner cards","section":"Financat","perm":"invoicing.read","keywords":["kartela","kartela e klientit","kartela e furnitorit","ios","konfirmim","statement","saldo"],"what":{"sq":"Kartela e partnerit: çdo faturë, pagesë dhe kompensim me një klient ose furnitor, me saldon.","en":"The partner card: every invoice, payment and compensation with a customer or vendor, with the balance."},"steps":[{"sq":"Zgjidh partnerin dhe periudhën.","en":"Choose the partner and the period."},{"sq":"Dërgoja klientit si konfirmim saldoje (IOS) për ta krahasuar me librat e tij.","en":"Send it to the customer as a balance confirmation to compare with their books."}],"mistakes":[],"related":[]},{"path":"/finance/compensations","title":"Kompensimet","title_en":"Compensations","section":"Financat","perm":"invoicing.read","keywords":["kompensim","kompensimi","offset","netting"],"what":{"sq":"Kompensimi: kur një partner të ka borxh dhe ti i ke borxh atij, i mbyll të dyja pa lëvizur para.","en":"Compensation: when a partner owes you and you owe them, settle both without moving money."},"steps":[{"sq":"Zgjidh partnerin: dalin faturat e hapura në të dyja anët.","en":"Choose the partner: the open invoices on both sides appear."},{"sq":"Zgjidh çka kompensohet (shumat duhet të jenë të barabarta) dhe kontabilizoje.","en":"Choose what is offset (the amounts must be equal) and post it."}],"mistakes":[],"related":[]},{"path":"/tax/books","title":"Librat e TVSH-së","title_en":"VAT books","section":"Tatimet","perm":"tax.read","keywords":["libri i shitjes","libri i shitjeve","sales book","vat book","tvsh","libri i blerjes","libri i blerjeve","purchase book"],"what":{"sq":"Librat e TVSH-së: çdo dokument përfundimtar i muajit, në librin e shitjeve ose të blerjeve, në kolonat e deklaratës.","en":"The VAT books: every final document of the month, in the sales or the purchase book, in the columns of the declaration."},"steps":[{"sq":"Zgjidh muajin lart djathtas.","en":"Choose the month at the top right."},{"sq":"Kalo mes librit të shitjeve dhe librit të blerjeve me skedat mbi tabelë.","en":"Switch between the sales book and the purchase book with the tabs above the table."},{"sq":"Kliko numrin e dokumentit për ta hapur faturën pas rreshtit.","en":"Click a document number to open the invoice behind the line."},{"sq":"Me \"Eksporto\" e merr librin në Excel, CSV ose PDF.","en":"With \"Export\" you get the book in Excel, CSV or PDF."}],"mistakes":[{"sq":"Faturat në skicë nuk dalin këtu: kontabilizoji para se të bësh deklaratën.","en":"Draft invoices do not show here: post them before you make the declaration."},{"sq":"Në Kosovë, notat e kreditit që lëshon ti shkojnë në librin e blerjeve dhe ato që merr në librin e shitjeve, si në deklaratën e ATK-së.","en":"In Kosovo, credit notes you issue go in the purchase book and those you receive go in the sales book, as on the ATK return."}],"after":{"sq":"Nga këta libra plotësohet deklarata e TVSH-së e muajit.","en":"The month's VAT declaration is filled from these books."},"related":[{"href":"/tax/declarations","label":"Deklaratat e TVSH"},{"href":"/tax","label":"Afatet e tatimeve"}]},{"path":"/tax/declarations","title":"Deklaratat e TVSH","title_en":"VAT declarations","section":"Tatimet","perm":"tax.read","keywords":["vat return","deklarata","tvsh","dpt","atk"],"what":{"sq":"Deklaratat mujore të TVSH-së, të plotësuara nga librat e shitjeve dhe blerjeve.","en":"The monthly VAT declarations, filled from the sales and purchase books."},"steps":[{"sq":"Kliko \"Deklaratë e re\", zgjidh muajin dhe kliko \"Krijo deklaratën\".","en":"Click \"New declaration\", choose the month and click \"Create declaration\"."},{"sq":"Deklarata krijohet si skicë dhe hapet: kontrolloje para se ta dorëzosh.","en":"The declaration is created as a draft and opens: check it before you submit it."},{"sq":"Filtro sipas statusit për të parë cilat janë ende skicë dhe cilat janë dorëzuar.","en":"Filter by status to see which are still drafts and which are submitted."}],"mistakes":[{"sq":"Programi propozon muajin e kaluar: kontrollo që ke zgjedhur muajin e duhur.","en":"The program suggests last month: check that you chose the right month."}],"after":{"sq":"Kur dorëzohet, deklarata regjistrohet në kontabilitet dhe muaji mbyllet për TVSH.","en":"When it is submitted, the declaration is booked and the month is closed for VAT."},"related":[{"href":"/tax/books","label":"Librat e TVSH-së"},{"href":"/tax","label":"Afatet e tatimeve"}]},{"path":"/tax/small-business","title":"Biznesi i vogël","title_en":"Small business tax","section":"Tatimet","perm":"tax.read","keywords":["biznes i vogël","biznes i vogel","3%","9%","tremujor","qarkullim","small business","turnover tax"],"what":{"sq":"Biznesi i vogël: biznesi që nuk është në TVSH paguan çdo tremujor një tatim mbi të ardhurat bruto.","en":"Small business: a business not registered for VAT pays a tax on its gross income every quarter."},"steps":[{"sq":"Zgjidh vitin lart djathtas.","en":"Choose the year at the top right."},{"sq":"Te \"Norma e këtij biznesi\" zgjidh 3% (tregti, transport, bujqësi) ose 9% (shërbime, profesione).","en":"Under \"The rate of this business\" choose 3% (trade, transport, farming) or 9% (services, professions)."},{"sq":"Shiko tabelën: për çdo tremujor të ardhurat, tatimin dhe afatin.","en":"Look at the table: for each quarter the income, the tax and the due date."},{"sq":"Kliko \"Libri i shitjeve\" te një tremujor për dokumentet nga vijnë të ardhurat.","en":"Click \"Sales book\" on a quarter for the documents the income comes from."}],"mistakes":[{"sq":"Biznesi i regjistruar për TVSH nuk e paguan këtë tatim: ai deklaron TVSH-në çdo muaj.","en":"A business registered for VAT does not pay this tax: it declares VAT every month."},{"sq":"Kur të ardhurat e vitit kalojnë kufirin, faqja të paralajmëron: biznesi duhet të regjistrohet për TVSH.","en":"When the year's income goes over the limit, the page warns you: the business must register for VAT."}],"after":{"sq":"Kjo faqe vetëm e llogarit tatimin, nuk regjistron asgjë. Ai deklarohet dhe paguhet deri më 15 të muajit pas tremujorit.","en":"This page only works out the tax, it books nothing. It is declared and paid by the 15th of the month after the quarter."},"related":[{"href":"/tax/books","label":"Librat e TVSH-së"}]},{"path":"/finance/z-reports","title":"Z-raportet e arkës fiskale","title_en":"Z reports","section":"Tatimet","perm":"invoicing.read","keywords":["z raport","z-raporti","raporti z","arka fiskale","kasa","fiscal register","z report"],"what":{"sq":"Z-raportet e arkës fiskale tënde: fotografo raportin e ditës dhe programi i regjistron shitjet sipas normës së TVSH-së.","en":"The Z reports of your own fiscal register: photograph the day's report and the program books the sales by VAT rate."},"steps":[{"sq":"Kliko \"Bëj një foto\" ose \"Zgjidh skedarë\" (disa ditë njëherësh); mund ta plotësosh edhe me dorë më poshtë.","en":"Click \"Take a photo\" or \"Choose files\" (several days at once); you can also fill it in by hand below."},{"sq":"Kontrollo \"Numri i Z-raportit\", arkën fiskale dhe datën.","en":"Check the \"Z report number\", the fiscal register and the date."},{"sq":"Për çdo normë zgjidh TVSH-në dhe shkruaj shumën pa TVSH; për një tjetër kliko \"Një normë tjetër TVSH\".","en":"For each rate choose the VAT and type the amount without VAT; for another one click \"Another VAT rate\"."},{"sq":"Shkruaj sa u pagua \"Me para në dorë\" dhe \"Me kartë\", me arkën dhe bankën ku shkojnë.","en":"Type what was paid \"In cash\" and \"By card\", with the till and the bank they go to."},{"sq":"Kliko \"Regjistro shitjet\".","en":"Click \"Book the sales\"."}],"mistakes":[{"sq":"Shumat në rreshta janë pa TVSH: krahaso totalin me TVSH me atë që shkruan raporti.","en":"The amounts on the lines are without VAT: compare the total with VAT with what the report says."},{"sq":"I njëjti Z-raport nuk regjistrohet dy herë: programi e refuzon numrin që është regjistruar më parë.","en":"The same Z report is not booked twice: the program refuses a number already booked."}],"after":{"sq":"Bëhet një faturë shitjeje e kontabilizuar te klienti \"Shitje me arkë fiskale\" dhe del në librin e shitjeve; nuk dërgohet përsëri për fiskalizim. Paratë në dorë hyjnë në arkë, kartat në bankë; pjesa që mbetet është e hapur te ai klient.","en":"A posted sales invoice is made to the customer \"Shitje me arkë fiskale\" and goes in the sales book; it is not sent for fiscalization again. Cash goes into the till, cards into the bank; whatever is left stays open on that customer."},"related":[{"href":"/tax/books","label":"Librat e TVSH-së"}]},{"path":"/tax/withholding","title":"Tatimi në burim","title_en":"Withholding tax","section":"Tatimet","perm":"tax.read","keywords":["tatim në burim","tatimi në burim","withholding","qira","rent","wht"],"what":{"sq":"Tatimi në burim: tatimi që mban nga pagesat për qira, interes, të drejta autori ose shërbime të individëve dhe jorezidentëve.","en":"Withholding tax: the tax you keep back from payments for rent, interest, royalties or services of individuals and non-residents."},"steps":[{"sq":"Tatimi mbahet te fatura e furnitorit: hap faturën e kontabilizuar dhe kliko \"Mbaj tatimin në burim\".","en":"The tax is withheld on the supplier's bill: open the posted bill and click \"Withhold tax\"."},{"sq":"Këtu, te \"Sipas muajit\", zgjidh muajin: sheh çdo tatim të mbajtur dhe totalin sipas llojit.","en":"Here, under \"By month\", choose the month: you see each tax withheld and the total by kind."},{"sq":"Me \"Eksporto\" e merr listën për deklaratën mujore.","en":"With \"Export\" you get the list for the monthly declaration."},{"sq":"Te \"Llojet dhe normat\" kontrollo normat; ndryshoji kur ndryshon ligji, ose shto një lloj të ri.","en":"Under \"Kinds and rates\" check the rates; change them when the law changes, or add a new kind."}],"mistakes":[{"sq":"Normat janë ato të zakonshme të vendit: kontrolloji me kontabilistin para se t'i përdorësh.","en":"The rates are the usual ones of the country: check them with your accountant before you use them."}],"after":{"sq":"Furnitori merr aq më pak para: borxhi ndaj tij zvogëlohet dhe tatimi regjistrohet si detyrim ndaj tatimeve, që deklarohet dhe paguhet deri në datën që tregon faqja.","en":"The supplier gets that much less: what you owe them goes down and the tax is booked as owed to the tax office, declared and paid by the date the page shows."},"related":[{"href":"/procurement/bills","label":"Faturat e furnitorëve"}]},{"path":"/tax/income-tax","title":"Tatimi mbi fitimin","title_en":"Corporate income tax","section":"Tatimet","perm":"tax.read","keywords":["tatimi mbi fitimin","tatim fitimi","cit","profit tax","deklarata vjetore"],"what":{"sq":"Tatimi mbi fitimin: nga fitimi në libra te tatimi i vitit, me shpenzimet e pazbritshme dhe humbjet e viteve të kaluara.","en":"Corporate income tax: from the profit in the books to the tax of the year, with non-deductible expenses and losses of earlier years."},"steps":[{"sq":"Shkruaj vitin.","en":"Type the year."},{"sq":"Kliko \"Zgjidh llogaritë\" dhe shëno kontot e shpenzimeve që tatimet nuk i pranojnë (gjoba, shpenzime private…).","en":"Click \"Choose accounts\" and mark the expense accounts the tax office does not accept (fines, private expenses…)."},{"sq":"Shto te \"± Diferenca të tjera\" çdo ndryshim tjetër dhe shkruaj humbjet e viteve të mëparshme që përdor.","en":"Add any other change under \"± Other differences\" and type the losses of earlier years you use."},{"sq":"Kontrollo normën dhe këstet e paguara gjatë vitit, pastaj kliko \"Ruaj\".","en":"Check the rate and the advances paid during the year, then click \"Save\"."},{"sq":"Kliko \"Regjistroje\" për ta futur tatimin në libra.","en":"Click \"Book it\" to put the tax in the books."}],"mistakes":[{"sq":"Nëse shifrat ndryshojnë pasi e ke regjistruar, kliko përsëri \"Regjistroje\": regjistrimi i ri zëvendëson të vjetrin.","en":"If the figures change after you booked it, click \"Book it\" again: the new entry replaces the old one."},{"sq":"Kur viti është mbyllur, tatimi nuk ndryshohet më; rihape vitin te \"Mbyllja e vitit\".","en":"When the year is closed the tax can no longer change; reopen the year under \"Year-end close\"."}],"after":{"sq":"Tatimi regjistrohet si shpenzim i vitit dhe si detyrim ndaj tatimeve. Fleta ndihmon për deklaratën vjetore: kontrolloje me kontabilistin para se ta dorëzosh.","en":"The tax is booked as an expense of the year and as owed to the tax office. The sheet helps with the annual return: check it with your accountant before filing."},"related":[{"href":"/finance/year-end","label":"Mbyllja e vitit"},{"href":"/finance/reports","label":"Pasqyrat financiare"}]},{"path":"/tax/fiscalization","title":"Fiskalizimi","title_en":"Fiscalization","section":"Tatimet","perm":"tax.read","keywords":["nivf","nslf","iic","fic","cis","efiskalizimi","qr"],"what":{"sq":"Fiskalizimi: çdo faturë dhe kupon që dërgohet te tatimet, me kodin që merr, dhe ato që dështuan.","en":"Fiscalization: every invoice and receipt sent to the tax office, with the code it gets, and the ones that failed."},"steps":[{"sq":"Shiko kartat lart: sa presin, sa dështuan dhe sa u fiskalizuan sot.","en":"Look at the cards on top: how many are waiting, how many failed and how many were fiscalized today."},{"sq":"Filtro sipas statusit \"Dështoi\" dhe lexo gabimin në rresht.","en":"Filter by the status \"Failed\" and read the error on the line."},{"sq":"Pasi ta rregullosh shkakun, kliko \"Dërgo dokumentet në pritje\": ato që dështuan dërgohen përsëri.","en":"Once you fix the cause, click \"Send waiting documents\": the failed ones are sent again."},{"sq":"Kliko \"Verifiko\" te rreshti për ta parë dokumentin në faqen e tatimeve.","en":"Click \"Verify\" on a line to see the document on the tax office's site."}],"mistakes":[{"sq":"Në mënyrën prove përgjigjja e tatimeve simulohet: kodet dhe lidhjet QR janë vetëm për provë.","en":"In test mode the tax office's answer is simulated: the codes and QR links are for testing only."}],"after":{"sq":"Dokumentet e lëshuara pa internet dërgohen më vonë, si fiskalizim i mëvonshëm.","en":"Documents issued offline are sent afterwards, as later fiscalization."},"related":[{"href":"/tax","label":"Afatet e tatimeve"}]},{"path":"/tax/codes","title":"Normat e TVSH","title_en":"Tax codes","section":"Tatimet","perm":"tax.read","keywords":["vat rates","exempt","reverse charge"],"what":{"sq":"Kodet e TVSH-së: normat që vendos në fatura, dhe në cilën kolonë të librit dhe fushë të deklaratës shkon çdo rresht.","en":"Tax codes: the rates you put on invoices, and which book column and declaration field each line goes to."},"steps":[{"sq":"Kliko \"Kod i ri tatimor\" për një normë të re, ose lapsin te rreshti për ta ndryshuar.","en":"Click \"New tax code\" for a new rate, or the pencil on a line to change it."},{"sq":"Shkruaj kodin, emrin dhe normën, dhe zgjidh \"Përdoret në\": shitje, blerje ose të dyja.","en":"Type the code, the name and the rate, and choose \"Used on\": sales, purchases or both."},{"sq":"Për raste të veçanta ndez \"E përjashtuar\" ose \"Autongarkesë\", ose fik \"TVSH-ja e blerjes zbritet\".","en":"For special cases switch on \"Exempt\" or \"Reverse charge\", or switch off \"Purchase VAT can be deducted\"."},{"sq":"Lëri kontot te \"Parazgjedhja e kompanisë\", përveç kur kontabilisti të thotë ndryshe.","en":"Leave the accounts on \"Company default\", unless your accountant says otherwise."}],"mistakes":[{"sq":"Një lloj i gabuar TVSH-je e çon rreshtin në kolonë të gabuar të librit dhe të deklaratës: pyet kontabilistin kur nuk je i sigurt.","en":"A wrong VAT type sends the line to the wrong book column and declaration field: ask your accountant when unsure."},{"sq":"Një kod që nuk përdoret më fike me \"Aktiv\"; mos e kthe në një normë tjetër.","en":"Switch off a code you no longer use with \"Active\"; do not turn it into another rate."}],"after":{"sq":"Te autongarkesa furnitori nuk vë TVSH dhe kompania e regjistron si TVSH të shitjeve dhe të blerjeve njëherësh; TVSH-ja që nuk zbritet i shtohet kostos.","en":"With reverse charge the vendor charges no VAT and the company books it as both sales and purchase VAT; non-deductible VAT is added to the cost."},"related":[]},{"path":"/check","title":"Kontrolli i librave","title_en":"Books check","section":"Kontabiliteti","perm":"invoicing.read","keywords":["kontrolli","gabime","gabimet","mistakes","check","kujdestari","pa faturë","minus","nui"],"what":{"sq":"Kontrolli i librave: gabimet që kanë kaluar pa u vënë re, secili me arsyen pse ka rëndësi dhe vendin ku rregullohet.","en":"Books check: the mistakes that slipped through, each with why it matters and where to fix it."},"steps":[{"sq":"Lexo çdo kartë: çka nuk është në rregull dhe pse ka rëndësi.","en":"Read each card: what is not right and why it matters."},{"sq":"Kliko butonin te rreshti (\"Fut faturën\", \"Bëje faturën\", \"Shto NUI-në\" ose \"Rregulloje\") për të shkuar aty ku rregullohet.","en":"Click the button on the line (\"Enter the invoice\", \"Make the invoice\", \"Add the NUI\" or \"Fix it\") to go where it is fixed."},{"sq":"Kur janë më shumë, kliko \"Shiko të gjitha\" për listën e plotë.","en":"When there are more, click \"See all\" for the full list."}],"mistakes":[{"sq":"Asgjë këtu nuk ndryshon vetvetiu: çdo gabim e rregullon ti në dokumentin e tij.","en":"Nothing here changes by itself: you fix each mistake on its own document."}],"after":{"sq":"Pasi e rregullon dokumentin, gabimi nuk del më në listë.","en":"Once you fix the document, the mistake no longer shows in the list."},"related":[]},{"path":"/finance/reports","title":"Pasqyrat financiare","title_en":"Financial statements","section":"Kontabiliteti","perm":"finance.read","keywords":["p&l","profit and loss","balance sheet","cash flow","trial balance","bilanc","comparison"],"what":{"sq":"Pasqyrat financiare: të ardhurat dhe shpenzimet, bilanci, fluksi i parasë dhe bilanci i verifikimit, nga regjistrimet e kontabilizuara.","en":"Financial statements: income statement, balance sheet, cash flow and trial balance, from posted entries."},"steps":[{"sq":"Zgjidh pasqyrën me skedat lart.","en":"Choose the statement with the tabs on top."},{"sq":"Zgjidh periudhën dhe, nëse do, \"Krahaso me\" vitin e mëparshëm ose muaj pas muaji.","en":"Choose the period and, if you like, \"Compare with\" the previous year or month by month."},{"sq":"Për një degë ose projekt zgjidh \"Qendra e kostos\" (te pasqyra e të ardhurave dhe bilanci i verifikimit).","en":"For a branch or project choose the \"Cost center\" (on the income statement and the trial balance)."},{"sq":"Kliko një konto për të parë çdo regjistrim pas saj.","en":"Click an account to see every entry behind it."},{"sq":"Me \"Eksporto\" ose \"Printo\" e merr pasqyrën.","en":"With \"Export\" or \"Print\" you take the statement with you."}],"mistakes":[{"sq":"Regjistrimet në skicë nuk llogariten: kontabilizoji para se t'i lexosh shifrat.","en":"Draft entries are not counted: post them before you read the figures."}],"related":[{"href":"/finance/accounts","label":"Plani kontabël"},{"href":"/finance/cost-centers","label":"Qendrat e kostos"}]},{"path":"/finance/journal","title":"Regjistrimet kontabël","title_en":"Journal entries","section":"Kontabiliteti","perm":"finance.read","keywords":["gl","general ledger","manual entry","ditar"],"what":{"sq":"Regjistrimet kontabël: gjithçka që është regjistruar në konto. Ato automatike vijnë nga dokumentet; ato manuale i bën ti.","en":"Journal entries: everything recorded in the accounts. Automatic ones come from documents; manual ones you make yourself."},"steps":[{"sq":"Zgjidh periudhën me datat lart.","en":"Choose the period with the dates on top."},{"sq":"Filtro sipas ditarit, burimit (automatik ose manual) ose statusit.","en":"Filter by journal, source (automatic or manual) or status."},{"sq":"Kliko një regjistrim për rreshtat e tij dhe dokumentin nga vjen.","en":"Click an entry for its lines and the document it comes from."},{"sq":"Për përllogaritje, gjendje fillestare ose korrigjime kliko \"Regjistrim manual\".","en":"For accruals, opening balances or corrections click \"Manual entry\"."}],"mistakes":[{"sq":"Mos bëj regjistrim manual për një faturë ose pagesë: dokumenti e regjistron vetë, dhe do të dalë dy herë.","en":"Do not make a manual entry for an invoice or payment: the document books itself, and it would show twice."}],"related":[{"href":"/finance/accounts","label":"Plani kontabël"},{"href":"/finance/account-card","label":"Kartela e kontos"}]},{"path":"/finance/account-card","title":"Kartela e kontos","title_en":"Account card","section":"Kontabiliteti","perm":"finance.read","keywords":["kartela e kontos","libri kryesor","general ledger","account ledger"],"what":{"sq":"Kartela e kontos: çdo regjistrim në një konto, me saldon pas secilit.","en":"The account card: every entry on one account, with the balance after each."},"steps":[{"sq":"Zgjidh kontin nga lista; mund të kërkosh me kod ose emër.","en":"Choose the account from the list; you can search by code or name."},{"sq":"Te kartela zgjidh periudhën me datat lart.","en":"On the card, choose the period with the dates on top."},{"sq":"Kliko numrin e regjistrimit ose dokumentin për ta hapur.","en":"Click the entry number or the document to open it."}],"mistakes":[],"related":[{"href":"/finance/accounts","label":"Plani kontabël"}]},{"path":"/finance/accounts","title":"Plani kontabël","title_en":"Chart of accounts","section":"Kontabiliteti","perm":"finance.read","keywords":["coa","ledger","plan kontabel","accounts"],"what":{"sq":"Plani kontabël: kontot sipas klasave, me lëvizjen dhe saldon e këtij viti.","en":"The chart of accounts: the accounts by class, with this year's movement and balance."},"steps":[{"sq":"Kërko me kod ose emër; me \"Vetëm llogaritë me lëvizje\" sheh vetëm ato që janë përdorur.","en":"Search by code or name; with \"Only accounts with movements\" you see only the ones used."},{"sq":"Kliko një konto për kartelën e saj: çdo regjistrim me saldon.","en":"Click an account for its card: every entry with the balance."},{"sq":"Për një konto të re kliko \"Llogari e re\" dhe plotëso kodin, grupin, emrin dhe llojin.","en":"For a new account click \"New account\" and fill in the code, group, name and type."}],"mistakes":[{"sq":"Kodi i kontos nuk ndryshohet pasi krijohet: kontrolloje mirë para se ta ruash.","en":"An account's code cannot change once created: check it well before saving."},{"sq":"\"Lloji i llogarisë\" vendos ku del kontoja në pasqyrat financiare.","en":"The \"Kind\" decides where the account appears in the financial statements."}],"related":[{"href":"/finance/account-card","label":"Kartela e kontos"},{"href":"/finance/setup","label":"Cilësimet e financës"}]},{"path":"/finance/assets","title":"Mjetet themelore","title_en":"Fixed assets","section":"Kontabiliteti","perm":"finance.read","keywords":["depreciation","amortization","aktive"],"what":{"sq":"Mjetet themelore: pajisjet, automjetet dhe mobiljet e kompanisë, me amortizimin e çdo muaji.","en":"Fixed assets: the company's equipment, vehicles and furniture, with each month's depreciation."},"steps":[{"sq":"Kliko \"Aktiv i ri\" për ta regjistruar me dorë, ose \"Nga fotoja e faturës\" për ta krijuar nga fatura.","en":"Click \"New asset\" to register it by hand, or \"From an invoice photo\" to make it from the invoice."},{"sq":"Kliko një mjet për planin e amortizimit dhe detajet.","en":"Click an asset for its depreciation schedule and details."},{"sq":"Kliko \"Llogarit amortizimin\", zgjidh datën te \"Deri dhe përfshirë\" dhe kliko \"Regjistro amortizimin\".","en":"Click \"Run depreciation\", choose the date under \"Up to and including\" and click \"Record depreciation\"."},{"sq":"Ndiz \"Regjistroje vetë çdo muaj\" që muaji i kaluar të regjistrohet vetë në ditën e parë të muajit.","en":"Switch on \"Record it by itself every month\" so last month is recorded on the first day of each month."}],"mistakes":[],"after":{"sq":"Bëhet një regjistrim amortizimi për çdo muaj; muajt e regjistruar më parë kapërcehen, ndaj nuk regjistrohen dy herë.","en":"One depreciation entry is made per month; months already recorded are skipped, so nothing is booked twice."},"related":[{"href":"/finance/asset-invoices","label":"Mjete nga faturat"}]},{"path":"/finance/asset-invoices","title":"Mjete nga faturat","title_en":"Assets from invoices","section":"Kontabiliteti","perm":"finance.read","keywords":["mjete themelore","faturë","foto","investim","veturë","kompjuter","asset invoice"],"what":{"sq":"Mjete nga faturat: fotografo faturën e një veture, makine ose kompjuteri dhe programi e regjistron si investim, krijon mjetin dhe planin e amortizimit.","en":"Assets from invoices: photograph the invoice of a vehicle, machine or computer and the program books it as an investment, makes the asset and plans its depreciation."},"steps":[{"sq":"Kliko \"Bëj një foto\" ose \"Zgjidh skedarë\"; mund ta plotësosh edhe me dorë.","en":"Click \"Take a photo\" or \"Choose files\"; you can also fill it in by hand."},{"sq":"Kontrollo shitësin, numrin e faturës dhe datën që lexoi programi.","en":"Check the seller, the invoice number and the date the program read."},{"sq":"Shkruaj emrin te \"Mjeti\", zgjidh \"Lloji i mjetit\" dhe kontrollo jetëgjatësinë në muaj.","en":"Type the name under \"The asset\", choose the \"Kind of asset\" and check the useful life in months."},{"sq":"Kontrollo shumat pa TVSH, zgjidh te \"U pagua?\" nëse është paguar, dhe kliko \"Regjistro mjetin\".","en":"Check the amounts without VAT, choose under \"Paid?\" whether it is paid, and click \"Book the asset\"."}],"mistakes":[{"sq":"Shitësi që nuk është në listë shtohet si furnitor i ri kur e regjistron: kontrollo emrin dhe NUI-në.","en":"A seller not in your list is added as a new vendor when you book: check the name and NUI."}],"after":{"sq":"Fatura del te faturat e furnitorëve dhe në librin e blerjeve; nëse nuk u pagua, pret te faturat për t’u paguar. Mjeti krijohet, vihet në përdorim dhe amortizohet çdo muaj.","en":"The invoice goes to the vendor bills and the purchase book; if not paid, it waits among the bills to pay. The asset is made, put in service and depreciated every month."},"related":[{"href":"/finance/assets","label":"Mjetet themelore"}]},{"path":"/finance/cost-centers","title":"Qendrat e kostos","title_en":"Cost centers","section":"Kontabiliteti","perm":"finance.read","keywords":["departments","branches","projects"],"what":{"sq":"Qendrat e kostos: dega, departamenti ose projekti, për të parë fitimin e secilit veç.","en":"Cost centers: a branch, department or project, to see the profit of each one."},"steps":[{"sq":"Kliko \"Qendër kostoje e re\" dhe shkruaj kodin dhe emrin; te \"Bën pjesë te\" mund ta vendosësh nën një tjetër.","en":"Click \"New cost center\" and type the code and name; under \"Belongs to\" you can put it under another one."},{"sq":"Zgjidh qendrën e kostos te regjistrimet, mjetet dhe dokumentet.","en":"Choose the cost center on entries, assets and documents."},{"sq":"Zgjidh periudhën me datat lart: për secilën sheh të ardhurat, koston e mallit, shpenzimet, fitimin dhe marzhin.","en":"Choose the period with the dates on top: for each you see revenue, cost of goods, expenses, profit and margin."}],"mistakes":[{"sq":"Të ardhurat dhe shpenzimet pa qendër kostoje dalin veç te \"Pa qendër kostoje\": kontrollo që e ke zgjedhur në dokumente.","en":"Revenue and costs without a cost center show apart under \"No cost center\": check you chose it on the documents."}],"related":[{"href":"/finance/reports","label":"Pasqyrat financiare"}]},{"path":"/finance/year-end","title":"Mbyllja e vitit","title_en":"Year-end close","section":"Kontabiliteti","perm":"finance.read","keywords":["mbyllja e vitit","mbyllje","year end","closing","fitimi i vitit","109","108"],"what":{"sq":"Mbyllja e vitit: kontrollo që asgjë nuk ka mbetur e hapur, shiko rezultatin dhe mbyll vitin.","en":"Year-end close: check that nothing is left open, see the result and close the year."},"steps":[{"sq":"Zgjidh vitin lart.","en":"Choose the year on top."},{"sq":"Te \"Para mbylljes\" rregullo çdo gjë me të kuqe me \"Hap\"; e verdha vlen të kontrollohet, por nuk e ndalon mbylljen.","en":"Under \"Before closing\" fix everything in red with \"Open\"; yellow is worth checking but does not stop the closing."},{"sq":"Shiko rezultatin e vitit: të ardhurat, shpenzimet dhe fitimin ose humbjen.","en":"Look at the result of the year: revenue, expenses and the profit or loss."},{"sq":"Zgjidh nëse rezultati kalon te kontoja 108 më 1 janar, pastaj kliko \"Mbyll vitin\".","en":"Choose whether the result is carried to account 108 on 1 January, then click \"Close the year\"."}],"mistakes":[{"sq":"Vitet mbyllen me radhë: mbyll më parë vitet e mëparshme që janë ende të hapura.","en":"Years close in order: first close the earlier years that are still open."},{"sq":"Vitin e mbyll vetëm dikush me të drejtë miratimi në financë.","en":"Only someone who can approve in finance can close the year."}],"after":{"sq":"Rezultati kalon në kontin 109 në fund të vitit dhe çdo muaj i vitit mbyllet: asgjë me datë në atë vit nuk kontabilizohet më. Për një korrigjim kliko \"Rihap vitin\" dhe shkruaj arsyen.","en":"The result moves to account 109 at the end of the year and every month of the year closes: nothing dated in it can be posted any more. To correct something, click \"Reopen the year\" and give the reason."},"related":[{"href":"/tax/income-tax","label":"Tatimi mbi fitimin"}]},{"path":"/finance/setup","title":"Cilësimet e financës","title_en":"Finance setup","section":"Kontabiliteti","perm":"finance.read","keywords":["posting accounts","periods","close","fiscal year","journals"],"what":{"sq":"Cilësimet e financës: kontot që përdorin regjistrimet automatike, muajt e hapur, ditarët dhe rregulla të tjera.","en":"Finance setup: the accounts automatic entries use, the open months, the journals and other rules."},"steps":[{"sq":"Te \"Llogaritë e kontabilizimit\" cakto kontin për çdo rast (arka, banka, TVSH, paga…).","en":"Under \"Posting accounts\" set the account for each case (cash, bank, VAT, salaries…)."},{"sq":"Te \"Muajt kontabël\" krijo vitin financiar dhe mbyll muajt e përfunduar me \"Mbyll muajin\".","en":"Under \"Accounting months\" create the financial year and close finished months with \"Close month\"."},{"sq":"Te \"Kategoritë e aktiveve\" sheh jetëgjatësinë, mënyrën dhe kontot e amortizimit.","en":"Under \"Asset categories\" you see the useful life, method and depreciation accounts."},{"sq":"Te \"Kufijtë e parave në dorë\" cakto kufijtë për pagesat me para në dorë; te \"Kushtet e pagesës\" afatet e pagesës.","en":"Under \"Cash limits\" set the limits for cash payments; under \"Payment terms\" the payment terms."}],"mistakes":[{"sq":"Një rast pa konto te \"Llogaritë e kontabilizimit\" e ndalon kontabilizimin e dokumenteve që e përdorin.","en":"A case with no account under \"Posting accounts\" stops the posting of the documents that use it."},{"sq":"Një muaj i mbyllur mund ta rihapë menaxheri i financës; një muaj i kyçur (\"Kyç\") nuk rihapet më.","en":"A closed month can be reopened by a finance manager; a locked month (\"Lock\") can never be reopened."}],"after":{"sq":"Dokumentet me datë në një muaj të mbyllur refuzohen me një mesazh të qartë.","en":"Documents dated in a closed month are refused with a clear message."},"related":[]},{"path":"/appointments","title":"Kalendari i termineve","title_en":"Appointment calendar","section":"Terminet","perm":"sales.read","keywords":["termin","terminet","takim","rezervim","kalendar","booking","salon","klinikë","servis"],"what":{"sq":"Kalendari i termineve: dita sipas personit, karriges ose ngritësit. Kliko një vend të lirë për të rezervuar.","en":"The appointment calendar: the day by person, chair or lift. Click a free place to book."},"steps":[{"sq":"Zgjidh ditën me shigjetat, me datën ose me \"Sot\".","en":"Choose the day with the arrows, the date or \"Today\"."},{"sq":"Kliko një vend të lirë në kolonën e personit, ose \"Termin i ri\".","en":"Click a free place in the person's column, or \"New appointment\"."},{"sq":"Zgjidh shërbimin dhe orën te \"Oraret e lira\"; zgjidh klientin ose shkruaj emrin dhe telefonin e një klienti të ri, pastaj ruaje.","en":"Choose the service and a time under \"Free times\"; pick the client or type a new client's name and phone, then save."},{"sq":"Kur vjen klienti kliko terminin dhe \"Erdhi\"; kur mbaron puna, \"U krye, te fatura\".","en":"When the client arrives click the appointment and \"Arrived\"; when the work is done, \"Done, to the invoice\"."}],"mistakes":[{"sq":"Pa email te \"Email (për kujtesën)\" klienti nuk merr kujtesë një ditë para terminit.","en":"Without an email under \"Email (for the reminder)\" the client gets no reminder the day before."}],"after":{"sq":"\"U krye, te fatura\" bën faturën me shërbimin dhe çmimin për ta kontrolluar, dhe e shton vizitën në kartelën e klientit.","en":"\"Done, to the invoice\" makes the invoice with the service and price for you to check, and adds the visit to the client card."},"related":[{"href":"/appointments/setup","label":"Shërbimet dhe stafi"},{"href":"/appointments/cards","label":"Dosjet e klientëve"}]},{"path":"/appointments/cards","title":"Dosjet e klientëve","title_en":"Client cards","section":"Terminet","perm":"sales.read","keywords":["kartela","pacient","automjet","targa","vetura","kafshë","historiku","vehicle","patient","pet"],"what":{"sq":"Dosjet e klientëve: vetura me targë e kilometra, pacienti, kafsha ose pajisja, me gjithë historikun vizitë pas vizite.","en":"Client cards: the car with its plate and kilometres, the patient, the pet or the device, with its whole history visit by visit."},"steps":[{"sq":"Zgjidh llojin lart dhe kërko me targë, emër ose telefon.","en":"Choose the kind on top and search by plate, name or phone."},{"sq":"Kliko butonin e kartelës së re lart djathtas, plotëso emrin ose targën dhe zgjidh klientin.","en":"Click the new-card button on the top right, fill in the name or plate and choose the client."},{"sq":"Hap një kartelë dhe kliko \"Shto në historik\" për të shkruar çfarë u bë.","en":"Open a card and click \"Add to the history\" to write down what was done."}],"mistakes":[{"sq":"Te termini zgjidh klientin dhe kartelën e tij: vetëm atëherë vizita dhe fatura shkojnë në historikun e kartelës.","en":"On the appointment choose the client and their card: only then do the visit and the invoice go into the card's history."}],"related":[{"href":"/appointments","label":"Kalendari i termineve"}]},{"path":"/appointments/memberships","title":"Anëtarësimet","title_en":"Memberships","section":"Terminet","perm":"sales.read","keywords":["anëtarësim","abonim","palestër","gym","karta","hyrje","membership"],"what":{"sq":"Anëtarësimet: shit anëtarësim mujor, vjetor ose me numër hyrjesh, kontrollo anëtarët te hyrja dhe shiko kujt i mbaron së shpejti.","en":"Memberships: sell a monthly, yearly or visit-based membership, check members in at the door, and see whose ends soon."},"steps":[{"sq":"Në fillim shto paketat te \"Paketat\" me \"Shto\": emri, muajt ose ditët, hyrjet dhe çmimi me TVSH.","en":"First add the plans under \"Plans\" with \"Add\": name, months or days, visits and price with VAT."},{"sq":"Kliko \"Shit një anëtarësim\", zgjidh anëtarin dhe paketën, pastaj \"Shit, te fatura\".","en":"Click \"Sell a membership\", choose the member and the plan, then \"Sell, to the invoice\"."},{"sq":"Te \"Te hyrja\" skano kartelën ose shkruaj numrin, telefonin ose emrin dhe kliko \"Check-in\".","en":"Under \"At the door\" scan the card or type its number, the phone or the name, and click \"Check in\"."},{"sq":"Zgjidh \"Mbarojnë brenda 7 ditëve\" dhe kliko \"Rinovo\" për ata që vazhdojnë.","en":"Choose \"Ending within 7 days\" and click \"Renew\" for those who continue."}],"mistakes":[{"sq":"Për një pushim të përkohshëm përdor \"Ngrije\", jo një shitje të re: ditët e ngrira shtohen në fund.","en":"For a temporary break use \"Freeze\", not a new sale: the frozen days are added at the end."}],"after":{"sq":"Çdo shitje bën një faturë për klientin; anëtari merr një numër kartele për hyrjen. Rinovimi fillon ditën pas mbarimit dhe mban të njëjtën kartelë.","en":"Each sale makes an invoice for the client; the member gets a card number for the door. A renewal starts the day after the current one ends and keeps the same card."},"related":[]},{"path":"/appointments/setup","title":"Shërbimet dhe stafi","title_en":"Services and staff","section":"Terminet","perm":"sales.read","keywords":["shërbime","punëtorë","orari","karrige","ngritës"],"what":{"sq":"Shërbimet dhe stafi: kush merr termine dhe çfarë bën, me kohëzgjatjen dhe çmimin.","en":"Services and staff: who takes appointments and what they do, with the length and the price."},"steps":[{"sq":"Te \"Kush punon\" kliko \"Shto\": një person, karrige, dhomë ose ngritës; secili bëhet një kolonë në kalendar.","en":"Under \"Who works\" click \"Add\": a person, chair, room or lift; each becomes a column of the calendar."},{"sq":"Cakto \"Orari i punës\" për çdo ditë; jashtë orarit kalendari del i hirtë.","en":"Set the \"Working hours\" for each day; outside them the calendar is grey."},{"sq":"Te \"Shërbime\" kliko \"Shto\": emri, minutat dhe çmimi me TVSH.","en":"Under \"Services\" click \"Add\": name, minutes and price with VAT."},{"sq":"Te \"Kush e bën\" zgjidh kush e kryen shërbimin; pa zgjedhur askënd, e bën kushdo.","en":"Under \"Who does it\" choose who performs the service; with nobody chosen, everyone can."}],"mistakes":[{"sq":"Çmimi i shërbimit është me TVSH dhe bëhet rresht në faturë: kontrollo normën e TVSH-së.","en":"The service price includes VAT and becomes an invoice line: check the VAT rate."}],"after":{"sq":"Kalendari hapet sapo të kesh të paktën një person ose vend pune.","en":"The calendar opens as soon as there is at least one person or place."},"related":[]},{"path":"/hotel","title":"Recepsioni","title_en":"Front desk","section":"Hotel","perm":"sales.read","keywords":["recepsion","reception","hotel","arrivals","mbërritje","check-in","check-out"],"what":{"sq":"Recepsioni: kush mbërrin, kush largohet dhe sa i zënë është hoteli sonte.","en":"The front desk: who arrives, who leaves, and how full the hotel is tonight."},"steps":[{"sq":"Te \"Mbërritjet sot\" kliko \"Check-in\" kur mysafiri vjen.","en":"Under \"Arrivals today\" click \"Check in\" when the guest arrives."},{"sq":"Te \"Largimet sot\" kliko \"Check-out\": hapet rezervimi për ta mbyllur.","en":"Under \"Departures today\" click \"Check out\": the reservation opens to close it."},{"sq":"Te \"Pastrimi i dhomave\" kliko \"Gati\" kur dhoma është pastruar.","en":"Under \"Housekeeping\" click \"Ready\" when a room has been cleaned."},{"sq":"Kliko \"Rezervim i ri\" për një rezervim, ose \"Kalendari i dhomave\" për të parë netët.","en":"Click \"New reservation\" for a booking, or \"Room calendar\" to see the nights."}],"mistakes":[],"after":{"sq":"Me check-out bëhet një faturë skicë me netët dhe shtesat; e konfirmon dhe merr pagesën aty. Dhoma kalon për pastrim.","en":"Check-out makes a draft invoice with the nights and extras; you confirm it and take the payment there. The room goes to cleaning."},"related":[{"href":"/hotel/reservations","label":"Rezervimet"},{"href":"/hotel/rooms","label":"Dhomat"}]},{"path":"/hotel/calendar","title":"Kalendari i dhomave","title_en":"Room calendar","section":"Hotel","perm":"sales.read","keywords":["kalendar","dhoma","rooms","availability","zënie","planner"],"what":{"sq":"Kalendari i dhomave: çdo dhomë dhe netët e saj për dy javë. Një qëndrim është një shirit nga mbërritja te largimi.","en":"The room calendar: every room and its nights for two weeks. A stay is a bar from arrival to departure."},"steps":[{"sq":"Lëviz me shigjetat ose kliko \"Sot\".","en":"Move with the arrows or click \"Today\"."},{"sq":"Kliko një natë të lirë te dhoma për ta rezervuar: dhoma dhe data plotësohen vetë.","en":"Click a free night on a room to book it: the room and the date fill in by themselves."},{"sq":"Kliko një shirit për të hapur rezervimin: ndrysho, bëj check-in ose check-out.","en":"Click a bar to open the reservation: change it, check in or check out."},{"sq":"Ngjyra e shiritit tregon statusin; pika te numri i dhomës tregon pastrimin.","en":"The bar's colour shows the status; the dot by the room number shows the cleaning state."}],"mistakes":[{"sq":"Dhoma \"Jashtë funksionit\" nuk rezervohet; ndryshoja gjendjen te \"Dhomat\" kur të rregullohet.","en":"A room \"Out of order\" cannot be booked; change its state under \"Rooms\" once it is fixed."}],"related":[]},{"path":"/hotel/reservations","title":"Rezervimet","title_en":"Reservations","section":"Hotel","perm":"sales.read","keywords":["rezervim","rezervime","booking","guest","mysafir","klient"],"what":{"sq":"Rezervimet: çdo qëndrim, i rezervuar, në hotel ose i larguar. Kërko sipas mysafirit, numrit ose telefonit.","en":"Reservations: every stay, booked, in the hotel or gone. Search by guest, number or phone."},"steps":[{"sq":"Kërko mysafirin ose filtro sipas statusit; kliko një rezervim për ta hapur.","en":"Search for the guest or filter by status; click a reservation to open it."},{"sq":"Për një të ri kliko \"Rezervim i ri\": shkruaj mysafirin, zgjidh dhomën, datat dhe çmimin për natë, pastaj \"Rezervo dhomën\".","en":"For a new one click \"New reservation\": type the guest, choose the room, dates and price a night, then \"Book the room\"."},{"sq":"Kur mysafiri është në hotel, shto te \"Shtesat në dhomë\" minibarin, mëngjesin ose lavanderinë.","en":"While the guest is in the hotel, add the minibar, breakfast or laundry under \"Extras on the room\"."}],"mistakes":[{"sq":"Nëse fatura duhet të dalë në emër të një firme, zgjidhe te \"Fatura në emër të (sipas dëshirës)\" para check-out.","en":"If the invoice must be in a company's name, choose it under \"Invoice to (optional)\" before check-out."}],"after":{"sq":"Shtesat dalin në faturë me check-out. Me \"Anulo rezervimin\" dhoma lirohet për ato net.","en":"Extras go on the invoice at check-out. \"Cancel the reservation\" frees the room for those nights."},"related":[]},{"path":"/hotel/rooms","title":"Dhomat","title_en":"Rooms","section":"Hotel","perm":"sales.read","keywords":["dhoma","housekeeping","pastrim","room types","çmime"],"what":{"sq":"Dhomat: llojet e dhomave me çmimin për natë, dhe çdo dhomë me gjendjen e pastrimit.","en":"Rooms: the room types with their price a night, and every room with its cleaning state."},"steps":[{"sq":"Te \"Llojet e dhomave\" kliko \"Shto\": emri (teke, dyshe, suitë), sa njerëz dhe çmimi për natë me TVSH.","en":"Under \"Room types\" click \"Add\": the name (single, double, suite), how many people and the price a night with VAT."},{"sq":"Te \"Dhomat\" kliko \"Shto dhomë\", shkruaj numrin dhe zgjidh llojin.","en":"Under \"Rooms\" click \"Add a room\", type the number and choose the type."},{"sq":"Ndrysho gjendjen te \"Pastrimi\": \"E pastër\", \"Për pastrim\", \"Për kontroll\" ose \"Jashtë funksionit\".","en":"Change the state under \"Cleaning\": \"Clean\", \"To clean\", \"To inspect\" or \"Out of order\"."}],"mistakes":[{"sq":"Akomodimi shpesh ka TVSH të reduktuar: zgjidh normën te lloji i dhomës dhe pyet kontabilistin.","en":"Accommodation often has a reduced VAT rate: choose it on the room type and check with your accountant."}],"after":{"sq":"Rezervimi i ri merr çmimin nga lloji i dhomës; mund ta ndryshosh te rezervimi.","en":"A new reservation takes its price from the room type; you can change it on the reservation."},"related":[]},{"path":"/manufacturing","title":"Pasqyra e prodhimit","title_en":"Production overview","section":"Prodhimi","perm":"manufacturing.read","keywords":["production","mrp","plan","prodhim","capacity"],"what":{"sq":"Pasqyra e prodhimit: çka po prodhohet, çka duhet prodhuar dhe sa kushton, pa TVSH.","en":"Production overview: what is being made, what to make next and what it costs, without VAT."},"steps":[{"sq":"Zgjidh periudhën; kartat tregojnë urdhrat në prodhim, ata me vonesë dhe vlerën e prodhuar.","en":"Choose the period; the cards show orders in production, late ones and the value produced."},{"sq":"Te \"Plani i prodhimit\" shiko \"Për t'u prodhuar\" dhe kliko \"Planifiko …\" për urdhrin e punës me atë sasi.","en":"In the \"Production plan\" look at \"To make\" and click \"Plan …\" for a work order with that quantity."},{"sq":"Te \"Ngarkesa e qendrave të punës\" e kuqja tregon ditët me më shumë punë se orë.","en":"In \"Work center load\" red shows the days with more work than hours."},{"sq":"Me \"Urdhër pune i ri\" ose \"Recetë e re\" fillon nga e para.","en":"Start from scratch with \"New work order\" or \"New recipe\"."}],"mistakes":[{"sq":"Në plan dalin vetëm artikujt me recetë; kur stoku bie nën minimum, plani e mbush deri te maksimumi.","en":"Only items with a recipe are in the plan; when stock falls below the minimum, the plan fills up to the maximum."}],"related":[{"href":"/manufacturing/orders","label":"Urdhrat e punës"},{"href":"/manufacturing/boms","label":"Recetat"}]},{"path":"/manufacturing/orders","title":"Urdhrat e punës","title_en":"Work orders","section":"Prodhimi","perm":"manufacturing.read","keywords":["wo","production order","manufacturing order","urdhër pune"],"what":{"sq":"Urdhrat e punës: çka po prodhohet, nga planifikimi deri te mbyllja.","en":"Work orders: what is being made, from planned to closed."},"steps":[{"sq":"Kliko \"Urdhër pune i ri\", zgjidh produktin dhe sasinë: materialet dhe hapat vijnë nga receta.","en":"Click \"New work order\", choose the product and quantity: materials and steps come from the recipe."},{"sq":"Shiko si \"Lista\" ose si \"Tabela\" sipas statusit; të vonuarat shënohen \"Me vonesë\".","en":"View as a \"List\" or as a \"Board\" by status; late ones are marked \"Late\"."},{"sq":"Kliko një urdhër për ta lëshuar në prodhim, për të përdorur materialet dhe për të regjistruar prodhimin.","en":"Click an order to release it, use the materials and book the output."}],"mistakes":[{"sq":"Lista tregon në fillim vetëm urdhrat aktivë; për të mbyllurit dhe të anuluarit ndrysho filtrin e statusit.","en":"The list first shows only active orders; change the status filter for closed and cancelled ones."}],"after":{"sq":"Përdorimi i materialeve dhe regjistrimi i prodhimit lëvizin stokun; mbyllja e urdhrit e barazon koston në kontabilitet.","en":"Using materials and booking output move the stock; closing the order settles the cost in the books."},"related":[]},{"path":"/manufacturing/boms","title":"Receta prodhimi","title_en":"Bills of materials","section":"Prodhimi","perm":"manufacturing.read","keywords":["receta","recipe","kit","ingredients","përbërës","kafe","restorant"],"what":{"sq":"Recetat: nga çka përbëhet çdo produkt dhe si bëhet.","en":"Recipes: what each product is made of and how."},"steps":[{"sq":"Kliko \"Recetë e re\", zgjidh produktin që prodhon dhe sasinë e serisë.","en":"Click \"New recipe\", choose the product it makes and the batch quantity."},{"sq":"Shto përbërësit me sasinë për një seri; \"Firo %\" shton humbjen e pritur.","en":"Add the components with the quantity for one batch; \"Waste %\" adds the expected loss."},{"sq":"Shto hapat me qendrën e punës dhe minutat: nga to llogaritet kostoja e punës.","en":"Add the steps with the work center and minutes: the labour cost is worked out from them."},{"sq":"Zgjidh llojin: \"Prodhimi\" për urdhra pune, ose \"Set ose recetë: përbërësit dalin nga stoku kur shitet\".","en":"Choose the type: \"Production\" for work orders, or \"Kit or recipe: its parts leave stock when it is sold\"."}],"mistakes":[{"sq":"Fillo nga lëndët e para: së pari gjysmëproduktet, pastaj produktet që bëhen prej tyre.","en":"Start from the raw materials: semi-finished products first, then the products made from them."},{"sq":"Një produkt mund të ketë disa receta; përdoret ajo me \"Receta kryesore për këtë produkt\".","en":"A product can have several recipes; the one marked \"Main recipe for this product\" is used."}],"related":[{"href":"/manufacturing/work-centers","label":"Makinat dhe linjat"},{"href":"/manufacturing/orders","label":"Urdhrat e punës"}]},{"path":"/manufacturing/work-centers","title":"Makinat dhe linjat","title_en":"Work centers","section":"Prodhimi","perm":"manufacturing.read","keywords":["machines","lines","capacity","rates"],"what":{"sq":"Makinat, linjat dhe ekipet ku bëhet puna, me koston e tyre për orë.","en":"The machines, lines and teams where the work is done, with their cost per hour."},"steps":[{"sq":"Kliko \"Qendër pune e re\" dhe shkruaj kodin dhe emrin.","en":"Click \"New work center\" and type the code and name."},{"sq":"Shkruaj \"Puna për orë\" dhe \"Shpenzime të përgjithshme për orë\" (energji, amortizim, pjesë e qirasë).","en":"Type the \"Labour per hour\" and \"Overhead per hour\" (energy, depreciation, share of rent)."},{"sq":"Cakto \"Orë në ditë\" dhe \"Efikasiteti %\": te 80% çdo hap zgjat 25% më shumë.","en":"Set the \"Hours per day\" and \"Efficiency %\": at 80% every step takes 25% longer."},{"sq":"Poshtë shiko ngarkesën e dy javëve të ardhshme; e kuqja do të thotë më shumë punë se orë.","en":"Below, see the load for the next two weeks; red means more work than hours."}],"mistakes":[],"after":{"sq":"Koha e raportuar në urdhrat e punës shumëzohet me këto tarifa dhe bëhet kosto pune dhe shpenzime në produkt.","en":"Time reported on work orders is multiplied by these rates and becomes labour and overhead cost in the product."},"related":[{"href":"/manufacturing/boms","label":"Recetat"}]},{"path":"/logistics","title":"Pasqyra e logjistikës","title_en":"Logistics overview","section":"Transporti","perm":"logistics.read","keywords":["transport","fleet","kpi","transport"],"what":{"sq":"Pasqyra e logjistikës: çka pret të niset, çka është në rrugë dhe si shkojnë dorëzimet.","en":"Logistics overview: what is waiting to go out, what is on the road and how deliveries are going."},"steps":[{"sq":"Zgjidh periudhën; \"Për t'u nisur\" janë dërgesat e mbledhura që s'janë ende në itinerar.","en":"Choose the period; \"To dispatch\" are picked deliveries not on a route yet."},{"sq":"Te \"Itineraret e sotme\" sheh ndalesat e kryera dhe ngarkesën e çdo mjeti.","en":"Under \"Today's routes\" see the stops done and each vehicle's load."},{"sq":"Kontrollo \"Pagesë në dorëzim për t'u dorëzuar në arkë\": paratë që shoferët i mblodhën por s'janë në arkë.","en":"Check \"Cash on delivery to settle\": money drivers collected that is not in the cash box yet."},{"sq":"Kliko \"Planifiko dërgesat\" për të krijuar itineraret.","en":"Click \"Plan deliveries\" to create the routes."}],"mistakes":[],"related":[{"href":"/logistics/planning","label":"Planifikimi i transportit"},{"href":"/logistics/shipments","label":"Transportet"}]},{"path":"/logistics/planning","title":"Planifikimi i transportit","title_en":"Delivery planning","section":"Transporti","perm":"logistics.read","keywords":["routes","dispatch","vans","drivers","plan"],"what":{"sq":"Planifikimi i transportit: dërgesat e mbledhura bëhen transporte dhe vendosen në një furgon ose te një korrier.","en":"Delivery planning: picked deliveries become shipments and go on a van or to a carrier."},"steps":[{"sq":"Te \"Në pritje për t'u nisur\" kliko \"Krijo transport\" te dërgesa; shkruaj pagesën në dorëzim nëse klienti paguan kur e merr.","en":"Under \"Waiting to go out\" click \"Create shipment\" on a delivery; type the cash on delivery if the customer pays on receipt."},{"sq":"Zgjidh transportet (janë sipas qytetit) dhe kliko \"Itinerar i ri\", ose \"Shto te …\" për një itinerar që ekziston.","en":"Select the shipments (grouped by city) and click \"New route\", or \"Add to …\" for an existing route."},{"sq":"Zgjidh mjetin, shoferin dhe nga niset; programi paralajmëron nëse pesha kalon kapacitetin.","en":"Choose the vehicle, driver and where it leaves from; the program warns if the weight is over capacity."},{"sq":"Për korrier të jashtëm kliko \"Transportuesi\" te transporti dhe shkruaj numrin e gjurmimit.","en":"For an outside courier click \"Carrier\" on the shipment and type the tracking number."},{"sq":"Kliko \"Hap fletën e itinerarit\" për renditjen e ndalesave dhe për shoferin.","en":"Click \"Open route sheet\" to order the stops and for the driver."}],"mistakes":[{"sq":"Shoferi duhet të konfirmojë që i mori paratë e pagesës në dorëzim, përndryshe ndalesa nuk llogaritet e dorëzuar.","en":"The driver must confirm the cash on delivery was collected, or the stop does not count as delivered."}],"after":{"sq":"Kur pakoja i jepet korrierit, malli del nga stoku (nëse depoja s'e ka nxjerrë ende).","en":"When the parcel is handed to the carrier, the goods leave stock (if the warehouse has not done it yet)."},"related":[]},{"path":"/logistics/shipments","title":"Transportet","title_en":"Shipments","section":"Transporti","perm":"logistics.read","keywords":["tracking","carrier","cod","cash on delivery","dërgesa"],"what":{"sq":"Transportet: çdo pako që del, me furgonin tonë ose me korrier, me gjurmim dhe pagesë në dorëzim.","en":"Shipments: every parcel that leaves, on our vans or with a carrier, with tracking and cash on delivery."},"steps":[{"sq":"Filtro sipas statusit, transportuesit ose \"Pagesë në dorëzim\".","en":"Filter by status, carrier or \"Cash on delivery\"."},{"sq":"Kliko numrin e gjurmimit për ta ndjekur pakon te faqja e korrierit.","en":"Click the tracking number to follow the parcel on the carrier's page."},{"sq":"Kliko një transport për ta shënuar të dorëzuar ose të padorëzuar.","en":"Click a shipment to mark it delivered or not delivered."},{"sq":"Për paratë që solli shoferi: zgjidh ato \"Mbledhur, jo në arkë\", kliko \"Dorëzo në arkë paratë e mbledhura\", zgjidh arkën ose bankën dhe \"Regjistro arkëtimet\".","en":"For cash the drivers brought in: select those \"Collected, not settled\", click \"Settle cash on delivery\", choose the cash box or bank and \"Record receipts\"."}],"mistakes":[],"after":{"sq":"Çdo transport i dorëzuar në arkë bëhet arkëtim nga klienti dhe lidhet me faturat e hapura të porosisë.","en":"Each settled shipment becomes a customer receipt, applied to the order's open invoices."},"related":[{"href":"/logistics/planning","label":"Planifikimi i transportit"},{"href":"/finance/payments","label":"Pagesat"}]},{"path":"/logistics/setup","title":"Mjetet dhe korrierët","title_en":"Carriers and fleet","section":"Transporti","perm":"logistics.read","keywords":["vehicles","carriers","vans","courier"],"what":{"sq":"Mjetet dhe korrierët: furgonët tanë me shoferët, dhe kompanitë korriere që u japim pakot.","en":"Carriers and fleet: our own vans and drivers, and the courier companies we hand parcels to."},"steps":[{"sq":"Kliko \"Shto transportues\" për çdo korrier dhe zgjidh \"Kompani korriere\" ose \"Mjetet tona\".","en":"Click \"Add carrier\" for each courier and choose \"Courier company\" or \"Our own vehicles\"."},{"sq":"Te \"Lidhja e gjurmimit\" vendos adresën e faqes së gjurmimit me {tracking}: numri i gjurmimit bëhet lidhje.","en":"In \"Tracking link\" put the tracking page address with {tracking}: the tracking number becomes a link."},{"sq":"Kliko \"Shto mjet\" dhe shkruaj targën, \"Kapaciteti i ngarkesës (kg)\" dhe \"Shoferi i zakonshëm\".","en":"Click \"Add vehicle\" and type the plate, the \"Load capacity (kg)\" and the \"Usual driver\"."}],"mistakes":[],"after":{"sq":"Kapaciteti kontrollohet kur vendos transporte në itinerar, dhe shoferi i zakonshëm propozohet vetë.","en":"The capacity is checked when you put shipments on a route, and the usual driver is suggested."},"related":[{"href":"/logistics/planning","label":"Planifikimi i transportit"}]},{"path":"/wms","title":"Paneli i skanerit","title_en":"Warehouse floor","section":"Skaneri","perm":"wms.read","keywords":["wms","scanner","handheld","magazina"],"what":{"sq":"Paneli i skanerit: ekranet e depos për pranim, vendosje në raft, mbledhje, dërgim, lëvizje dhe numërim.","en":"The warehouse floor: scanner screens for receiving, putting away, picking, shipping, moving and counting."},"steps":[{"sq":"Zgjidh njësinë lart djathtas; programi e mban mend në këtë pajisje.","en":"Choose the unit at the top right; the program remembers it on this device."},{"sq":"Kliko një kuadrat ose shtyp tastin 1–7; numri tregon sa punë presin.","en":"Click a tile or press 1–7; the number shows how much work is waiting."},{"sq":"Çdo ekran punon me skaner, me kamerën e telefonit ose me tastierë.","en":"Each screen works with a scanner, the phone camera or the keyboard."}],"mistakes":[{"sq":"Malli në zonën e pranimit nuk mblidhet për porosi derisa të vendoset në raft: kliko \"Vendos në raft nga …\".","en":"Goods in the receiving area cannot be picked until they are put away: click \"Put away …\"."}],"related":[{"href":"/wms/receive","label":"Prano mallin"},{"href":"/wms/picking","label":"Mblidh mallin"}]},{"path":"/wms/receive","title":"Prano mallin","title_en":"Receive","section":"Skaneri","perm":"wms.read","keywords":["receiving","dock","grn","scan in"],"what":{"sq":"Pranimi me skaner: malli që pritet, i numëruar artikull për artikull.","en":"Receiving with the scanner: the expected goods, counted item by item."},"steps":[{"sq":"Skano numrin e porosisë, të pranimit ose të fletëdërgesës, ose kliko furnitorin në listë.","en":"Scan the order, receipt or delivery note number, or click the vendor in the list."},{"sq":"Skano çdo artikull; për artikujt me lot skano etiketën e lotit ose shkruaj numrin dhe datën e skadimit.","en":"Scan each item; for items with lots scan the lot label or type the number and expiry date."},{"sq":"Kliko një rresht për të shkruar sasinë me dorë; rreshti bëhet i gjelbër kur përputhet.","en":"Click a line to type the quantity; the line turns green when it matches."},{"sq":"Kliko \"Prano … njësi\" dhe konfirmo.","en":"Click \"Receive … units\" and confirm."}],"mistakes":[{"sq":"Numërimi ruhet në pajisje edhe nëse fiket; \"Fillo nga e para\" e fshin dhe nis nga zero.","en":"The count is kept on the device even if it switches off; \"Start over\" clears it and starts from zero."}],"after":{"sq":"Malli hyn në zonën e pranimit dhe krijohet vetë detyra për ta vendosur në raft. Porosia e blerjes mban hapur atë që mungon.","en":"The goods go into the receiving area and a put-away task is created. The purchase order keeps open whatever is missing."},"related":[{"href":"/wms/putaway","label":"Vendos në raft"}]},{"path":"/wms/putaway","title":"Vendos në raft","title_en":"Put away","section":"Skaneri","perm":"wms.read","keywords":["putaway","bins","storage"],"what":{"sq":"Vendosja në raft: malli i pranuar kalon nga zona e pranimit te raftet ku ruhet.","en":"Putting away: received goods move from the receiving area to the shelves where they are kept."},"steps":[{"sq":"Kliko një detyrë; për çdo pranim krijohet vetë një e tillë.","en":"Click a task; one is created for every receipt."},{"sq":"Programi tregon artikullin dhe raftet e propozuara: kliko njërin ose skano etiketën e çdo rafti tjetër.","en":"The program shows the item and suggested shelves: click one or scan any other shelf label."},{"sq":"Ndrysho sasinë nëse e ndan mallin në disa rafte; skano një artikull tjetër për të kaluar te ai.","en":"Change the quantity to split the goods over several shelves; scan another item to switch to it."},{"sq":"Kur vendoset çdo rresht, detyra mbyllet vetë.","en":"When every line is put away, the task closes by itself."}],"mistakes":[{"sq":"\"Mblidh të gjitha nga …\" bën një detyrë për gjithë mallin që ka mbetur në zonën e pranimit.","en":"\"Collect all from …\" makes one task for everything still lying in the receiving area."}],"after":{"sq":"Malli kalon në raftet e reja pa ndryshuar vlerë dhe tani mund të mblidhet për porosi.","en":"The goods move to the new shelves without changing value and can now be picked for orders."},"related":[]},{"path":"/wms/picking","title":"Mblidh mallin","title_en":"Pick","section":"Skaneri","perm":"wms.read","keywords":["picking","pick list","orders"],"what":{"sq":"Mbledhja e mallit për dërgesat e klientëve, me listë mbledhjeje.","en":"Picking goods for customer deliveries, with a pick list."},"steps":[{"sq":"Te \"Për t’u mbledhur\" zgjidh një ose disa dërgesa të së njëjtës njësi dhe kliko \"Fillo mbledhjen\".","en":"Under \"To pick\" select one or more deliveries from the same unit and click \"Start picking\"."},{"sq":"Shko te rafti që tregohet, skano raftin, pastaj çdo artikull.","en":"Go to the shelf shown, scan the shelf, then each item."},{"sq":"Nëse mungon malli, kliko \"Mungesë — u gjetën …\"; me \"Kaloje për tani\" kalon te rreshti tjetër.","en":"If goods are missing, click \"Short — … found\"; \"Skip for now\" moves to the next line."},{"sq":"Kur mblidhet gjithçka, kliko \"Përfundo listën e mbledhjes\".","en":"When everything is picked, click \"Finish pick list\"."}],"mistakes":[{"sq":"Nëse e merr mallin nga një raft tjetër, skano atë raft: programi regjistron nga ku u mor.","en":"If you take the goods from another shelf, scan that shelf: the program records where they came from."}],"after":{"sq":"Dërgesat bëhen gati dhe dalin te \"Dërgo\". Artikujt që mungojnë hiqen nga dërgesa; porosia i mban për më vonë.","en":"The deliveries become ready and show under \"Ship\". Missing items are taken off the delivery; the order keeps them for later."},"related":[{"href":"/wms/shipping","label":"Dërgo"}]},{"path":"/wms/shipping","title":"Dërgo","title_en":"Ship","section":"Skaneri","perm":"wms.read","keywords":["shipping","dispatch","tracking","carrier"],"what":{"sq":"Dërgimi: dërgesat e mbledhura që presin të nisen.","en":"Shipping: picked deliveries waiting to leave."},"steps":[{"sq":"Skano numrin e dërgesës ose të porosisë, ose kliko \"Dërgo\" te dërgesa.","en":"Scan the delivery or order number, or click \"Ship\" on the delivery."},{"sq":"Printo \"Fletë paketimi\" dhe fute në pako.","en":"Print the \"Packing slip\" and put it in the parcel."},{"sq":"Shkruaj transportuesin, numrin e gjurmimit, pakot dhe peshën, pastaj kliko \"Konfirmo dërgimin\".","en":"Type the carrier, tracking number, parcels and weight, then click \"Confirm shipment\"."}],"mistakes":[],"after":{"sq":"Malli del nga stoku dhe regjistrohet kostoja e mallit të shitur; dërgesa del te \"Dërguar së fundi\".","en":"The goods leave stock and the cost of goods sold is booked; the delivery shows under \"Recently shipped\"."},"related":[{"href":"/sales/deliveries","label":"Dërgesat"},{"href":"/logistics/planning","label":"Planifikimi i transportit"}]},{"path":"/wms/move","title":"Lëviz mallin","title_en":"Move stock","section":"Skaneri","perm":"wms.read","keywords":["bin to bin","relocate","internal transfer"],"what":{"sq":"Lëvizja e mallit nga një raft te tjetri, me tre skanime.","en":"Moving goods from one shelf to another, in three scans."},"steps":[{"sq":"Skano raftin ku është malli.","en":"Scan the shelf the goods are on."},{"sq":"Skano artikujt që lëviz (ose kliko në listën e raftit); kliko sasinë për ta ndryshuar.","en":"Scan the items to move (or click them in the shelf list); click the quantity to change it."},{"sq":"Skano raftin ku i çon: lëvizja kryhet menjëherë.","en":"Scan the shelf you take them to: the move is done at once."}],"mistakes":[{"sq":"Lëviz vetëm sasia e lirë: malli i rezervuar për porosi nuk lëvizet.","en":"Only the free quantity moves: goods reserved for orders cannot be moved."}],"after":{"sq":"Lëvizja ruhet si transferim i kryer dhe del te Transferet; vlera e stokut nuk ndryshon.","en":"The move is saved as a completed transfer and shows under Transfers; the stock value does not change."},"related":[{"href":"/inventory/transfers","label":"Transferet"}]},{"path":"/hr","title":"Pasqyra e personelit","title_en":"People overview","section":"Punonjësit","perm":"hr.read","keywords":["hr","headcount","burime njerëzore"],"what":{"sq":"Pasqyra e personelit: sa punonjës ke, kush është në punë ose me leje sot, dhe sa kushtojnë pagat.","en":"The people overview: how many employees you have, who is at work or on leave today, and what salaries cost."},"steps":[{"sq":"Kliko kartelat lart (\"Në punë sot\", \"Me leje sot\", \"Leje për t'u vendosur\") për të hapur listën përkatëse.","en":"Click the tiles on top (\"At work today\", \"On leave today\", \"Leave to decide\") to open that list."},{"sq":"\"Kostoja e pagave\" tregon muajt me pagë përfundimtare: bruto plus kontributet e punëdhënësit, dhe sa morën punonjësit neto.","en":"\"Salary cost\" shows the months with a final payroll: gross plus employer contributions, and what employees received net."},{"sq":"Te \"Kontrata që mbarojnë\" sheh kontratat me afat që mbarojnë në 60 ditët e ardhshme; kliko emrin për të hapur punonjësin.","en":"Under \"Contracts ending\" see the fixed-term contracts ending in the next 60 days; click a name to open the employee."},{"sq":"Me \"Punonjës i ri\" shton një punonjës; te \"Cilësimet e personelit\" cakton departamentet, pozicionet dhe llojet e lejeve.","en":"With \"New employee\" add a person; under \"HR setup\" set the departments, positions and leave types."}],"mistakes":[],"related":[{"href":"/hr/employees","label":"Punonjësit"},{"href":"/hr/payroll","label":"Pagat"}]},{"path":"/hr/setup","title":"Cilësimet e personelit","title_en":"HR setup","section":"Punonjësit","perm":"hr.read","keywords":["cilësimet e punonjësve","departamente","pozita","pushime","hr settings","departments","positions"],"what":{"sq":"Cilësimet e personelit: departamentet, pozicionet e punës, llojet e lejeve dhe festat zyrtare.","en":"HR setup: departments, job positions, leave types and public holidays."},"steps":[{"sq":"Te \"Departamentet\" kliko \"Departament i ri\" dhe zgjidh menaxherin dhe qendrën e kostos.","en":"Under \"Departments\" click \"New department\" and choose the manager and the cost center."},{"sq":"Te \"Pozicionet\" shkruaj titujt e punës: ato dalin në fletëpagesë dhe në listën për tatimet.","en":"Under \"Positions\" type the job titles: they show on payslips and on the payroll list for the tax office."},{"sq":"Te \"Llojet e lejeve\" cakto \"Ditë në vit\" (0 do të thotë pa kufi, p.sh. pushimi mjekësor) dhe nëse leja paguhet.","en":"Under \"Leave types\" set \"Days per year\" (0 means no limit, e.g. sick leave) and whether the leave is paid."},{"sq":"Te \"Festat zyrtare\" kliko \"Shto festë\" për çdo festë të vitit.","en":"Under \"Public holidays\" click \"Add holiday\" for each holiday of the year."}],"mistakes":[{"sq":"Kur festa bie në fundjavë, shkruaj ditën ku zhvendoset pushimi, jo të shtunën ose të dielën.","en":"When a holiday falls on a weekend, enter the day it moves to, not the Saturday or Sunday."},{"sq":"Një departament, pozicion ose lloj leje fshihet vetëm kur nuk e përdor askush.","en":"A department, position or leave type can only be deleted while nothing uses it."}],"after":{"sq":"Pagat regjistrohen te qendra e kostos e departamentit, nëse punonjësi nuk ka të vetën. Festat nuk numërohen as si leje, as si ditë pune; leja pa pagesë ul pagën.","en":"Salaries are booked on the department's cost center unless the employee has their own. Holidays count neither as leave nor as working days; unpaid leave reduces pay."},"related":[]},{"path":"/hr/employees","title":"Punonjësit","title_en":"Employees","section":"Punonjësit","perm":"hr.read","keywords":["staff","punonjës","contracts"],"what":{"sq":"Të gjithë punonjësit, me departamentin, menaxherin dhe kontratën.","en":"Everyone who works here, with their department, manager and contract."},"steps":[{"sq":"Kliko \"Punonjës i ri\" për një punonjës, ose \"Importo\" për shumë njëherësh nga Excel-i.","en":"Click \"New employee\" for one person, or \"Import\" for many at once from Excel."},{"sq":"Kërko me emër, numër ose email; filtro sipas departamentit, pozicionit ose statusit.","en":"Search by name, number or email; filter by department, position or status."},{"sq":"Lista tregon aktivët dhe ata me leje; për ata që janë larguar ndrysho filtrin \"Statusi\".","en":"The list shows active people and those on leave; for people who left, change the \"Status\" filter."},{"sq":"Kliko një punonjës për profilin, kontratën, lejet, prezencën dhe fletëpagesat.","en":"Click an employee for the profile, contract, leave, attendance and payslips."}],"mistakes":[],"related":[{"href":"/hr/setup","label":"Cilësimet e personelit"},{"href":"/settings/import","label":"Importi"}]},{"path":"/hr/contracts","title":"Kontratat","title_en":"Contracts","section":"Punonjësit","perm":"payroll.read","keywords":["kontrata","kontratat e punës","aneks","employment contract","annex","ndërprerje","njoftim"],"what":{"sq":"Të gjitha kontratat e punës dhe anekset: cilat janë në fuqi, cilat presin nënshkrimin, cilat mbarojnë së shpejti dhe kush është në provë.","en":"Every employment contract and annex: which are in force, which wait for a signature, which end soon and who is on probation."},"steps":[{"sq":"Kliko \"Kontratë e re\", zgjidh punonjësin dhe plotëso kushtet: lloji, data, pozita, paga bruto, orari, prova, pushimi.","en":"Click \"New contract\", choose the employee and fill in the terms: type, dates, position, gross pay, hours, probation, leave."},{"sq":"Programi e shkruan kontratën nga modeli i vendit tënd (Kosovë ose Shqipëri), me nenet që kërkon ligji.","en":"The program writes the contract from your country's model (Kosovo or Albania), with the articles the law asks for."},{"sq":"Përdor butonat sipër listës: \"Pa nënshkruar\", \"Mbarojnë brenda 60 ditëve\", \"Në provë\".","en":"Use the buttons above the list: \"Not signed yet\", \"Ending in 60 days\", \"On probation\"."}],"mistakes":[{"sq":"Kontrata që nuk është shënuar e nënshkruar nuk hyn në listëpagesë derisa ta shënosh.","en":"A draft contract is not in payroll until you mark it signed."}],"after":{"sq":"Një javë para se të mbarojë prova dhe 30 ditë para se të mbarojë kontrata me afat, menaxheri i HR merr kujtesë.","en":"A week before probation ends and 30 days before a fixed-term contract ends, the HR manager gets a reminder."},"related":[{"href":"/hr/employees","label":"Punonjësit"},{"href":"/hr/setup","label":"Modelet e kontratave"}]},{"path":"/hr/leave","title":"Leje","title_en":"Leave","section":"Punonjësit","perm":"hr.read","keywords":["holiday","vacation","pushime","absence","sick"],"what":{"sq":"Lejet: kërkesat, vendimet dhe sa ditë i kanë mbetur secilit këtë vit.","en":"Leave: requests, decisions and what everyone has left this year."},"steps":[{"sq":"Kliko \"Kërko leje\", zgjidh punonjësin, llojin e lejes dhe datat; numërohen vetëm ditët e punës.","en":"Click \"Ask for leave\", choose the employee, the type of leave and the dates; only working days count."},{"sq":"\"Ruaj si skicë\" e mban për më vonë; \"Dërgo kërkesën\" e dërgon për vendim.","en":"\"Save draft\" keeps it for later; \"Send request\" sends it for a decision."},{"sq":"Kliko një kërkesë që pret dhe zgjidh \"Mirato lejen\" ose \"Refuzo\"; mund t'i shkruash edhe një shënim punonjësit.","en":"Click a waiting request and choose \"Approve leave\" or \"Reject\"; you can also write a note to the employee."},{"sq":"Te \"Ditët e mbetura\" sheh për çdo punonjës sa ditë ka në vit, sa ka marrë dhe sa i kanë mbetur.","en":"Under \"Days left\" see for each employee their days per year, what they took and what is left."}],"mistakes":[{"sq":"Fundjavat dhe festat zyrtare nuk numërohen; nëse ditët dalin gabim, kontrollo festat te \"Cilësimet e personelit\".","en":"Weekends and public holidays do not count; if the days look wrong, check the holidays in \"HR setup\"."}],"after":{"sq":"Leja e miratuar del te prezenca dhe zbret nga ditët e mbetura; leja pa pagesë ul pagën e muajit.","en":"Approved leave shows in attendance and comes off the days left; unpaid leave reduces that month's pay."},"related":[{"href":"/hr/attendance","label":"Prezenca"},{"href":"/hr/setup","label":"Cilësimet e personelit"}]},{"path":"/hr/attendance","title":"Prezenca","title_en":"Attendance","section":"Punonjësit","perm":"hr.read","keywords":["timesheet","clock in","prezenca","overtime"],"what":{"sq":"Prezenca: muaji i çdo punonjësi me një shikim, ditët në punë me orë, lejet, festat dhe mungesat.","en":"Attendance: each person's month at a glance, days at work with hours, leave, holidays and missing days."},"steps":[{"sq":"Zgjidh muajin me shigjetat dhe, nëse do, një departament.","en":"Choose the month with the arrows and, if you like, a department."},{"sq":"Çdo katror është një ditë: numri tregon orët e punuara, shkronja tregon leje, festë ose mungesë.","en":"Each box is one day: a number shows the hours worked, a letter shows leave, a holiday or an absence."},{"sq":"Kliko një ditë për të shtuar ose korrigjuar \"Hyrja\", \"Dalja\" dhe \"Orë shtesë (h)\", pastaj \"Ruaj\".","en":"Click a day to add or correct \"In\", \"Out\" and \"Overtime (h)\", then \"Save\"."},{"sq":"Në fund të rreshtit sheh orët, orët shtesë, ditët në punë dhe mungesat e muajit.","en":"At the end of the row see the month's hours, overtime, days present and absences."}],"mistakes":[{"sq":"Një ditë pune pa regjistrim dhe pa leje del si mungesë: korrigjoje para pagave nëse punonjësi ishte në punë.","en":"A working day with no record and no leave shows as absent: correct it before payroll if the person was at work."}],"after":{"sq":"Orët shtesë nga prezenca paguhen me shtesën ligjore kur llogaritet paga.","en":"Overtime from attendance is paid at the legal premium when payroll is calculated."},"related":[]},{"path":"/hr/payroll","title":"Pagat","title_en":"Payroll","section":"Punonjësit","perm":"payroll.read","keywords":["salaries","payslips","listëpagesa","tap","contributions","paga"],"what":{"sq":"Pagat: një listëpagesë për çdo muaj, e llogarit, e miraton dikush tjetër, bëhet përfundimtare dhe paguhet.","en":"Payroll: one payroll per month, calculated, approved by someone else, made final, then paid."},"steps":[{"sq":"Kliko \"Listëpagesë e re mujore\", zgjidh muajin dhe datën e pagesës, pastaj \"Krijo listëpagesën\".","en":"Click \"New monthly payroll\", choose the month and the pay date, then \"Create payroll\"."},{"sq":"Në të hyjnë të gjithë punonjësit me kontratë aktive.","en":"Everyone with an active contract is included."},{"sq":"Kliko një listëpagesë për ta llogaritur, miratuar dhe paguar; filtro sipas statusit për ato që presin.","en":"Click a payroll to calculate, approve and pay it; filter by status for the ones waiting."}],"mistakes":[{"sq":"Punonjësi pa kontratë aktive nuk del në listëpagesë: shtoja kontratën te kartela e tij.","en":"A person without an active contract is not on the payroll: add the contract on their file."}],"related":[{"href":"/hr/employees","label":"Punonjësit"},{"href":"/settings/automation","label":"Automatizimet"}]},{"path":"/hr/me","title":"Vendi im i punës","title_en":"My workplace","section":"Punonjësit","perm":"core.read","keywords":["my leave","my payslips","clock in","self-service"],"what":{"sq":"Vendi im i punës: regjistro hyrjen dhe daljen, kërko leje dhe shiko fletëpagesat e tua.","en":"My workplace: clock in and out, ask for leave and see your payslips."},"steps":[{"sq":"Kur vjen në punë kliko \"Regjistro hyrjen\"; kur ikën, \"Regjistro daljen\".","en":"When you arrive click \"Clock in\"; when you leave, \"Clock out\"."},{"sq":"Kliko \"Kërko leje\", zgjidh llojin e lejes dhe datat, pastaj \"Dërgo kërkesën\".","en":"Click \"Ask for leave\", choose the type of leave and the dates, then \"Send request\"."},{"sq":"Te kartela e lejeve sheh sa ditë të kanë mbetur këtë vit.","en":"The leave card shows how many days you have left this year."},{"sq":"Kliko një muaj te \"Fletëpagesat e mia\" për ta parë fletëpagesën.","en":"Click a month under \"My payslips\" to see the payslip."}],"mistakes":[{"sq":"Nëse faqja thotë se llogaria jote nuk është lidhur me punonjës, kërkoji personelit ta lidhë te kartela jote.","en":"If the page says your login is not linked to an employee, ask HR to link it on your employee file."}],"after":{"sq":"Nëse je menaxher, kërkesat e ekipit dalin poshtë te \"Lejet e ekipit tuaj\": mirato ose refuzo direkt aty.","en":"If you are a manager, your team's requests show below under \"Your team's leave\": approve or reject them right there."},"related":[]},{"path":"/reports","title":"Raportet","title_en":"Reports","section":"Raportet","perm":"reports.read","keywords":["analytics","sales analysis","margin","valuation","aging","raporte"],"what":{"sq":"Raportet: shitjet, blerjet, stoku, financat dhe tatimet, secili raport si një pyetje.","en":"Reports: sales, purchasing, stock, finance and tax, each report as a question."},"steps":[{"sq":"Kliko raportin që i përgjigjet pyetjes tënde.","en":"Click the report that answers your question."},{"sq":"Zgjidh periudhën dhe si grupohen shifrat te \"Grupo sipas\"; me \"Në kolona\" e kthen në tabelë me kolona.","en":"Choose the period and how the figures are grouped under \"Group by\"; with \"Across\" you turn it into a table with columns."},{"sq":"Kliko një rresht për të parë nga se përbëhet; rruga mbi tabelë të kthen pas.","en":"Click a row to see what makes it up; the path above the table takes you back."},{"sq":"Kliko \"Ruaj raportin\" për ta gjetur më vonë te \"Raportet e mia\", ose \"Eksporto\" për Excel, CSV ose PDF.","en":"Click \"Save the report\" to find it later under \"My reports\", or \"Export\" for Excel, CSV or PDF."}],"mistakes":[{"sq":"Raportet që sheh varen nga roli yt: nëse të mungon një raport, pyet administratorin e kompanisë.","en":"The reports you see follow your role: if one is missing, ask the company admin."}],"related":[{"href":"/finance/reports","label":"Pasqyrat financiare"}]},{"path":"/reports/kpi","title":"Paneli i menaxherit","title_en":"Manager's panel","section":"Raportet","perm":"reports.read","keywords":["kpi","plan","target","objektiv","realizimi","kupon mesatar","average receipt","marzh","humbje","qarkullimi","menaxher","performance"]},{"path":"/sales","title":"Shitjet","title_en":"Sales overview","section":"Raportet","perm":"sales.read","keywords":["revenue","kpi","performance","metrics"],"what":{"sq":"Pasqyra e shitjeve: sa ke shitur, me çfarë marzhi, cilat fatura janë me vonesë dhe kush blen më shumë.","en":"Sales overview: how much you sold, at what margin, which invoices are overdue and who buys most."},"steps":[{"sq":"Zgjidh periudhën lart.","en":"Choose the period on top."},{"sq":"Kliko një kartë (p.sh. \"Shitjet (pa TVSH)\" ose \"Fatura me vonesë (me TVSH)\") për listën pas saj.","en":"Click a card (for example \"Sales (without VAT)\" or \"Overdue invoices (with VAT)\") for the list behind it."},{"sq":"Shiko klientët dhe produktet kryesore, dhe shitjet sipas shitësit.","en":"Look at the top customers and products, and the sales by salesperson."},{"sq":"Me \"Ofertë e re\" ose \"Porosi e re\" fillon një shitje të re.","en":"With \"New quote\" or \"New order\" you start a new sale."}],"mistakes":[{"sq":"Shitjet numërohen nga faturat e kontabilizuara minus notat e kreditit, pa TVSH: faturat në skicë nuk llogariten.","en":"Sales count posted invoices minus credit notes, without VAT: draft invoices are not counted."}],"related":[{"href":"/sales/invoices","label":"Faturat e shitjes"},{"href":"/reports","label":"Raportet"}]},{"path":"/procurement","title":"Blerjet","title_en":"Purchasing overview","section":"Raportet","perm":"procurement.read","keywords":["spend","procurement","kpi","blerje"],"what":{"sq":"Pasqyra e blerjeve: sa ke shpenzuar, çka është në porosi, çka ke pranuar pa faturë dhe cilat fatura janë me vonesë.","en":"Purchasing overview: what you spent, what is on order, what came in without a bill and which bills are overdue."},"steps":[{"sq":"Zgjidh periudhën lart.","en":"Choose the period on top."},{"sq":"Kliko një kartë për listën pas saj; \"Fatura me mospërputhje\" janë ato ku sasia ose çmimi ndryshon nga porosia.","en":"Click a card for the list behind it; \"Bills with a mismatch\" are those where quantity or price differs from the order."},{"sq":"Te \"Furnitorët\" sheh shpenzimin, dorëzimet në kohë dhe sa ditë zgjat dorëzimi.","en":"Under \"Vendors\" you see the spend, on-time deliveries and how many days delivery takes."},{"sq":"Me \"Porosi e re blerjeje\" ose \"Kërkesë e re blerjeje\" fillon një blerje.","en":"With \"New purchase order\" or \"New requisition\" you start a purchase."}],"mistakes":[{"sq":"\"Pranuar, pa faturë\" është malli që ka hyrë, por fatura e furnitorit nuk është regjistruar ende: pritet një faturë.","en":"\"Received, not billed\" is goods that came in whose vendor bill is not recorded yet: a bill is still to come."}],"related":[{"href":"/procurement/bills","label":"Faturat e furnitorëve"},{"href":"/reports","label":"Raportet"}]},{"path":"/finance","title":"Financat në përgjithësi","title_en":"Finance overview","section":"Raportet","perm":"finance.read","keywords":["accounting","kpi","kontabilitet"],"what":{"sq":"Financat në përgjithësi: të ardhurat, fitimi, paratë, TVSH-ja dhe borxhet, direkt nga kontabiliteti.","en":"Finance overview: revenue, profit, cash, VAT and debts, straight from the accounts."},"steps":[{"sq":"Zgjidh periudhën lart.","en":"Choose the period on top."},{"sq":"Kliko një shifër për të parë çka ka pas saj.","en":"Click a figure to see what is behind it."},{"sq":"Shiko grafikun: paratë në fund të çdo muaji dhe fitimin e muajit.","en":"Look at the chart: cash at the end of each month and the month's profit."},{"sq":"Me \"Arkëto një pagesë\", \"Paguaj një furnitor\" ose \"Regjistrim manual\" fillon punën e zakonshme.","en":"With \"Receive a payment\", \"Pay a vendor\" or \"Manual entry\" you start the usual work."}],"mistakes":[{"sq":"\"Regjistrime si skicë\" janë regjistrime manuale ende të pakontabilizuara: kontabilizoji ose fshiji.","en":"\"Draft entries\" are manual entries not posted yet: post them or delete them."}],"related":[{"href":"/finance/reports","label":"Pasqyrat financiare"}]},{"path":"/tax","title":"Afatet e tatimeve","title_en":"Tax overview","section":"Raportet","perm":"tax.read","keywords":["vat","tvsh","calendar","deadlines","tatime"],"what":{"sq":"Afatet e tatimeve: TVSH-ja e këtij muaji deri tani, çka duhet dorëzuar dhe kur, dhe si po shkon fiskalizimi.","en":"Tax overview: this month's VAT so far, what is due and when, and how fiscalization is going."},"steps":[{"sq":"Shiko kartat lart: TVSH e shitjeve, e blerjeve dhe sa del për të paguar deri tani. Kliko një kartë për librin.","en":"Look at the cards on top: sales VAT, purchase VAT and what is to pay so far. Click a card for the book."},{"sq":"Te \"Afatet\" sheh çdo deklaratë me afatin dhe statusin; të vonuarat dalin me të kuqe.","en":"Under \"Deadlines\" you see each declaration with its due date and status; late ones are red."},{"sq":"Kur mbaron muaji, kliko \"Deklaratë e re\".","en":"When the month is over, click \"New declaration\"."},{"sq":"Nëse \"Librat kundrejt kontabilitetit\" tregon \"Kontrolloni\", kliko \"Hap librat\" dhe gjej diferencën.","en":"If \"Books against accounting\" says \"Check\", click \"Open the books\" and find the difference."}],"mistakes":[{"sq":"TVSH-ja e kuponëve në turne të hapura të arkës kalon në kontabilitet vetëm me Z-raportin: mbyll turnet para se të krahasosh.","en":"Till VAT in open shifts reaches accounting only with the Z report: close the shifts before you compare."}],"related":[{"href":"/tax/declarations","label":"Deklaratat e TVSH"},{"href":"/tax/fiscalization","label":"Fiskalizimi"}]},{"path":"/history","title":"Programi i vjetër","title_en":"History from the old program","section":"Raportet","perm":"invoicing.read","keywords":["historiku","logmicro","arkiv","archive","old program","kubit","bilanc"],"what":{"sq":"Programi i vjetër: shitjet, blerjet, pagesat dhe kontabiliteti nga programi që përdorej më parë, të ruajtura si arkiv.","en":"The old program: sales, purchases, payments and accounting from the program used before, kept as an archive."},"steps":[{"sq":"Zgjidh periudhën me \"Nga\" dhe \"Deri\".","en":"Choose the period with \"From\" and \"To\"."},{"sq":"Te \"Pasqyra\" sheh shitjet dhe blerjet sipas muajve, sipas njësisë dhe produktet më të shitura.","en":"Under \"Overview\" you see sales and purchases by month, by store and the best-selling products."},{"sq":"Te \"Dokumentet\" kërko një faturë ose kupon me numër ose partner, dhe kliko për ta parë me rreshta.","en":"Under \"Documents\" search an invoice or receipt by number or partner, and click it to see its lines."},{"sq":"Te \"Pagesat dhe arka\" sheh pagesat; te \"Kontabiliteti\" lëvizjen e çdo kontoje sipas muajve të një viti.","en":"Under \"Payments and cash\" you see the payments; under \"Accounting\" each account's movement by month of a year."}],"mistakes":[{"sq":"Ky është vetëm arkiv: nuk ndryshon stokun, librat ose çka është dërguar te tatimet.","en":"This is only an archive: it does not change stock, the books or anything sent to the tax office."}],"related":[]},{"path":"/settings","title":"Kompania","title_en":"Company settings","section":"Cilësimet","perm":"admin.read","keywords":["profile","nipt","fiscal codes","preferences"],"what":{"sq":"Cilësimet e kompanisë: si del kompania në dokumente, me çka fillojnë dokumentet e reja dhe lidhja me tatimet.","en":"Company settings: how the company appears on documents, what new documents start with, and the link to the tax office."},"steps":[{"sq":"Te \"Kompania\" plotëso emrin, NUI-në ose NIPT-in, adresën dhe kontaktet: dalin në fatura, kupona dhe fletëpagesa.","en":"Under \"Company\" fill in the name, NUI or NIPT, address and contacts: they print on invoices, receipts and payslips."},{"sq":"Te \"Vlerat fillestare dhe rregullat\" zgjidh njësinë dhe TVSH-në që propozohen, dhe rregullat si \"Lejo stok negativ\".","en":"Under \"Defaults and rules\" choose the warehouse and VAT that are suggested, and rules such as \"Allow negative stock\"."},{"sq":"Te \"Fiskalizimi\" ndiz \"Fiskalizo dokumentet\" dhe shkruaj kodet nga administrata tatimore.","en":"Under \"Fiscalization\" switch on \"Fiscalize documents\" and type the codes from the tax office."},{"sq":"Kliko \"Ruaj ndryshimet\" poshtë faqes; te \"Menuja\" çdo ndryshim ruhet menjëherë.","en":"Click \"Save changes\" at the bottom; under \"Menu\" each change is saved at once."}],"mistakes":[{"sq":"Me mënyrën \"Test\" asgjë nuk shkon te tatimet. Kalo në \"Reale\" vetëm kur shërbimi i fiskalizimit është vendosur me certifikatën e kompanisë.","en":"In \"Test\" mode nothing reaches the tax office. Switch to \"Live\" only once the fiscalization service is set up with the company certificate."}],"after":{"sq":"Pjesët e fikura te \"Menuja\" zhduken nga menuja e të gjithëve, por asgjë nuk fshihet: faqet gjenden ende me kërkim.","en":"Parts switched off under \"Menu\" disappear from everyone's menu, but nothing is deleted: the pages can still be found by search."},"related":[]},{"path":"/settings/users","title":"Përdoruesit","title_en":"Users and roles","section":"Cilësimet","perm":"admin.read","keywords":["invite","members","permissions","roles","access","security","siguria","permission matrix","custom role"],"what":{"sq":"Përdoruesit: kush hyn në këtë kompani dhe çfarë mund të bëjë secili, sipas roleve të tij.","en":"Users: who can sign in to this company and what each person may do, by their roles."},"steps":[{"sq":"Kliko \"Fto një person\", shkruaj email-in, zgjidh rolet dhe kliko \"Dërgo ftesën\".","en":"Click \"Invite a person\", type the email, choose the roles and click \"Send invitation\"."},{"sq":"Nëse personi ka llogari, i vjen ftesa dhe duhet të klikojë \"Prano\"; deri atëherë del si \"I ftuar\". Për dikë pa llogari, llogarinë e hap administratori i DrisPRO.","en":"If the person has an account, they get the invitation and must click \"Accept\"; until then they show as \"Invited\". For someone without an account, the DrisPRO administrator makes one."},{"sq":"Te menyja \"…\" e çdo personi: \"Ndrysho rolet\", \"Njësitë ku punon\", PIN për arkën e përbashkët ose \"Pezullo aksesin\".","en":"In each person's \"…\" menu: \"Change roles\", \"Warehouses they work in\", a PIN for the shared till, or \"Suspend access\"."},{"sq":"Fto kontabilistin te \"Kontabilisti juaj, falas\": nuk zë vend përdoruesi në licencë.","en":"Invite your accountant under \"Your accountant, free\": they do not take a user place of your licence."}],"mistakes":[{"sq":"Me \"Hiq nga kompania\" personi humb aksesin menjëherë. Për një largim të përkohshëm përdor \"Pezullo aksesin\" dhe më vonë \"Rikthe aksesin\".","en":"With \"Remove from company\" the person loses access at once. For a temporary break use \"Suspend access\", and later \"Restore access\"."}],"after":{"sq":"Rolet e ndryshuara vlejnë herën tjetër që personi hap një faqe. Dokumentet që ka bërë mbeten me emrin e tij.","en":"Changed roles apply the next time the person opens a page. Documents they made keep their name."},"related":[{"href":"/settings/roles","label":"Rolet dhe të drejtat"},{"href":"/hr/employees","label":"Punonjësit"}]},{"path":"/settings/numbering","title":"Numërimi","title_en":"Numbering","section":"Cilësimet","perm":"admin.read","keywords":["sequences","prefix","document numbers"],"what":{"sq":"Numërimi i dokumenteve: si numërohet çdo lloj dokumenti. Numrat nuk kanë zbrazëtira dhe nuk përdoren dy herë.","en":"Document numbering: how each kind of document is numbered. Numbers have no gaps and are never used twice."},"steps":[{"sq":"Kliko lapsin te dokumenti që do të ndryshosh.","en":"Click the pencil on the document you want to change."},{"sq":"Ndrysho \"Parashtesa\", \"Shifrat\" dhe, nëse do, \"Viti në numër\"; poshtë sheh si del numri i radhës.","en":"Change the \"Prefix\", \"Digits\" and, if you like, \"Year in the number\"; below you see how the next number looks."},{"sq":"Me \"Kodi i dyqanit ose njësisë në numër\" çdo dyqan numëron më vete.","en":"With \"Store or warehouse code in the number\" each store counts on its own."},{"sq":"Kur vazhdon një seri nga programi i vjetër, rrite \"Numri i radhës\" dhe kliko \"Ruaj numërimin\".","en":"When continuing a series from the old program, move \"Next number\" forward and click \"Save numbering\"."}],"mistakes":[{"sq":"\"Numri i radhës\" vetëm rritet, nuk zbret. Numërimi që rifillon çdo vit duhet ta ketë vitin në numër, përndryshe numrat e dy viteve do të ishin të njëjtë.","en":"\"Next number\" only moves forward. Numbering that restarts every year must show the year, or two years would get the same numbers."}],"after":{"sq":"Ndryshimi vlen nga dokumenti i ardhshëm; numrat e dhënë mbeten siç janë.","en":"The change applies from the next document; numbers already given stay as they are."},"related":[]},{"path":"/settings/automation","title":"Automatizimet","title_en":"Automations","section":"Cilësimet","perm":"core.read","keywords":["automatic","schedule","automatizim","email","whatsapp","reminders"],"what":{"sq":"Automatizimet: çfarë bën DrisPRO vetë dhe kur. Çdo gjë që prek paratë, ligjin ose mallin pret konfirmimin e një personi.","en":"Automations: what DrisPRO does by itself, and when. Whatever touches money, the law or goods waits for a person to confirm."},"steps":[{"sq":"Te \"Mbyllja e ditës në arkë\" shkruaj nga sa diferencë parash të njoftohesh dhe kliko \"Ruaj\".","en":"Under \"End of the day at the till\" type from what cash difference you want to be told, and click \"Save\"."},{"sq":"Ndiz \"Pagat mujore\" dhe zgjidh ditën: listëpagesa përgatitet vetë si skicë nga kontratat, prezenca dhe lejet.","en":"Switch on \"Monthly payroll\" and choose the day: the payroll is prepared as a draft from contracts, attendance and leave."},{"sq":"Te \"Serveri i email-it (SMTP)\" vendos kutinë postare dhe kliko \"Dërgo një email prove\": prej saj dalin kujtesat, porositë dhe përmbledhja e mëngjesit.","en":"Under \"Mail server (SMTP)\" set the mailbox and click \"Send a test email\": reminders, purchase orders and the morning summary go out from it."},{"sq":"Kliko \"Hap\" te \"Faturat mujore\", \"Çmimet e reja nga kosto\" ose \"Rifurnizim\" për t'i rregulluar.","en":"Click \"Open\" on \"Recurring invoices\", \"New selling prices from the cost\" or \"Replenishment\" to set them up."}],"mistakes":[{"sq":"Për Gmail përdor një fjalëkalim aplikacioni (Google › Security › App passwords), jo fjalëkalimin e zakonshëm.","en":"For Gmail use an app password (Google › Security › App passwords), not your usual password."}],"after":{"sq":"Listëpagesa e përgatitur vetë mbetet skicë: miratimi dhe pagesa mbeten te ti.","en":"The payroll prepared by itself stays a draft: approving and paying stay with you."},"related":[{"href":"/hr/payroll","label":"Pagat"},{"href":"/sales/recurring","label":"Faturat mujore"}]},{"path":"/settings/assistant","title":"Agjenti AI","title_en":"AI agent","section":"Cilësimet","perm":"core.read","keywords":["agjenti","asistenti","ai","inteligjenca artificiale","trajno","mëso","rregulla","çka di agjenti","teach","knowledge","memory"],"what":{"sq":"Çka di agjenti AI për kompaninë tuaj: rregullat, fjalët dhe emrat tuaj, si e bëni një punë dhe si i doni përgjigjet. Agjenti i ndjek në çdo përgjigje dhe në kontrollin e mëngjesit.","en":"What the AI agent knows about your company: your rules, words and names, how you do a job and how you like the answers. It follows them in every answer and in the morning check."},"steps":[{"sq":"Kliko \"Mësoji diçka të re\", zgjidh çka është (rregull, fjalë ose emër, si e bëjmë, preferencë) dhe shkruaje si do t'ia thoshe një punëtori të ri.","en":"Click \"Teach something new\", choose what it is (a rule, a word or a name, how we do it, a preference) and write it as you would tell a new worker."},{"sq":"Ndize \"Për gjithë kompaninë\" që ta ndjekë asistenti i të gjithëve; fikur, e ndjek vetëm asistenti yt. Për gjithë kompaninë e mëson vetëm menaxheri.","en":"Turn on \"For the whole company\" so everyone's assistant follows it; off, only yours does. Only a manager teaches it for the whole company."},{"sq":"Në bisedë (Ctrl+J), kur e korrigjon agjentin ose i thua si punoni, ai të pyet \"Ta mbaj mend?\"; me \"Po\" mësimi shtohet këtu.","en":"In the chat (Ctrl+J), when you correct the agent or tell it how you work, it asks \"Remember this?\"; with \"Yes\" the lesson is added here."},{"sq":"Kur shtyp \"Jo\" te një kartë, shkruaj pse: arsyeja ruhet këtu dhe propozimi i ardhshëm del më i mirë.","en":"When you press \"No\" on a card, write why: the reason is kept here and the next proposal is better."},{"sq":"Me lapsin e ndryshon një mësim, me koshin e harron.","en":"Change a lesson with the pencil, forget it with the bin."}],"mistakes":[{"sq":"Një mësim nuk jep leje: arkëtari nuk sheh paga edhe nëse shkruhet \"tregoja pagat\".","en":"A lesson gives no permissions: a cashier sees no salaries even if it says \"show them the salaries\"."}],"related":[{"href":"/settings/automation","label":"Automatizimet"},{"href":"/tasks","label":"Detyrat"}]},{"path":"/settings/workflows","title":"Rregullat e miratimit","title_en":"Approval workflows","section":"Cilësimet","perm":"admin.read","keywords":["approval limits","approvers"],"what":{"sq":"Rregullat e miratimit: cilat dokumente duhet t'i miratojë dikush, nga cila shumë, dhe kush vendos në çdo hap.","en":"Approval workflows: which documents need approval, from what amount, and who decides at each step."},"steps":[{"sq":"Kliko \"Rrjedhë e re\", jepi emër dhe zgjidh dokumentin (p.sh. porosi blerjeje, pagesë furnitori, leje).","en":"Click \"New workflow\", name it and choose the document (e.g. purchase order, vendor payment, leave)."},{"sq":"Shkruaj \"Nga shuma\": rrjedha vlen për dokumentet me këtë shumë ose më shumë.","en":"Type the \"From amount\": the workflow applies to documents of this amount or more."},{"sq":"Shto hapat me \"Shto një hap\"; për secilin zgjidh \"Kush miraton\": një rol ose një person.","en":"Add steps with \"Add a step\"; for each one choose \"Who approves\": a role or a person."},{"sq":"Kliko \"Krijo rrjedhën\"; me çelësin pranë saj e fik ose e ndez kur të duash.","en":"Click \"Create workflow\"; use the switch next to it to turn it off or on at any time."}],"mistakes":[{"sq":"Pa asnjë rrjedhë, dokumentet miratohen sapo dërgohen. Kur disa rrjedha i përshtaten një dokumenti, fiton ajo me \"Përparësia\" më të lartë.","en":"Without any workflow, documents are approved as soon as they are sent. When several fit a document, the highest \"Priority\" wins."}],"after":{"sq":"Hapat shkojnë me radhë; një \"jo\" e kthen dokumentin mbrapsht.","en":"Steps run in order; one \"no\" sends the document back."},"related":[{"href":"/settings/roles","label":"Rolet dhe të drejtat"}]},{"path":"/settings/import","title":"Importi","title_en":"Import data","section":"Cilësimet","perm":"core.read","keywords":["csv","excel","upload","migration","opening balances"],"what":{"sq":"Importi: sill artikujt, klientët e furnitorët, punonjësit dhe gjendjen fillestare nga Excel ose CSV.","en":"Import data: bring products, customers and vendors, employees and opening stock from Excel or CSV."},"steps":[{"sq":"Zgjidh çfarë importon; kliko \"Shabllon\" për një skedar shembull me kolonat e duhura.","en":"Choose what you import; click \"Template\" for a sample file with the right columns."},{"sq":"Kliko \"Zgjidh një skedar\": Excel .xlsx ose CSV, me emrat e kolonave në rreshtin e parë.","en":"Click \"Choose a file\": Excel .xlsx or CSV, with the column names in the first row."},{"sq":"Kontrollo lidhjen e kolonave (ato me * janë të detyrueshme); me \"Ruaje si shabllon\" e gjen gati herën tjetër.","en":"Check how the columns are matched (those with * are required); with \"Save as template\" it is ready next time."},{"sq":"Kliko \"Kontrollo skedarin\": asgjë nuk ruhet, vetëm del çka duhet rregulluar. Pastaj importo rreshtat.","en":"Click \"Check the file\": nothing is saved, it only shows what to fix. Then import the rows."}],"mistakes":[{"sq":"Artikulli me SKU që ekziston përditësohet, nuk krijohet i ri; partnerët gjenden sipas NIPT/NUI ose kodit.","en":"An item with an existing SKU is updated, not created again; partners are matched by NIPT/NUI or code."},{"sq":"Për gjendjen fillestare bëj një skedar për çdo njësi.","en":"For opening stock make one file per warehouse."}],"after":{"sq":"Gjendja fillestare regjistrohet si një rregullim stoku i hapjes.","en":"Opening stock is posted as one opening stock adjustment."},"related":[{"href":"/settings/migration","label":"Kalimi nga programi tjetër"}]},{"path":"/settings/migration","title":"Kalimi nga programi tjetër","title_en":"Move from another program","section":"Cilësimet","perm":"admin.write","keywords":["migration","kubit","logmicro","bilanc","pantheon","opening balances","cut-over","kalimi","migrimi"],"what":{"sq":"Kalimi nga programi tjetër: sill kompaninë nga programi i vjetër, hap pas hapi, dhe krahaso totalet.","en":"Move from another program: bring the company over from the old program step by step, then compare the totals."},"steps":[{"sq":"Zgjidh \"Data e kalimit\" dhe \"Programi i vjetër\"; nxirr çdo listë në Excel nga programi i vjetër në atë datë.","en":"Choose the \"Cut-over date\" and the \"Old program\"; export each list to Excel from the old program on that date."},{"sq":"Ndiq hapat me radhë majtas: artikujt, partnerët, gjendja, faturat e hapura, saldot e llogarive. Ato \"(opsionale)\" mund t'i kalosh.","en":"Follow the steps on the left in order: products, partners, stock, open invoices, account balances. The \"(optional)\" ones can be skipped."},{"sq":"Në çdo hap: zgjidh skedarin, lidh kolonat, kontrolloje dhe importoje.","en":"In each step: choose the file, match the columns, check it and import it."},{"sq":"Në fund hap \"Kontrolli i totaleve\" dhe krahaso çdo shifër me të njëjtin raport në programin e vjetër.","en":"At the end open \"Check the totals\" and compare each figure with the same report in the old program."}],"mistakes":[{"sq":"Rendi ka rëndësi: faturat e hapura kanë nevojë për klientët, gjendja dhe çmimet për artikujt.","en":"The order matters: open invoices need their customers, stock and prices need the products."},{"sq":"Nëse një shifër nuk përputhet, importo sërish atë hap ose korrigjo dokumentin.","en":"If a figure does not match, import that step again or correct the document."}],"after":{"sq":"Nga data e kalimit kompania punon vetëm në DrisPRO; faturat e hapura vjetërohen dhe paguhen si çdo faturë tjetër.","en":"From the cut-over date the company works only in DrisPRO; the open invoices age and take payments like any other."},"related":[]},{"path":"/settings/integrations","title":"Lidhjet me programe","title_en":"B2B portal and API","section":"Cilësimet","perm":"admin.read","keywords":["api","b2b","portal","portali","web shop","dyqan online","integrim","key","çelës","woocommerce","shopify","chatgpt","claude","mcp","ai"],"what":{"sq":"Lidhjet me programe: portali B2B për klientët, ChatGPT dhe Claude, çelësat API dhe webhooks.","en":"B2B portal and API: the portal for customers, ChatGPT and Claude, API keys and webhooks."},"steps":[{"sq":"Te \"Portali B2B\" zgjidh nëse porositë konfirmohen menjëherë dhe çfarë shohin klientët nga stoku. Lidhja për çdo klient bëhet te faqja e klientit.","en":"Under \"B2B portal\" choose whether orders are confirmed at once and what customers see of the stock. Each customer's link is made on the customer's page."},{"sq":"Te \"ChatGPT dhe Claude\" kliko \"Krijo lidhjen time\" dhe ngjite lidhjen në ChatGPT ose Claude, sipas udhëzimeve.","en":"Under \"ChatGPT and Claude\" click \"Make my link\" and paste the link into ChatGPT or Claude, as the steps say."},{"sq":"Te \"Çelësat API\" kliko \"Çelës i ri\", jepi emër, shëno \"Çfarë mund të bëjë\" dhe kliko \"Bëj çelësin\".","en":"Under \"API keys\" click \"New key\", name it, tick \"What it may do\" and click \"Make the key\"."},{"sq":"Kopjo çelësin menjëherë: shfaqet vetëm një herë.","en":"Copy the key at once: it is shown only this once."}],"mistakes":[{"sq":"Kush e ka lidhjen ose çelësin e sheh kompaninë si ti: mos e ndaj. Nëse rrjedh, fike çelësin ose hiqe lidhjen dhe bëj një të re.","en":"Whoever has the link or the key sees the company as you: do not share it. If it leaks, switch the key off or remove the link and make a new one."}],"related":[{"href":"/partners","label":"Klientët dhe furnitorët"}]},{"path":"/settings/audit","title":"Kush ndryshoi çfarë","title_en":"Audit log","section":"Cilësimet","perm":"audit.read","keywords":["history","changes","who changed"],"what":{"sq":"Historiku i ndryshimeve: kush ndryshoi çfarë, kur, dhe vlerat para e pas. Këtu asgjë nuk ndryshohet e nuk fshihet.","en":"Change history: who changed what, when, and the values before and after. Nothing here can be edited or deleted."},"steps":[{"sq":"Filtro sipas \"Fusha\", \"Personi\", \"Veprimi\" ose datave.","en":"Filter by \"Area\", \"Person\", \"Action\" or dates."},{"sq":"Kliko një rresht për të parë çdo fushë që ndryshoi, me vlerën e vjetër dhe të renë.","en":"Click a row to see each field that changed, with the old and the new value."},{"sq":"Kliko \"Gjithë historiku i këtij regjistrimi\" për ta ndjekur një dokument nga fillimi.","en":"Click \"Full history of this record\" to follow one document from the start."},{"sq":"Nëse diçka u fshi gabimisht, hap rreshtin e fshirjes dhe kliko \"Ktheje\".","en":"If something was deleted by mistake, open the row of the deletion and click \"Bring it back\"."}],"mistakes":[{"sq":"\"Ktheje\" kërkon të drejtën e fshirjes në atë fushë.","en":"\"Bring it back\" needs the right to delete in that area."}],"related":[]},{"path":"/procurement/orders/:id","title":"Një porosi blerjeje","section":null,"keywords":[],"what":{"sq":"Një porosi blerjeje: furnitori, artikujt, kur pritet malli dhe ku dorëzohet.","en":"One purchase order: the vendor, the items, when the goods are expected and where they go."},"steps":[{"sq":"Zgjidh furnitorin, \"Dorëzimi i pritur\" dhe njësinë te \"Dorëzo në\".","en":"Choose the vendor, the \"Expected delivery\" and the unit under \"Deliver to\"."},{"sq":"Shto rreshtat: çmimi vjen nga çmimet e furnitorit, nga çmimi i fundit i paguar ose nga kostoja mesatare.","en":"Add the lines: the price comes from the vendor's prices, the last price paid or the average cost."},{"sq":"Kliko \"Dërgo\": porosia kontrollohet dhe miratohet, ose shkon te miratuesi kur shuma e kërkon.","en":"Click \"Submit\": the order is checked and approved, or goes to the approver when the amount needs it."},{"sq":"Kur ia dërgon furnitorit, kliko \"Shëno si të dërguar\"; kur vjen malli, \"Prano mallin\".","en":"When it is with the vendor, click \"Mark as sent\"; when the goods arrive, \"Receive goods\"."},{"sq":"Kur vjen fatura, kliko \"Regjistro faturën\": krahasohet me porosinë dhe me mallin e pranuar.","en":"When the bill comes, click \"Enter bill\": it is checked against the order and the goods received."}],"mistakes":[{"sq":"Pas \"Dërgo\" rreshtat nuk ndryshohen; nëse pret ende miratim, kliko \"Tërhiq\" që të kthehet në skicë.","en":"After \"Submit\" the lines cannot change; while it still waits for approval, click \"Withdraw\" to get it back as a draft."},{"sq":"Nëse pjesa tjetër e mallit nuk do të vijë, kliko \"Mbyll\", që të mos llogaritet më si mall në ardhje.","en":"If the rest of the goods will not come, click \"Close\" so it no longer counts as incoming stock."}],"after":{"sq":"Porosia e miratuar del si mall në ardhje te stoku dhe te rifurnizimi. \"Prano mallin\" hap një pranim skicë; malli hyn në stok kur e konfirmon.","en":"An approved order shows as incoming stock and in replenishment. \"Receive goods\" opens a draft receipt; the goods enter stock when you confirm it."},"related":[{"href":"/procurement/vendor-prices","label":"Çmimet e furnitorëve"},{"href":"/procurement/bills","label":"Faturat e blerjes"}]},{"path":"/sales/quotes/:id","title":"Një ofertë për klientin","section":null,"keywords":[],"what":{"sq":"Një ofertë për klientin: artikujt, çmimet dhe deri kur vlen.","en":"One quote for a customer: the items, the prices and how long it is valid."},"steps":[{"sq":"Zgjidh klientin: çmimet vijnë nga lista e tij, ose zgjidh një tjetër te \"Lista e çmimeve\".","en":"Choose the customer: prices come from their list, or choose another under \"Price list\"."},{"sq":"Cakto \"E vlefshme deri më\" dhe shto rreshtat.","en":"Set \"Valid until\" and add the lines."},{"sq":"Printoje ose dërgoje me e-mail, pastaj kliko \"Shëno si të dërguar\".","en":"Print it or send it by email, then click \"Mark as sent\"."},{"sq":"Kur klienti pranon, kliko \"Krijo porosinë\"; kur refuzon, \"Klienti refuzoi\".","en":"When the customer accepts, click \"Create order\"; when they say no, \"Customer said no\"."}],"mistakes":[{"sq":"Oferta e dërguar nuk ndryshohet: kliko \"Ndrysho përsëri\" që të kthehet në skicë.","en":"A sent quote cannot be changed: click \"Edit again\" to bring it back to draft."}],"after":{"sq":"Oferta nuk prek as stokun as librat. \"Krijo porosinë\" bën një porosi skicë me të njëjtat rreshta dhe çmime, dhe mundësia shënohet si e fituar.","en":"A quote touches neither stock nor the books. \"Create order\" makes a draft order with the same lines and prices, and the deal is marked as won."},"related":[{"href":"/sales/quotes","label":"Ofertat"},{"href":"/crm/pipeline","label":"Marrëveshjet"}]},{"path":"/sales/orders/:id","title":"Një porosi klienti","section":null,"keywords":[],"what":{"sq":"Një porosi klienti: artikujt, nga cila njësi dërgohen, dhe sa është dërguar e faturuar.","en":"One customer order: the items, which unit they go from, and how much is delivered and invoiced."},"steps":[{"sq":"Zgjidh klientin dhe njësinë te \"Dërgohet nga\", pastaj shto rreshtat.","en":"Choose the customer and the unit under \"Send from\", then add the lines."},{"sq":"Kliko \"Konfirmo porosinë\": kontrollohen zbritjet dhe kredia e klientit, pastaj rezervohet malli.","en":"Click \"Confirm order\": the discounts and the customer's credit are checked, then the goods are reserved."},{"sq":"Kur malli niset, kliko \"Krijo dërgesën\".","en":"When the goods leave, click \"Create delivery\"."},{"sq":"Kliko \"Krijo faturën\" për të faturuar; për pagesë para dërgimit përdor \"Faturë paradhënieje\".","en":"Click \"Create invoice\" to invoice it; for a payment before delivery use \"Advance invoice\"."}],"mistakes":[{"sq":"Pas konfirmimit rreshtat nuk ndryshohen më.","en":"After confirming, the lines can no longer change."},{"sq":"Nëse pjesa tjetër s'do të dërgohet, kliko \"Mbyll porosinë\" që të lirohet malli i rezervuar.","en":"If the rest will not be delivered, click \"Close order\" to release the reserved stock."}],"after":{"sq":"Malli i rezervuar nuk i shitet dot tjetërkujt; stoku zbret kur përfundon dërgesa, dhe borxhi i klientit lind me faturën. Kur kalohet kufiri i kredisë ose i zbritjes, porosia shkon për miratim.","en":"Reserved goods cannot be sold to anyone else; stock goes down when the delivery is completed, and the customer's debt starts with the invoice. Over the credit or discount limit, the order goes for approval."},"related":[{"href":"/sales/deliveries","label":"Dërgesat"},{"href":"/oms/fulfillment","label":"Porositë në pritje"}]},{"path":"/inventory/receipts/:id","title":"Një pranim malli","section":null,"keywords":[],"what":{"sq":"Një pranim malli: nga kush vjen, në cilën njësi hyn dhe çfarë erdhi.","en":"One goods receipt: who it comes from, which unit it goes into and what arrived."},"steps":[{"sq":"Zgjidh \"Lloji i pranimit\" dhe, nëse ka, \"Porosi blerjeje\": rreshtat dhe çmimet vijnë nga porosia.","en":"Choose the \"Receipt type\" and, if there is one, the \"Purchase order\": lines and prices come from the order."},{"sq":"Kontrollo \"Njësia\" dhe datën, dhe shkruaj \"Nr. i fletëdërgesës\".","en":"Check the \"Warehouse\" and the date, and type the \"Delivery note no.\"."},{"sq":"Te \"Produktet e pranuara\" kontrollo sasitë me fletëdërgesën; për artikujt me lot zgjidh ose krijo lotin.","en":"Under \"Products received\" check the quantities against the delivery note; for items with lots choose or create the lot."},{"sq":"Kliko \"Prano mallin\" dhe konfirmo; pas kësaj pranimi nuk ndryshohet më.","en":"Click \"Receive goods\" and confirm; after that the receipt can no longer change."},{"sq":"Pastaj: \"Etiketat\" për raftet, \"Krijo faturën e furnitorit\" (kur s'ka porosi) ose \"Kthe te furnitori\" për mallin me defekt.","en":"Then: \"Labels\" for the shelves, \"Create the vendor bill\" (when there is no order) or \"Return to the vendor\" for faulty goods."}],"mistakes":[{"sq":"Për mall nga importi aktivizo \"Mall i importuar…\" dhe shkruaj DUD-in; transportin dhe doganën i shton më vonë me \"Shto koston e mbërritjes\".","en":"For imported goods switch on \"Imported goods…\" and type the customs declaration; add freight and customs later with \"Add landed cost\"."},{"sq":"Rreshtat me QC \"Refuzuar\" nuk hyjnë në stok; kthimi nga klienti hyn me koston mesatare, pa çmim.","en":"Lines with QC \"Rejected\" do not enter stock; a customer return comes back at the average cost, without a price."}],"after":{"sq":"Malli hyn në stok dhe kostoja mesatare rillogaritet. Për blerjet regjistrohet stoku kundrejt mallit të pranuar pa faturë, derisa të vijë fatura (shih \"Kontabiliteti\").","en":"The goods enter stock and the average cost is recalculated. For purchases the books record the stock against goods received not yet invoiced, until the bill comes (see \"Accounting\")."},"related":[{"href":"/procurement/bills","label":"Faturat e blerjes"},{"href":"/inventory/labels","label":"Etiketat"}]},{"path":"/inventory/transfers/:id","title":"Një transferim","section":null,"keywords":[],"what":{"sq":"Një transferim: çka niset, nga cila njësi te cila, dhe çka arriti.","en":"One transfer: what is sent, from which unit to which, and what arrived."},"steps":[{"sq":"Zgjidh \"Nga\" dhe \"Deri\"; e njëjta njësi në të dyja anët do të thotë lëvizje mes rafteve.","en":"Choose \"From\" and \"To\"; the same unit on both sides means moving between shelves."},{"sq":"Shto artikujt me \"Shto rresht\"; \"Në dispozicion\" tregon sa ka të lirë në raftin nga merret.","en":"Add the items with \"Add line\"; \"Available\" shows what is free on the shelf it is taken from."},{"sq":"Mes dy njësive kliko \"Dërgo\": malli del dhe është në rrugë. Brenda një njësie kliko \"Lëviz mallin\": zhvendoset menjëherë.","en":"Between two units click \"Ship\": the goods leave and are on the road. Inside one unit click \"Move stock\": it moves at once."},{"sq":"Kur arrin, njësia pranuese e numëron (me skaner ose me dorë) dhe kliko \"Prano mallin\".","en":"When it arrives, the receiving unit counts it (scanning or typing) and clicks \"Receive the goods\"."},{"sq":"Për çdo mungesë zgjidh \"Humbur gjatë rrugës\" ose \"Kthehet te dërguesi\".","en":"For anything missing choose \"Lost on the way\" or \"Back to the sender\"."}],"mistakes":[{"sq":"Kur dyqani e kërkon mallin, aktivizo \"Kjo është kërkesë nga njësia pranuese\": depoja e kontrollon dhe e dërgon.","en":"When a shop asks for goods, switch on \"This is a request from the receiving store\": the depot checks and ships it."},{"sq":"Pranimi me diferenca nuk zhbëhet: numëro me kujdes para se ta konfirmosh.","en":"Receiving with differences cannot be undone: count carefully before you confirm."}],"after":{"sq":"Vlera e stokut nuk ndryshon. Humbjet gjatë rrugës dalin nga stoku dhe regjistrohen në kontabilitet; tepricat shtohen në stok.","en":"The stock value does not change. Losses on the way leave stock and are booked; extras are added to stock."},"related":[]},{"path":"/inventory/adjustments/:id","title":"Një rregullim stoku","section":null,"keywords":[],"what":{"sq":"Një rregullim stoku: çka shtohet ose hiqet, në cilën njësi dhe pse.","en":"One stock adjustment: what is added or removed, in which unit and why."},"steps":[{"sq":"Zgjidh \"Njësia\", \"Arsyeja\" dhe datën; te \"Shënime\" shkruaj pse ndryshoi stoku.","en":"Choose the \"Warehouse\", the \"Reason\" and the date; under \"Notes\" write why the stock changed."},{"sq":"Shto rreshtat: te \"Ndryshimi (±)\" plus për mall të gjetur ose gjendje fillestare, minus për humbje dhe dëmtim.","en":"Add the lines: in \"Change (±)\" plus for stock found or opening stock, minus for losses and damage."},{"sq":"Kolona \"Pas\" tregon sa mbetet; e kuqe do të thotë se stoku del në minus.","en":"The \"After\" column shows what is left; red means the stock goes below zero."},{"sq":"Kliko \"Dërgo dhe kryej\". Nëse kërkon miratim, shkon te menaxheri; pasi miratohet, kliko \"Kryej rregullimin\".","en":"Click \"Send and complete\". If it needs approval it goes to the manager; once approved, click \"Complete adjustment\"."}],"mistakes":[{"sq":"Te \"Gjendja fillestare\" shkruaj koston për njësi në çdo rresht: ajo bëhet kostoja mesatare e fillimit.","en":"For \"Opening stock\" type each line's unit cost: it becomes the starting average cost."}],"after":{"sq":"Shtimet vlerësohen me koston që shkruan (ose koston mesatare), heqjet me koston mesatare. Malli i dëmtuar dhe i skaduar shkon te skartimi; regjistrimi del te \"Kontabiliteti\".","en":"Increases are valued at the cost you type (or the average cost), decreases at the average cost. Damaged and expired goods go to scrap; the entry shows under \"Accounting\"."},"related":[]},{"path":"/manufacturing/orders/:id","title":"Një urdhër pune","section":null,"keywords":[],"what":{"sq":"Një urdhër pune: materialet, hapat, prodhimi dhe kostoja e tij.","en":"One work order: its materials, steps, output and cost."},"steps":[{"sq":"Kliko \"Lësho në prodhim\": programi tregon nëse mungon ndonjë material.","en":"Click \"Release\": the program tells you if any material is missing."},{"sq":"Kliko \"Përdor materialet\" kur merren nga depoja; te \"Hapat\" kliko \"Raporto punën\" për minutat e punuara.","en":"Click \"Use materials\" when they are taken from the store; under \"Steps\" click \"Report work\" for the minutes worked."},{"sq":"Kur del malli i gatshëm, kliko \"Regjistro prodhimin\" dhe shkruaj \"Sasia e mirë\" dhe sa u \"Skartuar\".","en":"When finished goods come off the line, click \"Book output\" and type the \"Good quantity\" and how much was \"Scrapped\"."},{"sq":"Nëse mbetet material, kliko \"Kthe materialin e papërdorur\".","en":"If material is left over, click \"Return unused material\"."},{"sq":"Në fund kliko \"Mbyll dhe barazo koston\".","en":"At the end click \"Close and settle cost\"."}],"mistakes":[{"sq":"Kur del paralajmërimi për material që mungon, lëvize mallin te vendi i prodhimit ose pranoje para se të përdorësh materialet.","en":"When the missing-material warning shows, move the stock to the production place or receive it before using the materials."},{"sq":"Prodhimi i pjesshëm vlerësohet me koston e planifikuar; prodhimi i fundit merr gjithë koston që mbetet.","en":"Partial output is valued at the planned cost; the last output takes all the cost that is left."}],"after":{"sq":"Materialet dalin nga stoku dhe hyjnë në prodhim në proces; malli i gatshëm hyn në stok. Me mbylljen, kostoja që s'e mori malli regjistrohet si diferencë kostoje (llogaria 6012).","en":"Materials leave stock into work in progress; finished goods enter stock. On closing, any cost the output did not take is booked as a cost difference (account 6012)."},"related":[]},{"path":"/tax/declarations/:id","title":"Një deklaratë TVSH-je","section":null,"keywords":[],"what":{"sq":"Një deklaratë TVSH-je: fushat e formularit, rezultati i muajit dhe dorëzimi.","en":"One VAT declaration: the fields of the form, the result of the month and the filing."},"steps":[{"sq":"Kontrollo shifrat e formularit; me \"Librat\" sheh dokumentet pas tyre.","en":"Check the figures of the form; with \"Books\" you see the documents behind them."},{"sq":"Nëse ke shtuar ose ndryshuar fatura të këtij muaji, kliko \"Rillogarit\".","en":"If you added or changed invoices of this month, click \"Recalculate\"."},{"sq":"Shiko \"Kontrolli me kontabilitetin\": TVSH-ja e librave duhet të përputhet me kontabilitetin.","en":"Look at \"Accounting check\": the VAT in the books should match accounting."},{"sq":"Nëse ke kredi dhe kërkon rimbursim, shkruaj shumën te \"Rimbursimi që kërkohet\" dhe kliko \"Zbato\".","en":"If you have a credit and ask for a refund, type the amount under \"Refund to request\" and click \"Apply\"."},{"sq":"Deklaroje te ATK-ja (DPT në Shqipëri), pastaj kliko \"Dorëzo deklaratën\" dhe shkruaj numrin te \"Referenca e dorëzimit\".","en":"File it with the ATK (DPT in Albania), then click \"Submit declaration\" and type the number under \"Filing reference\"."}],"mistakes":[{"sq":"\"Dorëzo deklaratën\" nuk e dërgon deklaratën te ATK-ja: e regjistron në libra dhe e mbyll muajin. Deklarimi bëhet në portalin e tatimeve.","en":"\"Submit declaration\" does not send it to the ATK: it books it and closes the month. The filing itself is done on the tax office portal."},{"sq":"Nëse tatimet e refuzojnë, kliko \"Shëno si të refuzuar\", pastaj \"Rihape si skicë\" për ta korrigjuar dhe dorëzuar përsëri.","en":"If the tax office rejects it, click \"Mark rejected\", then \"Reopen as draft\" to correct it and submit it again."}],"after":{"sq":"TVSH-ja e shitjeve dhe e blerjeve e muajit kalon në kontin 4455; diferenca paguhet ose mbartet si kredi në muajin tjetër. Pas dorëzimit nuk shtohet më asnjë faturë në atë muaj.","en":"The month's sales and purchase VAT moves to account 4455; the balance is paid or carried as a credit to next month. After submitting, no invoice can be added to that month."},"related":[{"href":"/tax/books","label":"Librat e TVSH-së"}]},{"path":"/finance/journal/:id","title":"Një regjistrim kontabël","section":null,"keywords":[],"what":{"sq":"Një regjistrim kontabël: ditari, data dhe rreshtat në debi dhe kredi. Këtu bën edhe regjistrimin manual.","en":"One journal entry: the journal, the date and the debit and credit lines. This is also where you make a manual entry."},"steps":[{"sq":"Zgjidh \"Ditari\" dhe datën, dhe shkruaj përshkrimin.","en":"Choose the \"Journal\" and the date, and type the description."},{"sq":"Për çdo rresht zgjidh kontin dhe shkruaj shumën në \"Debi\" ose në \"Kredi\"; partneri dhe qendra e kostos janë sipas nevojës.","en":"For each line choose the account and type the amount under \"Debit\" or \"Credit\"; the partner and cost center are as needed."},{"sq":"Me \"Shto rresht\" shton rreshta. Debia dhe kredia duhet të barazohen; nëse ka diferencë, kliko mesazhin e kuq për ta barazuar në rreshtin e fundit.","en":"With \"Add line\" you add lines. Debits and credits must be equal; if there is a difference, click the red message to balance it on the last line."},{"sq":"Kliko \"Ruaj si skicë\" për ta lënë për më vonë, ose \"Kontabilizo\" kur është gati.","en":"Click \"Save draft\" to leave it for later, or \"Post\" when it is ready."}],"mistakes":[{"sq":"Një regjistrim i kontabilizuar nuk ndryshohet: për ta korrigjuar kliko \"Storno\" dhe bëj një të ri.","en":"A posted entry cannot be changed: to correct it click \"Reverse\" and make a new one."},{"sq":"Regjistrimet automatike korrigjohen nga dokumenti i tyre (p.sh. me notë krediti), jo këtu.","en":"Automatic entries are corrected from their document (for example with a credit note), not here."}],"after":{"sq":"\"Kontabilizo\" i ndryshon menjëherë saldot e kontove dhe pasqyrat financiare. \"Storno\" kontabilizon sot një regjistrim të ri me debi dhe kredi të ndërruara.","en":"\"Post\" changes the account balances and the financial statements at once. \"Reverse\" posts a new entry today with debits and credits swapped."},"related":[]},{"path":"/finance/assets/:id","title":"Një mjet themelor","section":null,"keywords":[],"what":{"sq":"Një mjet themelor: të dhënat, plani i amortizimit, dhe shitja ose nxjerrja jashtë përdorimit.","en":"One fixed asset: its details, the depreciation schedule, and selling or scrapping it."},"steps":[{"sq":"Plotëso emrin, kategorinë, datat, koston pa TVSH dhe jetëgjatësinë në muaj; kliko \"Ruaj\".","en":"Fill in the name, category, dates, cost without VAT and useful life in months; click \"Save\"."},{"sq":"Kliko \"Vëre në përdorim\" dhe zgjidh \"Regjistro blerjen tani\" ose \"Tashmë në kontabilitet\".","en":"Click \"Put in service\" and choose \"Record the purchase now\" or \"Already in the accounts\"."},{"sq":"Te \"Amortizimi\" sheh çdo muaj: shumën, sa është amortizuar dhe vlerën që mbetet.","en":"Under \"Depreciation\" you see each month: the amount, what is depreciated and the value left."},{"sq":"Kur e shet ose e hedh, kliko \"Shit ose nxirr jashtë përdorimit\" dhe shkruaj shumën e shitjes pa TVSH (0 nëse hidhet).","en":"When you sell or scrap it, click \"Sell or scrap\" and type the sale amount without VAT (0 if scrapped)."}],"mistakes":[{"sq":"Nëse fatura e furnitorit është regjistruar tashmë në kontin e mjetit, zgjidh \"Tashmë në kontabilitet\": përndryshe blerja regjistrohet dy herë.","en":"If the vendor bill was already booked to the asset account, choose \"Already in the accounts\": otherwise the purchase is booked twice."},{"sq":"Pasi vihet në përdorim, të dhënat e mjetit nuk ndryshohen më.","en":"Once in service, the asset's details can no longer change."}],"after":{"sq":"Amortizimi fillon nga muaji i vënies në përdorim. Te shitja, amortizimi plotësohet deri në datë, mjeti hiqet nga librat dhe regjistrohet fitimi ose humbja.","en":"Depreciation starts from the in-service month. On a sale, depreciation is brought up to the date, the asset leaves the books and the gain or loss is booked."},"related":[]},{"path":"/hr/employees/:id","title":"Kartela e punonjësit","section":null,"keywords":[],"what":{"sq":"Kartela e punonjësit: të dhënat personale, kontrata, lejet, prezenca dhe fletëpagesat.","en":"The employee's file: personal details, contract, leave, attendance and payslips."},"steps":[{"sq":"Te \"Profili\" plotëso emrin, numrin personal, departamentin, menaxherin dhe IBAN-in, pastaj kliko \"Ruaj ndryshimet\".","en":"Under \"Profile\" fill in the name, personal number, department, manager and IBAN, then click \"Save changes\"."},{"sq":"Te \"Kontrata\" kliko \"Kontratë e re\": plotëso pozitën, pagën bruto dhe orët, dhe programi e shkruan kontratën nga modeli. Pastaj printoje dhe shëno që u nënshkrua.","en":"Under \"Contract\" click \"New contract\": fill in the position, gross pay and hours, and the program writes the contract from the model. Then print it and mark it signed."},{"sq":"Te \"Llogaria e hyrjes\" lidhe punonjësin me përdoruesin e tij: kështu regjistron hyrjen, kërkon leje dhe sheh fletëpagesat vetë.","en":"Under \"Login\" link the employee to their user: then they clock in, ask for leave and see their own payslips."},{"sq":"Te \"Ndalesat\" shto paradhëniet, kreditë ose ndalesat e tjera që mbahen nga paga neto çdo muaj.","en":"Under \"Deductions\" add salary advances, loans or other amounts kept back from the net pay every month."}],"mistakes":[{"sq":"Pa kontratë në fuqi punonjësi nuk hyn në listëpagesë. Rritja e pagës ose pozita e re bëhet me aneks te faqja e kontratës, jo me kontratë të re.","en":"Without a contract in force the person is left out of payroll. A raise or a new position is an annex on the contract page, not a new contract."},{"sq":"Në Kosovë, për punën e dytë fik \"Punëdhënësi kryesor\": paga tatohet me 10% të sheshtë, pa shumë të patatueshme.","en":"In Kosovo, for a second job switch off \"Main employer\": the pay is taxed at a flat 10%, with no tax-free amount."}],"after":{"sq":"Pagat llogariten nga kontrata aktive. Menaxheri i caktuar këtu i sheh kërkesat për leje te \"Vendi im i punës\" dhe mund t'i miratojë.","en":"Payroll uses the active contract. The manager set here sees the leave requests under \"My workplace\" and can approve them."},"related":[{"href":"/hr/payroll","label":"Pagat"},{"href":"/hr/leave","label":"Lejet"}]},{"path":"/hr/payroll/:id","title":"Një listëpagesë mujore","section":null,"keywords":[],"what":{"sq":"Një listëpagesë mujore: bruto, kontributet, tatimi, neto dhe kostoja e punëdhënësit për çdo punonjës.","en":"One monthly payroll: gross, contributions, tax, net and employer cost for each employee."},"steps":[{"sq":"Te \"Të ardhura shtesë\" shto shpërblimet dhe shtesat para se ta llogaritësh.","en":"Under \"Extra earnings\" add bonuses and allowances before calculating."},{"sq":"Kliko \"Llogarit pagat\"; pas çdo ndryshimi kliko \"Rillogarit\".","en":"Click \"Calculate payroll\"; after any change click \"Recalculate\"."},{"sq":"Dikush tjetër, jo ai që e llogariti, klikon \"Mirato listëpagesën\".","en":"Someone other than the person who calculated it clicks \"Approve payroll\"."},{"sq":"Kliko \"Bëje përfundimtare dhe kontabilizo\", pastaj \"Paguaj pagat\" dhe zgjidh llogarinë bankare.","en":"Click \"Make final and book\", then \"Pay salaries\" and choose the bank account."},{"sq":"Te \"Lista për deklaratën\" eksporto listën për deklaratën mujore të pagave.","en":"Under \"Declaration list\" export the list for the monthly payroll declaration."}],"mistakes":[{"sq":"Ai që e llogarit listëpagesën nuk mund ta miratojë vetë: duhet dikush tjetër me të drejtë miratimi.","en":"The person who calculated the payroll cannot approve it: someone else with approval rights must."},{"sq":"Deri sa ta kontabilizosh, mund ta kthesh me \"Kthe në skicë\"; pas kontabilizimit nuk ndryshohet më.","en":"Until it is booked you can send it back with \"Back to draft\"; once booked it no longer changes."}],"after":{"sq":"Pagat dhe kontributet regjistrohen si shpenzim; neto, kontributet dhe tatimi bëhen detyrime për t'u paguar. Punonjësit i shohin fletëpagesat te \"Vendi im i punës\".","en":"Salaries and contributions are booked as expenses; net pay, contributions and tax become amounts to pay. Employees see their payslips under \"My workplace\"."},"related":[]},{"path":"/settings/roles","title":"Rolet dhe të drejtat","section":null,"keywords":[],"what":{"sq":"Rolet dhe të drejtat: çfarë mund të shohë dhe ndryshojë çdo rol në secilën pjesë të programit.","en":"Roles and permissions: what each role may see and change in every part of the program."},"steps":[{"sq":"Kliko një rol majtas për të parë të drejtat e tij.","en":"Click a role on the left to see its permissions."},{"sq":"Rolet \"I gatshëm\" nuk ndryshohen: kliko \"Kopjo si rol të personalizuar\" për të bërë versionin tënd.","en":"\"Built in\" roles cannot change: click \"Copy as custom role\" to make your own version."},{"sq":"Ose kliko \"Rol i ri i personalizuar\", jepi emër dhe shëno për çdo fushë \"Shiko\", \"Ndrysho\", \"Fshi\" ose \"Mirato\".","en":"Or click \"New custom role\", name it and tick \"See\", \"Change\", \"Delete\" or \"Approve\" for each area."},{"sq":"Kliko \"Krijo rolin\", pastaj jepua njerëzve te \"Përdoruesit\" me \"Ndrysho rolet\".","en":"Click \"Create role\", then give it to people under \"Users\" with \"Change roles\"."}],"mistakes":[{"sq":"Një rol i personalizuar fshihet vetëm pasi t'ua heqësh të gjithëve.","en":"A custom role can be deleted only after you take it away from everyone."}],"related":[{"href":"/settings/users","label":"Përdoruesit"}]},{"path":"/pos/till/:registerId","title":"Ekrani i shitjes në arkë","section":null,"keywords":[],"what":{"sq":"Ekrani i shitjes në arkë: skano mallin, merr paratë, printo kuponin.","en":"The till screen: scan the goods, take the money, print the receipt."},"steps":[{"sq":"Skano barkodin ose kërko artikullin me emër; çdo skanim shton një copë.","en":"Scan the barcode or search the item by name; each scan adds one piece."},{"sq":"Për sasi ose zbritje kliko rreshtin dhe zgjidh \"Sasia, zbritja…\".","en":"For a quantity or a discount, click the line and choose \"Quantity, discount…\"."},{"sq":"Kliko \"Paguaj\", zgjidh para në dorë ose kartë dhe shkruaj sa të dha klienti: kusuri del vetë.","en":"Click \"Pay\", choose cash or card and type what the customer gave: the change is shown."},{"sq":"Kliko \"Përfundo shitjen\"; kuponi printohet dhe fillon shitja tjetër.","en":"Click \"Finish the sale\"; the receipt prints and the next sale starts."}],"mistakes":[{"sq":"Kthimi i mallit bëhet me \"Kthim\" nga menyja \"Më shumë\", jo duke shitur me minus.","en":"A return is done with \"Return\" in \"More\", not by selling a negative quantity."},{"sq":"Zbritjet e mëdha kërkojnë menaxherin: thirre para se ta premtosh zbritjen.","en":"Big discounts need the manager: call them before promising the discount."}],"after":{"sq":"Malli zbret nga stoku menjëherë; paratë shkojnë te sirtari i arkës deri në mbylljen e turnit.","en":"The goods leave stock at once; the money goes to the till drawer until the shift is closed."},"related":[]},{"path":"/inventory/products/new","title":"Artikull i ri, me fushat më të nevojshme; të tjerat janë te \"Më shumë\".","section":null,"keywords":[],"what":{"sq":"Artikull i ri, me fushat më të nevojshme; të tjerat janë te \"Më shumë\".","en":"A new item with the fields you need; the rest is under \"More\"."},"steps":[{"sq":"Skano ose shkruaj barkodin, pastaj emrin.","en":"Scan or type the barcode, then the name."},{"sq":"Shkruaj çmimin e shitjes me TVSH; pa TVSH llogaritet vetë.","en":"Type the selling price with VAT; without VAT is worked out."},{"sq":"Nëse malli është tashmë në raft, shkruaj sasinë: hyn si gjendje fillestare.","en":"If the goods are already on the shelf, type the quantity: it goes in as opening stock."}],"mistakes":[{"sq":"Kontrollo normën e TVSH-së (8% ose 18%): ajo del në kupon dhe në librin e shitjeve.","en":"Check the VAT rate (8% or 18%): it goes on the receipt and in the sales book."}],"related":[]},{"path":"/inventory/receipts/new","title":"Pranimi i mallit që vjen te njësia, me ose pa porosi blerjeje.","section":null,"keywords":[],"what":{"sq":"Pranimi i mallit që vjen te njësia, me ose pa porosi blerjeje.","en":"Goods arriving at a unit, with or without a purchase order."},"steps":[{"sq":"Zgjidh furnitorin dhe njësinë ku hyn malli.","en":"Choose the vendor and the unit the goods go into."},{"sq":"Shto rreshtat ose zgjidh porosinë që të mbushen vetë.","en":"Add the lines, or choose the order to fill them in."},{"sq":"Kontrollo sasitë me fletëdërgesën dhe përfundo pranimin.","en":"Check the quantities against the delivery note and finish the receipt."}],"mistakes":[{"sq":"Nëse ke edhe faturën, përdor \"Fatura e blerjes me mall\": pranimi dhe fatura bëhen njëherësh.","en":"If you also have the invoice, use \"Purchase invoice with goods\": receipt and bill in one go."}],"after":{"sq":"Malli hyn në stok me koston e rreshtit; transporti dhe dogana shtohen me \"Shto koston e mbërritjes\".","en":"The goods enter stock at the line cost; freight and customs are added with \"Add arrival costs\"."},"related":[]},{"path":"/inventory/transfers/new","title":"Kalimi i mallit nga një njësi në tjetrën (p.sh. nga depo në dyqan).","section":null,"keywords":[],"what":{"sq":"Kalimi i mallit nga një njësi në tjetrën (p.sh. nga depo në dyqan).","en":"Moving goods from one unit to another (for example from the depot to the shop)."},"steps":[{"sq":"Zgjidh nga ku dhe ku shkon malli.","en":"Choose where the goods come from and where they go."},{"sq":"Shto artikujt dhe sasitë.","en":"Add the items and quantities."},{"sq":"Nise; kur arrin, njësia tjetër e pranon.","en":"Send it; when it arrives, the other unit receives it."}],"mistakes":[],"after":{"sq":"Vlera e stokut nuk ndryshon: malli vetëm ndërron vend.","en":"The stock value does not change: the goods only change place."},"related":[]},{"path":"/inventory/adjustments/new","title":"Korrigjimi i stokut për dëmtim, vjedhje, skadim ose gabim.","section":null,"keywords":[],"what":{"sq":"Korrigjimi i stokut për dëmtim, vjedhje, skadim ose gabim.","en":"Correcting stock for damage, theft, expiry or a mistake."},"steps":[{"sq":"Zgjidh arsyen: kjo del te raporti i humbjeve.","en":"Choose the reason: it shows in the shrinkage report."},{"sq":"Shto artikujt me sasinë që hiqet (minus) ose shtohet (plus).","en":"Add the items with the quantity removed (minus) or added (plus)."},{"sq":"Kontabilizoje; rregullimet e mëdha mund të kërkojnë miratim.","en":"Post it; large adjustments may need approval."}],"mistakes":[{"sq":"Për numërimin e gjithë raftit përdor \"Inventarizimi\": ai i llogarit diferencat vetë.","en":"To count a whole shelf use \"Stock count\": it works out the differences itself."}],"related":[]},{"path":"/wms/counts/:id","title":"Një numërim","section":null,"keywords":[],"what":{"sq":"Një numërim: skano raftin, pastaj çdo artikull në të.","en":"One count: scan the shelf, then every item on it."},"steps":[{"sq":"Skano etiketën e raftit (ose printo fletën e numërimit).","en":"Scan the shelf label (or print the count sheet)."},{"sq":"Skano çdo artikull; çdo skanim shton një copë. Kliko rreshtin për ta shkruar sasinë me dorë.","en":"Scan each item; each scan adds one. Click a line to type the quantity."},{"sq":"Kur mbaron, \"Përfundo numërimin\" e dërgon për shqyrtim.","en":"When done, \"Finish counting\" sends it for review."},{"sq":"Te shqyrtimi shiko çka mungon dhe sa vlen; diferencat e mëdha ktheji për rinumërim.","en":"In the review see what is missing and what it is worth; send big differences back to be counted again."},{"sq":"\"Konfirmo diferencat\" e korrigjon stokun.","en":"\"Confirm differences\" corrects the stock."}],"mistakes":[],"after":{"sq":"Diferencat bëhen një rregullim stoku me arsye \"Numërim\" dhe dalin te Humbjet dhe firot.","en":"The differences become one stock adjustment (reason: count) and show in Shrinkage."},"related":[]},{"path":"/procurement/invoice/new","title":"Fatura e blerjes me mall","section":null,"keywords":[],"what":{"sq":"Fatura e blerjes me mall: malli hyn në stok dhe fatura regjistrohet njëherësh.","en":"Purchase invoice with goods: the goods enter stock and the bill is recorded in one go."},"steps":[{"sq":"Zgjidh furnitorin dhe shkruaj numrin e faturës së tij.","en":"Choose the vendor and type their invoice number."},{"sq":"Skano ose kërko artikujt; shkruaj sasinë dhe çmimin pa TVSH si në faturë.","en":"Scan or search the items; type the quantity and the price without VAT as on the invoice."},{"sq":"Programi propozon çmimet e reja të shitjes sipas marzhës; prano ato që të duken mirë.","en":"The program suggests new selling prices by margin; take the ones that look right."},{"sq":"Nëse paguan në vend, zgjidh arkën ose bankën te \"Pagesa\". Kliko \"Kompleto\".","en":"If you pay on the spot, choose the cash box or bank under \"Payment\". Click \"Complete\"."}],"mistakes":[{"sq":"Totali duhet të dalë si në letër: kontrollo TVSH-në dhe zbritjet para se ta kompletosh.","en":"The total must match the paper: check the VAT and discounts before completing."},{"sq":"Mos e regjistro dy herë të njëjtën faturë: programi paralajmëron kur numri përsëritet.","en":"Do not record the same bill twice: the program warns when the number repeats."}],"after":{"sq":"Malli hyn në stok, fatura shkon te \"Kujt i kam borxh\" dhe në librin e blerjeve.","en":"The goods enter stock; the bill goes to payables and the purchase book."},"related":[]},{"path":"/sales/invoices/:id","title":"Një faturë shitjeje","section":null,"keywords":[],"what":{"sq":"Një faturë shitjeje: klienti, artikujt, afati i pagesës.","en":"One sales invoice: the customer, the items, the due date."},"steps":[{"sq":"Zgjidh klientin: kushtet e pagesës dhe çmimet e tij plotësohen vetë.","en":"Choose the customer: their payment terms and prices fill in by themselves."},{"sq":"Shto rreshtat: skano barkodin ose kërko artikullin, shkruaj sasinë.","en":"Add the lines: scan the barcode or search the item, type the quantity."},{"sq":"Kontrollo totalin dhe kliko \"Kontabilizo faturën\".","en":"Check the total and click \"Post invoice\"."},{"sq":"Printoje ose dërgoje me email; kur paguan klienti, \"Regjistro arkëtimin\".","en":"Print it or email it; when the customer pays, \"Record a receipt\"."}],"mistakes":[{"sq":"Një faturë e kontabilizuar nuk ndryshohet më: për korrigjim bëj notë krediti.","en":"A posted invoice cannot be changed: make a credit note to correct it."},{"sq":"Nëse klienti paguan me pjesë, ndaje faturën në këste te kartela \"Këstet\".","en":"If the customer pays in parts, split the invoice under \"Instalments\"."}],"after":{"sq":"Malli zbret nga stoku (nëse s'ka dalë me dërgesë), fatura shkon te Borxhet, në librin e shitjeve dhe në kontabilitet.","en":"The goods leave stock (unless delivered already); the invoice goes to Debts, the sales book and the books."},"related":[]},{"path":"/finance/payments/:id","title":"Një pagesë","section":null,"keywords":[],"what":{"sq":"Një pagesë: kush pagoi, sa, nga cila llogari, dhe cilat fatura mbyll.","en":"One payment: who paid, how much, from which account, and which invoices it settles."},"steps":[{"sq":"Zgjidh partnerin: dalin faturat e tij të hapura.","en":"Choose the partner: their open invoices appear."},{"sq":"Shkruaj shumën dhe zgjidh bankën ose arkën.","en":"Type the amount and choose the bank or cash box."},{"sq":"Programi e ndan shumën mbi faturat më të vjetra; ndryshoje nëse klienti tha ndryshe.","en":"The program spreads the amount over the oldest invoices; change it if the customer said otherwise."},{"sq":"Kontabilizoje.","en":"Post it."}],"mistakes":[],"related":[]},{"path":"/finance/payables","title":"Kujt i ke borxh","section":null,"keywords":[],"what":{"sq":"Kujt i ke borxh: faturat e furnitorëve të papaguara, sipas vonesës.","en":"What you owe: unpaid vendor bills by how overdue they are."},"steps":[{"sq":"Fillo nga kolonat me vonesë: ato janë më urgjente.","en":"Start with the overdue columns: they are the most urgent."},{"sq":"\"Paguaj disa njëherësh\" hap propozimin e pagesave.","en":"\"Pay several at once\" opens the payment proposal."}],"mistakes":[],"related":[]},{"path":"/partners/:id","title":"Kartela e një klienti ose furnitori","section":null,"keywords":[],"what":{"sq":"Kartela e një klienti ose furnitori: të dhënat, kushtet e pagesës, kontaktet, çmimet e veçanta dhe gjithë dokumentet me të.","en":"The card of one customer or vendor: details, payment terms, contacts, special prices and every document with them."},"steps":[{"sq":"Për biznes, shkruaj NUI-në ose emrin dhe kliko \"Gjeje në regjistrin e bizneseve (ARBK)\": emri, adresa dhe NIPT-i plotësohen vetë.","en":"For a business, type the NUI or name and click \"Find it in the business register (ARBK)\": name, address and tax number fill in by themselves."},{"sq":"Te \"Detajet\", pjesa \"Kushtet e shitjes\": kushtet e pagesës, lista e çmimeve dhe \"Limiti i kreditit (me TVSH)\".","en":"Under \"Details\", the \"Sales terms\" part: payment terms, price list and \"Credit limit (with VAT)\"."},{"sq":"Te \"Kontaktet dhe adresat\" shto personat dhe adresat e dërgesës.","en":"Under \"Contacts and addresses\" add people and delivery addresses."},{"sq":"Te \"Çmime të veçanta\" jep një çmim fiks ose zbritje vetëm për këtë klient.","en":"Under \"Special prices\" give a fixed price or discount just for this customer."},{"sq":"Te \"Kujtesat\" shikon çfarë kujtesash i kanë shkuar dhe mund t'i dërgosh një tani.","en":"Under \"Reminders\" see which reminders were sent and send one now."}],"mistakes":[{"sq":"Pa NIPT/NUI nuk del dot faturë fiskale për biznes.","en":"Without a tax number you cannot issue a fiscal invoice to a business."},{"sq":"Ndryshimi i kushteve të pagesës vlen për dokumentet e reja; të vjetrat mbajnë të tyret.","en":"Changing the payment terms applies to new documents; old ones keep theirs."}],"after":{"sq":"Kushtet dhe çmimet e kartelës plotësohen vetë në çdo ofertë, porosi dhe faturë të re për këtë partner.","en":"The card's terms and prices fill in by themselves on every new quote, order and invoice for this partner."},"related":[{"href":"/finance/receivables","label":"Borxhet"},{"href":"/sales/price-lists","label":"Listat e çmimeve"}]},{"path":"/procurement/bills/:id","title":"Një faturë furnitori","section":null,"keywords":[],"what":{"sq":"Një faturë furnitori: e regjistron siç është shtypur, e kontrollon me porosinë dhe pranimin, pastaj e kontabilizon dhe e paguan.","en":"One vendor bill: enter it as printed, check it against the order and receipt, then post and pay it."},"steps":[{"sq":"Zgjidh furnitorin dhe shkruaj numrin e faturës \"Siç është shtypur në faturën e tyre\", datën dhe afatin.","en":"Choose the vendor and type the bill number \"As printed on their invoice\", the date and due date."},{"sq":"Shto rreshtat me sasi dhe çmim pa TVSH; totalet llogariten vetë.","en":"Add lines with quantity and price without VAT; totals work themselves out."},{"sq":"Nëse vjen nga një porosi, programi e krahason: sasitë dhe çmimet që nuk përputhen dalin të shënuara.","en":"If it comes from an order, the program compares them: quantities and prices that do not match are flagged."},{"sq":"Kliko \"Kontabilizo faturën\". Pastaj \"Paguaj këtë faturë\" ose ndaje në këste.","en":"Click \"Post bill\". Then \"Pay this bill\" or split it into instalments."}],"mistakes":[{"sq":"Fatura me mall që nuk ka kaluar nga pranimi bëhet më mirë te \"Fatura e blerjes me mall\", që të hyjë malli në stok.","en":"A bill with goods that did not go through a receipt is better done in \"Purchase invoice with goods\", so the stock comes in."},{"sq":"\"Kontabilizo gjithsesi…\" kërkon arsye dhe mbetet e shënuar; përdore vetëm kur diferenca është e kuptuar.","en":"\"Post anyway…\" asks for a reason and stays recorded; use it only when the difference is understood."},{"sq":"Fatura e kontabilizuar nuk fshihet; korrigjohet me notë krediti.","en":"A posted bill is not deleted; it is corrected with a credit note."}],"after":{"sq":"Detyrimi ndaj furnitorit hyn në Borxhe, TVSH-ja e zbritshme në librin e blerjeve dhe fatura del te Propozimi i pagesave sipas afatit.","en":"What you owe goes into Debts, the deductible VAT into the purchase book, and the bill shows in the Payment proposal by its due date."},"related":[{"href":"/finance/payment-proposal","label":"Propozimi i pagesave"},{"href":"/procurement/invoice/new","label":"Fatura me mall"}]},{"path":"/procurement/requisitions/:id","title":"Një kërkesë për blerje","section":null,"keywords":[],"what":{"sq":"Një kërkesë për blerje: punëtori shkruan çfarë i duhet, menaxheri e miraton dhe blerjet e kthejnë në porosi te furnitorët.","en":"One purchase requisition: a worker writes what is needed, a manager approves it and purchasing turns it into orders to vendors."},"steps":[{"sq":"Shto artikujt: produkt nga katalogu ose përshkrim i lirë, sasia dhe kostoja e përafërt pa TVSH.","en":"Add items: a catalogue product or a free description, the quantity and an estimated cost without VAT."},{"sq":"Vendos \"Duhet deri më\", depon dhe arsyen.","en":"Set \"Needed by\", the warehouse and the reason."},{"sq":"Kliko \"Dërgo për miratim\". Miratuesi e sheh te \"Për miratim\".","en":"Click \"Submit for approval\". The approver sees it under \"Approvals\"."},{"sq":"Pas miratimit, blerjet klikojnë \"Krijo porosi blerjeje\": një porosi për çdo furnitor të sugjeruar.","en":"Once approved, purchasing clicks \"Create purchase orders\": one order per suggested vendor."}],"mistakes":[{"sq":"Shiko sasinë \"në stok\" dhe \"tashmë në porosi\" para se ta kërkosh, që të mos blihet dy herë.","en":"Check the \"on hand\" and \"already on order\" quantities before asking, so it is not bought twice."}],"after":{"sq":"Porositë e krijuara lidhen me kërkesën; kur malli vjen, pranohet nga porosia.","en":"The orders created are linked to the requisition; when the goods arrive they are received from the order."},"related":[{"href":"/approvals","label":"Për miratim"},{"href":"/procurement/orders","label":"Porositë e blerjes"}]},{"path":"/manufacturing/boms/:id","title":"Receta e një produkti","section":null,"keywords":[],"what":{"sq":"Receta e një produkti: nga çfarë përbërësish bëhet, me sa firo dhe me cilët hapa pune. Prej saj del kostoja për njësi.","en":"A product's recipe: which components it is made of, with how much waste and which work steps. Its cost per unit comes from it."},"steps":[{"sq":"Zgjidh produktin që bëhet dhe \"Sasia e serisë\": sa njësi del nga një seri.","en":"Choose the product made and the \"Batch quantity\": how many units one batch makes."},{"sq":"Kliko \"Shto përbërës\" për çdo lëndë, me sasinë për seri dhe \"Firo %\".","en":"Click \"Add component\" for each material, with the quantity per batch and \"Waste %\"."},{"sq":"Kliko \"Shto hap\" për punën: qendra e punës dhe minutat për njësi. Puna dhe shpenzimet e përgjithshme llogariten nga qendra.","en":"Click \"Add step\" for the work: the work center and minutes per unit. Labour and overhead come from the center."},{"sq":"Kliko \"Ruaj recetën\" dhe shiko \"Ndarja e kostos (pa TVSH)\".","en":"Click \"Save recipe\" and look at the \"Cost breakdown (without VAT)\"."}],"mistakes":[{"sq":"Si \"Set\" përbërësit dalin nga stoku kur shitet produkti; si recetë prodhimi dalin vetëm me urdhër pune.","en":"As a \"Kit\" the parts leave stock when the product is sold; as a production recipe they leave only with a work order."},{"sq":"Pa qendër pune nuk shtohen dot hapa; krijoje te Qendrat e punës.","en":"Without a work center you cannot add steps; create one under Work centers."}],"after":{"sq":"Urdhrat e punës për këtë produkt marrin përbërësit dhe hapat nga kjo recetë.","en":"Work orders for this product take the components and steps from this recipe."},"related":[{"href":"/manufacturing/orders","label":"Urdhrat e punës"},{"href":"/manufacturing/work-centers","label":"Qendrat e punës"}]},{"path":"/inventory/landed-costs/:id","title":"Kostot e importit (transport, doganë, spedicion) që shtohen te vlera e mallit të","section":null,"keywords":[],"what":{"sq":"Kostot e importit (transport, doganë, spedicion) që shtohen te vlera e mallit të pranuar, që kostoja e çdo artikulli të jetë e vërtetë.","en":"Import costs (freight, customs, forwarding) added to the value of goods received, so each item's cost is the real one."},"steps":[{"sq":"Zgjidh \"Pranimet ku zbatohet kjo kosto\".","en":"Choose the \"Receipts this cost applies to\"."},{"sq":"Kliko \"Shto kosto\" për çdo shpenzim: transport, taksa doganore, spedicion, me shumën pa TVSH.","en":"Click \"Add charge\" for each cost: freight, customs duty, forwarding, with the amount without VAT."},{"sq":"Për doganën plotëso deklaratën doganore (numri DUD) dhe TVSH-në e importit të paguar.","en":"For customs fill in the customs declaration (DUD number) and the import VAT paid."},{"sq":"Zgjidh \"Shpërnda sipas\" (vlerë, sasi, peshë…) dhe kliko \"Shpërnda dhe regjistro\".","en":"Choose \"Split by\" (value, quantity, weight…) and click \"Spread and record\"."}],"mistakes":[{"sq":"TVSH e importit nuk hyn në koston e mallit: ajo zbritet si TVSH hyrëse.","en":"Import VAT does not go into the goods' cost: it is deducted as input VAT."},{"sq":"Pjesa që i takon mallit të shitur tashmë shkon në kosto të mallit të shitur, jo në stok.","en":"The share for goods already sold goes to cost of goods sold, not to stock."}],"after":{"sq":"Kostoja shtohet te shtresat FIFO të vetë atij pranimi, ndaj marzhat e shitjeve të ardhshme dalin të sakta.","en":"The cost is added to the FIFO layers of that very receipt, so margins on future sales come out right."},"related":[{"href":"/inventory/receipts","label":"Pranimet"}]},{"path":"/inventory/products/:id","title":"Kartela e një produkti","section":null,"keywords":[],"what":{"sq":"Kartela e një produkti: çmimi, TVSH-ja, sa ka në çdo depo, varianti dhe barkodet, ambalazhet dhe kur duhet riporositur.","en":"One product's card: price, VAT, how much is in each warehouse, variants and barcodes, packaging and when to reorder."},"steps":[{"sq":"Kliko \"Ndrysho\" për emrin, kategorinë, çmimin e shitjes dhe TVSH-në.","en":"Click \"Edit\" for the name, category, selling price and VAT."},{"sq":"Te \"Stoku\" shikon sa ka në çdo depo, raft dhe lot, me koston mesatare.","en":"Under \"Stock\" see how much is in each warehouse, bin and lot, with the average cost."},{"sq":"Te \"Variantet dhe barkodet\" shto barkodin e prodhuesit ose \"Krijo kod të brendshëm\" për mallin pa barkod.","en":"Under \"Variants & barcodes\" add the maker's barcode or \"Generate in-store code\" for goods without one."},{"sq":"Te \"Pikat e riporositjes\" vendos kur bie poshtë sasia dhe deri sa të porositet; Rimbushja i propozon vetë.","en":"Under \"Reorder points\" set when the quantity is too low and how much to order up to; Replenishment suggests them."},{"sq":"Te \"Kartela e artikullit\" sheh çdo hyrje dhe dalje me dokumentin e saj.","en":"Under \"Item card\" see every in and out with its document."}],"mistakes":[{"sq":"Njësia, lloji dhe gjurmimi me lot nuk ndryshohen pasi produkti ka lëvizje; krijo produkt të ri nëse duhet.","en":"Unit, type and lot tracking cannot change once the product has movements; make a new product if needed."}],"after":{"sq":"Ndryshimi i çmimit ruhet te \"Historiku i çmimit\" dhe vlen menjëherë në arkë dhe në dokumentet e reja.","en":"A price change is kept in \"Price history\" and applies at once at the till and on new documents."},"related":[{"href":"/inventory/labels","label":"Etiketat"},{"href":"/procurement/replenishment","label":"Rimbushja"}]},{"path":"/sales/deliveries/:id","title":"Një dërgesë te klienti","section":null,"keywords":[],"what":{"sq":"Një dërgesë te klienti: çfarë merret nga depo dhe kur del malli. Kur përfundon, stoku zbret dhe kostoja e mallit kontabilizohet.","en":"One delivery to a customer: what is taken from the warehouse and when the goods leave. When completed, stock goes down and the cost of goods is booked."},"steps":[{"sq":"Kontrollo \"Merret nga\" (depo), datën dhe rreshtat me sasi; për mall me lot zgjidh lotin.","en":"Check \"Pick from\" (the warehouse), the date and the lines with quantities; for lot goods choose the lot."},{"sq":"Shkruaj shënimet për shoferin dhe numrin e gjurmimit nëse e dërgon me korrier.","en":"Write notes for the driver and the tracking number if a courier takes it."},{"sq":"Kliko \"Përfundo dërgesën\" kur malli largohet.","en":"Click \"Complete delivery\" when the goods leave."}],"mistakes":[{"sq":"Mos e përfundo para se malli të dalë realisht: stoku zbret menjëherë.","en":"Do not complete it before the goods really leave: stock goes down at once."}],"after":{"sq":"Nga porosia mund të bësh faturën për sasinë e dërguar; dërgesa e përfunduar nuk fshihet.","en":"From the order you can invoice the quantity delivered; a completed delivery is not deleted."},"related":[{"href":"/sales/deliveries","label":"Dërgesat"}]},{"path":"/finance/accounts/:id","title":"Kartela e një llogarie kontabël","section":null,"keywords":[],"what":{"sq":"Kartela e një llogarie kontabël: gjendja fillestare, çdo veprim debi dhe kredi me dokumentin e tij, dhe gjendja në fund.","en":"One ledger account's card: the opening balance, every debit and credit with its document, and the closing balance."},"steps":[{"sq":"Zgjidh periudhën me \"Nga\" dhe \"Deri\".","en":"Choose the period with \"From\" and \"To\"."},{"sq":"Kliko një rresht për të hapur regjistrimin ose dokumentin që e krijoi.","en":"Click a line to open the entry or the document that made it."},{"sq":"Me \"Ndrysho\" ndryshon emrin, grupin dhe seksionin e fluksit të parasë.","en":"With \"Edit\" change the name, group and cash flow section."}],"mistakes":[{"sq":"Kodi i llogarisë me lëvizje nuk ndryshohet; regjistrimet gabim korrigjohen me regjistrim të ri.","en":"An account with movements keeps its code; wrong entries are fixed with a new entry."}],"related":[{"href":"/finance/accounts","label":"Plani kontabël"},{"href":"/finance/account-card","label":"Kartela e llogarisë"}]},{"path":"/pos/sessions/:id","title":"Një ndërrim arke","section":null,"keywords":[],"what":{"sq":"Një ndërrim arke: kush e hapi, sa para kishte në fillim, çdo kupon, pagesat sipas mënyrës, diferenca e parave dhe raporti Z.","en":"One till shift: who opened it, the opening cash, every receipt, payments by method, the cash difference and the Z-report."},"steps":[{"sq":"Shiko \"Diferenca e parave\": sa u numërua kundrejt sa pritej në sirtar.","en":"Look at \"Cash difference\": what was counted against what was expected in the drawer."},{"sq":"Te \"Kupona\" hap një kupon për ta printuar përsëri ose për të bërë kthim.","en":"Under \"Receipts\" open one to reprint it or make a refund."},{"sq":"Te raporti Z kliko \"Printo raportin Z\" për letrën e mbylljes.","en":"On the Z-report click \"Print Z-report\" for the closing slip."},{"sq":"Te \"Kontabiliteti\" sheh si u regjistrua ndërrimi në libra.","en":"Under \"Accounting\" see how the shift was booked."}],"mistakes":[{"sq":"Diferenca e madhe e parave duhet sqaruar me arkëtarin të njëjtën ditë.","en":"A large cash difference should be cleared up with the cashier the same day."}],"after":{"sq":"Shitjet e ndërrimit hyjnë në librin e shitjeve dhe paratë kalojnë në arkë ose në kasafortë.","en":"The shift's sales go into the sales book and the cash moves into the cash box or safe."},"related":[{"href":"/finance/z-reports","label":"Z-raportet"}]},{"path":"/hr/contracts/:id","title":"Një kontratë pune ose aneks","section":null,"keywords":[],"what":{"sq":"Një kontratë pune ose aneks: teksti që printohet, kushtet, kopja e nënshkruar dhe historia e punonjësit.","en":"One employment contract or annex: the text to print, the terms, the signed copy and the person's history."},"steps":[{"sq":"Kontrollo tekstin. Kur është skicë, me \"Ndrysho tekstin\" e përshtat dhe me \"Ndrysho kushtet\" ndryshon pagën, datat ose pozitën.","en":"Check the text. While it is a draft, \"Edit the text\" changes the wording and \"Change terms\" changes pay, dates or position."},{"sq":"Kliko \"Printo\", nënshkruajeni të dy palët, pastaj \"Shëno si të nënshkruar\". Nga ajo ditë kontrata nuk ndryshon më.","en":"Click \"Print\", have both sides sign, then \"Mark as signed\". From then on the contract does not change."},{"sq":"Te \"Kopja e nënshkruar\" ngarko skanimin ose foton e kontratës së nënshkruar.","en":"Under \"Signed copy\" upload the scan or photo of the signed contract."},{"sq":"Për rritje page, pozitë të re ose orar tjetër kliko \"Aneks\"; për kontratë me afat kliko \"Zgjat\".","en":"For a raise, a new position or other hours click \"Annex\"; for a fixed-term contract click \"Extend\"."},{"sq":"Kur punonjësi largohet, kliko \"Ndërprit kontratën\": arsyeja, data e njoftimit dhe dita e fundit. Pastaj printo njoftimin.","en":"When the person leaves, click \"End the contract\": the reason, the notice date and the last day. Then print the notice."}],"mistakes":[{"sq":"Afati i njoftimit varet nga vjetërsia; programi e llogarit sipas ligjit dhe të paralajmëron kur është më i shkurtër.","en":"The notice period depends on length of service; the program works it out by law and warns you when it is shorter."},{"sq":"Para fillimit të punës punonjësi duhet deklaruar në administratën tatimore (ATK / DPT), të paktën një ditë më parë.","en":"Before work starts, the employee must be declared to the tax office (ATK / DPT), at least one day before."}],"after":{"sq":"Paga paguan sipas kontratës në fuqi; kur aneksi fillon në mes të muajit, secila pjesë paguan ditët e veta.","en":"Payroll pays by the contract in force; when an annex starts mid-month, each part pays its own days."},"related":[{"href":"/hr/payroll","label":"Pagat"}]},{"path":"/tasks/setup","title":"Detyrat që përsëriten vetë, modelet (shumë detyra me një klik) dhe detyrat që pr","section":null,"keywords":[],"what":{"sq":"Detyrat që përsëriten vetë, modelet (shumë detyra me një klik) dhe detyrat që programi i krijon nga ajo që ndodh.","en":"Tasks that repeat by themselves, templates (many tasks with one click) and tasks the program makes from what happens."},"steps":[{"sq":"Te \"Që përsëriten\" shto p.sh. \"Hapja e dyqanit\" çdo ditë pune, me pikat e kontrollit një për rresht.","en":"Under \"Repeating\" add e.g. \"Opening the shop\" every working day, with its steps one per line."},{"sq":"Te \"Modelet\" bëj një grup detyrash (p.sh. \"Punëtori i ri\") dhe nise me \"Fillo\" kur të duhet.","en":"Under \"Templates\" make a set of tasks (e.g. \"New employee\") and start it with \"Start\" when needed."},{"sq":"Te \"Automatik\" ndiz rastet që do: faturat e vonuara, diferencat në arkë, stoku i ulët, lotet, kontratat, afatet tatimore, kontaktet e reja.","en":"Under \"Automatic\" switch on what you want: late invoices, till differences, low stock, lots, contracts, tax deadlines, new contacts."}],"mistakes":[{"sq":"Nisni me pak automatizime: shumë detyra automatike bëhen zhurmë dhe njerëzit ndalojnë së lexuari.","en":"Start with a few automations: too many automatic tasks become noise and people stop reading."}],"after":{"sq":"Programi kontrollon çdo orë dhe nuk krijon detyrë të dytë për të njëjtën gjë sa kohë e para është e hapur.","en":"The program checks every hour and never makes a second task for the same thing while the first is open."},"related":[{"href":"/tasks","label":"Detyrat"}]},{"path":"/skaner","title":"DrisPRO Skaner","section":null,"keywords":[],"what":{"sq":"DrisPRO Skaner: programi për pajisjen e dorës (Zebra). Ka vetëm ekranet e skanimit, me butona të mëdhenj, dhe punon edhe pa internet.","en":"DrisPRO Skaner: the program for the handheld (Zebra). It has only the scanning screens, with large buttons, and works without internet too."},"steps":[{"sq":"Në pajisje hap Chrome te erp.dris-ks.com/skaner dhe hyr me përdoruesin e saj.","en":"On the device open Chrome at erp.dris-ks.com/skaner and log in with its user."},{"sq":"Shtyp \"Instalo DrisPRO Skaner në këtë pajisje\" (ose ⋮ → Instalo aplikacionin). Del ikona \"Skaner\" me shiritin portokalli.","en":"Press \"Install DrisPRO Skaner on this device\" (or ⋮ → Install app). The \"Skaner\" icon with the orange bar appears."},{"sq":"Lart zgjidh njësinë ku punon pajisja. Tastet 1–9 hapin ekranet.","en":"At the top choose the unit the device works in. Keys 1–9 open the screens."},{"sq":"Te DataWedge lidhe profilin me aplikacionin Skaner dhe ndiz \"Send ENTER\".","en":"In DataWedge link the profile to the Skaner app and switch on \"Send ENTER\"."}],"mistakes":[{"sq":"Përdoruesi i pajisjes le të ketë rolin e magazinierit: sheh vetëm ekranet e magazinës, jo financat apo pagat.","en":"Give the device user the warehouse role: they see only the warehouse screens, not finance or payroll."}],"after":{"sq":"Çmimi i ri që shkruhet te \"Çmimi\" shkon te nivelimi \"Nga skaneri\"; ndryshon kur menaxheri e kontabilizon.","en":"A new price typed under \"Price\" goes onto the \"From the scanner\" levelling; it changes when a manager posts it."},"related":[{"href":"/inventory/check","label":"Kontrollo artikullin"},{"href":"/wms/counts","label":"Inventarizimi"}]}]
